class Tooltip:
    """Hover tooltip for any widget: shows after a short delay so tips do
    not flash while the mouse crosses the panel. The top-bar Helper switch
    flips the class-wide `enabled` flag to silence every tip at once."""
    enabled = True
    DELAY_MS = 450
    # Tip colours, re-derived from the active theme by _apply_brand. They
    # start as the shipped light-theme pair so a tip raised before the
    # first _apply_brand still reads.
    BG = "#ffffff"
    FG = "#201b16"
    EDGE = "#555555"

    def __init__(self, widget, text):
        self.widget = widget
        self.text = text
        self.tip = None
        self._job = None
        widget.bind("<Enter>", self._schedule)
        widget.bind("<Leave>", self._hide)
        widget.bind("<ButtonPress>", self._hide, add="+")
        # A tooltipped row can go away while the pointer rests on it: the
        # formula list and the notch list both rebuild in place. Without
        # this, the pending after-job fires on a dead widget, and a tip
        # already on screen outlives the row it belongs to.
        widget.bind("<Destroy>", self._hide, add="+")

    def _schedule(self, _=None):
        if not Tooltip.enabled or not self.text:
            return
        self._cancel()
        self._job = self.widget.after(self.DELAY_MS, self._show)

    def _cancel(self):
        if self._job is not None:
            try:
                self.widget.after_cancel(self._job)
            except Exception:
                pass
            self._job = None

    def _show(self, _=None):
        self._job = None
        if self.tip or not self.text or not Tooltip.enabled:
            return
        x = self.widget.winfo_rootx() + 18
        y = self.widget.winfo_rooty() + self.widget.winfo_height() + 4
        self.tip = tk.Toplevel(self.widget)
        self.tip.wm_overrideredirect(True)
        self.tip.configure(bg=Tooltip.EDGE)  # 1px frame around the tip
        tk.Label(self.tip, text=self.text, justify="left", wraplength=300,
                 background=Tooltip.BG, foreground=Tooltip.FG, relief="flat",
                 font="TkTooltipFont", padx=8, pady=5).pack(padx=1, pady=1)
        # clamp to the screen so tips near the right/bottom edge stay whole
        self.tip.update_idletasks()
        tw, th = self.tip.winfo_reqwidth(), self.tip.winfo_reqheight()
        sw, sh = self.tip.winfo_screenwidth(), self.tip.winfo_screenheight()
        if x + tw > sw - 8:
            x = max(8, sw - tw - 8)
        if y + th > sh - 8:
            y = self.widget.winfo_rooty() - th - 6
        self.tip.wm_geometry("+%d+%d" % (x, y))

    def _hide(self, _=None):
        self._cancel()
        if self.tip:
            self.tip.destroy(); self.tip = None


class BrandScale(tk.Canvas):
    """Brand slider: rounded trough, filled progress, ROUND knob (the
    classic Scale's square knob read as ambiguous; sv_ttk's trough images
    cannot follow the theme). Drag anywhere or click to jump."""

    def __init__(self, parent, from_=0.0, to=1.0, variable=None,
                 command=None, **kw):
        super().__init__(parent, height=20, highlightthickness=0, bd=0,
                         bg=kw.get("bg", "#f1eee6"))
        self.lo, self.hi = float(from_), float(to)
        self.var = variable
        self.command = command
        self._trough = "#d9d5c9"
        self._fillc = "#1D3EC0"
        self._knob = "#1D3EC0"
        self._ring = "#f1eee6"
        self._hov = None
        self._hot = False
        self._tr = None
        self.configure(cursor="hand2")
        self.bind("<Configure>", lambda e: self._draw())
        self.bind("<Button-1>", self._jump)
        self.bind("<B1-Motion>", self._jump)
        self.bind("<Enter>", lambda e: self._set_hot(True))
        self.bind("<Leave>", lambda e: self._set_hot(False))
        if variable is not None:
            self._tr = variable.trace_add("write", lambda *a: self._draw())
        self._draw()

    def destroy(self):
        try:
            if self.var is not None and self._tr:
                self.var.trace_remove("write", self._tr)
        except Exception:
            pass
        super().destroy()

    def retint(self, bg, trough, fill, knob, ring, hov=None):
        try:
            self.configure(bg=bg)
        except tk.TclError:
            return
        self._trough, self._fillc = trough, fill
        self._knob, self._ring = knob, ring
        self._hov = hov
        self._draw()

    def _set_hot(self, hot):
        self._hot = hot
        self._draw()

    def _frac(self):
        try:
            v = float(self.var.get())
        except Exception:
            v = self.lo
        span = (self.hi - self.lo) or 1.0
        return min(1.0, max(0.0, (v - self.lo) / span))

    def _jump(self, e):
        w = max(self.winfo_width(), 1)
        pad = 9
        f = min(1.0, max(0.0, (e.x - pad) / max(w - 2 * pad, 1)))
        v = self.lo + f * (self.hi - self.lo)
        if self.var is not None:
            self.var.set(v)
        if self.command:
            self.command(v)

    def _draw(self):
        try:
            self.delete("all")
        except tk.TclError:
            return
        w = max(self.winfo_width(), 30)
        pad, cy, r = 9, 10, 7
        f = self._frac()
        kx = pad + f * (w - 2 * pad)
        self.create_line(pad, cy, w - pad, cy, width=4, fill=self._trough,
                         capstyle="round")
        if kx > pad + 1:
            self.create_line(pad, cy, kx, cy, width=4, fill=self._fillc,
                             capstyle="round")
        # square knob: the brand's marker shape, unambiguous to grab
        kc = (self._hov or self._knob) if self._hot else self._knob
        self.create_rectangle(kx - r, cy - r, kx + r, cy + r, fill=kc,
                              outline=self._ring, width=2)


def unit_x(result, unit):
    """X array for a result in the chosen unit ('wl' nm, 'wn' cm^-1, 'ev')."""
    if unit == "wn":
        return result["wn"]
    if unit == "ev":
        return np.where(result["wl"] > 0, EV_NM / result["wl"], np.nan)
    return result["wl"]


def unit_label(unit):
    return {"wl": "Wavelength (nm)", "wn": "Wavenumber (cm$^{-1}$)",
            "ev": "Photon energy (eV)"}[unit]


def _conv(frm, to):
    """forward/inverse functions mapping primary-axis values to a top-axis unit.

    nm_to and to_nm have identical bodies on purpose: every unit here maps
    to/from nm by the same self-inverse map (identity, or x -> C/x), so one
    formula converts in either direction."""
    def nm_to(v, u):
        with np.errstate(divide="ignore", invalid="ignore"):
            if u == "wl": return v
            if u == "wn": return 1e7 / v
            return EV_NM / v
    def to_nm(v, u):
        with np.errstate(divide="ignore", invalid="ignore"):
            if u == "wl": return v
            if u == "wn": return 1e7 / v
            return EV_NM / v
    fwd = lambda x: nm_to(to_nm(x, frm), to)
    inv = lambda x: nm_to(to_nm(x, to), frm)
    return fwd, inv


class BrandCard(tk.Canvas):
    """Flat card: panel-colored ground with a thin rounded border whose top
    edge opens around an optional title (classic labelframe look, drawn).
    Content goes in .body. grow='x' sizes the card to its content; grow=
    'both' lets the interior fill whatever the card is given."""

    def __init__(self, master, grow="x", pad=8, radius=9, **kw):
        super().__init__(master, highlightthickness=0, bd=0, **kw)
        self.grow, self.pad, self.radius = grow, pad, radius
        self._border = "#b9b0a0"
        self._title = None
        self._title_anchor = "w"
        self._twin = None
        self.body = ttk.Frame(self)
        self._win = self.create_window((pad, pad), window=self.body,
                                       anchor="nw")
        if grow == "x":
            self.body.bind("<Configure>", lambda e: self._refresh())
        self.bind("<Configure>", self._layout)
        self.bind("<Map>", lambda e: self.after_idle(self._refresh))

    def set_title(self, widget, anchor="w"):
        """Mount a title widget (child of this canvas) on the border line."""
        self._title = widget
        self._title_anchor = anchor
        self._twin = self.create_window((self.pad + 10, 0), window=widget,
                                        anchor="nw")
        widget.bind("<Configure>", lambda e: self._refresh())
        self.after_idle(self._refresh)

    def _refresh(self):
        self._fit_height()
        self._layout()

    def _top_inset(self):
        if self._title is None:
            return self.pad
        try:
            return self._title.winfo_reqheight() + 3
        except tk.TclError:
            return self.pad

    def _fit_height(self, _e=None):
        if self.grow != "x":
            return
        need = self._top_inset() + self.body.winfo_reqheight() + self.pad
        try:
            if int(self.cget("height")) != need:
                self.configure(height=need)
        except tk.TclError:
            pass
        self._fit_width()

    def _fit_width(self, _e=None):
        """Ask for the width the content needs, the way _fit_height asks
        for the height.

        A tk.Canvas requests a stock 378 px however wide its contents
        are. In the right panel nothing noticed: the pane width is set
        by _pane_widths and the card just fills it. It bites the moment
        a DIALOG is sized from winfo_reqwidth (_fit_dialog): the Quick
        Access customizer's two explainer paragraphs were handed 392 px
        for a 420 px wraplength and ran off the right edge, with only a
        VERTICAL scroll host to reach them - rule 66's "nothing may be
        unreachable" in its horizontal half.

        Setting the request cannot feed back on itself: making the card
        wider re-lays the body window out but does not change what the
        body's children ASK for (a wraplength is a fixed number), so
        body.winfo_reqwidth() is a fixed point.
        """
        if self.grow != "x":
            return
        try:
            need = self.body.winfo_reqwidth() + 2 * self.pad
            if need > 8 and int(self.cget("width")) != need:
                self.configure(width=need)
        except tk.TclError:
            pass

    def _layout(self, _e=None):
        w, h = self.winfo_width(), self.winfo_height()
        if w < 8 or h < 8:
            return
        top = self._top_inset()
        self.coords(self._win, self.pad, top)
        self.itemconfigure(self._win, width=w - 2 * self.pad)
        if self.grow == "both":
            # Floor at 1, never 8: a collapsed card is only top_inset + pad
            # tall, so an 8 px body window would sit ON the drawn bottom
            # border (y = h - 2) and hide it. The pad IS the border's room.
            self.itemconfigure(self._win, height=max(1, h - top - self.pad))
        self._draw_border(w, h)

    def _draw_border(self, w, h):
        self.delete("card")
        r, c = self.radius, self._border
        x0, x1, y1 = 1, w - 2, h - 2
        ty = 1
        gap = None
        if self._title is not None:
            try:
                th = self._title.winfo_reqheight()
                tw = self._title.winfo_reqwidth()
            except tk.TclError:
                th = tw = 0
            ty = max(1, th // 2)
            if self._title_anchor == "center":
                tx = max(self.pad + 6, (w - tw) // 2)
            else:
                tx = self.pad + 10
            self.coords(self._twin, tx, 0)
            gap = (tx - 5, tx + tw + 5)
        for box, start in (((x0, ty, x0 + 2 * r, ty + 2 * r), 90),
                           ((x1 - 2 * r, ty, x1, ty + 2 * r), 0),
                           ((x1 - 2 * r, y1 - 2 * r, x1, y1), 270),
                           ((x0, y1 - 2 * r, x0 + 2 * r, y1), 180)):
            self.create_arc(box, start=start, extent=90, style="arc",
                            outline=c, width=1, tags="card")
        if gap is None:
            self.create_line(x0 + r, ty, x1 - r, ty, fill=c, width=1,
                             tags="card")
        else:
            if gap[0] > x0 + r + 2:
                self.create_line(x0 + r, ty, gap[0], ty, fill=c, width=1,
                                 tags="card")
            if gap[1] < x1 - r - 2:
                self.create_line(gap[1], ty, x1 - r, ty, fill=c, width=1,
                                 tags="card")
        for ln in ((x0 + r, y1, x1 - r, y1),
                   (x0, ty + r, x0, y1 - r), (x1, ty + r, x1, y1 - r)):
            self.create_line(*ln, fill=c, width=1, tags="card")

    def retint(self, bg, border):
        self._border = border
        try:
            self.configure(background=bg)
        except tk.TclError:
            pass
        self._layout()


def _rb_dispatch(meth):
    """Class-bindtag handler: route the event to the RoundButton it hit."""
    def _h(e):
        w = getattr(e, "widget", None)
        if isinstance(w, RoundButton):
            return getattr(w, meth)(e)
        return None
    return _h


class RoundButton(tk.Canvas):
    """The house primary button: a drawn rounded rectangle with a centered
    label (and an optional icon on its left), sized to a REAL ttk.Button.

    sv_ttk's Accent.TButton is an image assembly and cannot take the
    per-theme triad, while a plain tk.Button is square-cornered and a notch
    taller than the ttk buttons beside it. This is both at once: ttk
    geometry, brand color. The corners are drawn the BrandCard way (pieslice
    arcs plus two rectangles), radius 4 to match sv_ttk.

    It answers to the tk.Button option names the call sites already use
    (text / command / state / image / compound / font / bg / fg /
    activebackground / activeforeground / disabledforeground / padx / pady)
    so _tint_brand_button, _update_profile_btn, _update_data_btn and the
    Run<->Cancel swap keep working untouched. Hover / press / focus are
    bound on a private BINDTAG, not on the widget, because Tooltip binds
    <Enter> without add="+" and would otherwise wipe them.
    """

    TAG = "SpartaRoundBtn"
    _class_bound = False
    _OWN = frozenset((
        "text", "command", "state", "image", "compound", "font",
        "bg", "background", "fg", "foreground", "activebackground",
        "activeforeground", "disabledforeground", "disabledbackground",
        "padx", "pady", "radius", "chrome", "focuscolor", "outline",
        "outlinewidth", "gap", "matchttk", "minwidth"))

    def __init__(self, master, app=None, **kw):
        self._o = {"text": "", "command": None, "state": "normal",
                   "image": None, "compound": "left", "font": None,
                   "bg": "#1D3EC0", "fg": "#ffffff",
                   "activebackground": None, "activeforeground": None,
                   "disabledforeground": None, "disabledbackground": None,
                   "padx": None, "pady": None, "radius": 4,
                   "chrome": None, "focuscolor": None, "outline": None,
                   "outlinewidth": 2, "gap": None, "matchttk": True,
                   "minwidth": 0}
        self._app = app
        self._fobj = None
        self._hot = self._down = self._ring = False
        mine = {k: kw.pop(k) for k in list(kw) if k in self._OWN}
        tk.Canvas.__init__(self, master, highlightthickness=0, bd=0,
                           takefocus=1, **kw)
        cls = type(self)
        if not cls._class_bound:
            cls._class_bound = True
            for seq, meth in (("<Enter>", "_ev_enter"),
                              ("<Leave>", "_ev_leave"),
                              ("<ButtonPress-1>", "_ev_press"),
                              ("<ButtonRelease-1>", "_ev_release"),
                              ("<FocusIn>", "_ev_focus_in"),
                              ("<FocusOut>", "_ev_focus_out"),
                              ("<Key-space>", "_ev_key"),
                              ("<Return>", "_ev_key"),
                              ("<KP_Enter>", "_ev_key"),
                              ("<Configure>", "_ev_configure")):
                self.bind_class(cls.TAG, seq, _rb_dispatch(meth))
        _bt = list(self.bindtags())
        if cls.TAG not in _bt:
            _bt.insert(1, cls.TAG)          # after the widget's own tag
            self.bindtags(tuple(_bt))
        self.configure(**mine)

    # ---- option plumbing (tk.Button names in, canvas drawing out) --------
    def configure(self, cnf=None, **kw):
        if isinstance(cnf, dict):
            kw = dict(cnf, **kw)
            cnf = None
        o = getattr(self, "_o", None)
        if o is None:                       # pre-__init__ safety
            return tk.Canvas.configure(self, cnf, **kw)
        if cnf is None and not kw:
            return tk.Canvas.configure(self)
        mine = {}
        for k in list(kw):
            if k in self._OWN:
                mine[k] = kw.pop(k)
        if "background" in mine:
            mine["bg"] = mine.pop("background")
        if "foreground" in mine:
            mine["fg"] = mine.pop("foreground")
        if kw or cnf is not None:
            tk.Canvas.configure(self, cnf, **kw)
        if mine:
            if "font" in mine:
                self._fobj = self._resolve_font(mine["font"])
            o.update(mine)
            self._sync()
        return None

    config = configure

    def cget(self, key):
        o = getattr(self, "_o", None)
        if o is not None:
            k = {"background": "bg", "foreground": "fg"}.get(key, key)
            if k in self._OWN:
                return o.get(k)
        return tk.Canvas.cget(self, key)

    __getitem__ = cget

    def __setitem__(self, key, value):
        self.configure(**{key: value})

    def invoke(self):
        """Run the command, exactly as tk.Button.invoke does."""
        if self._o["state"] == "disabled":
            return None
        cmd = self._o["command"]
        return cmd() if callable(cmd) else None

    # ---- colors ----------------------------------------------------------
    def _rgb(self, col):
        try:
            r, g, b = self.winfo_rgb(col)
        except tk.TclError:
            return None
        return (r // 256, g // 256, b // 256)

    def _mix(self, c1, c2, t):
        a, b = self._rgb(c1), self._rgb(c2)
        if a is None or b is None:
            return c1
        return "#%02x%02x%02x" % tuple(
            int(round(x + (y - x) * t)) for x, y in zip(a, b))

    def _dim(self, col, f):
        a = self._rgb(col)
        if a is None:
            return col
        return "#%02x%02x%02x" % tuple(
            max(0, min(255, int(x * f))) for x in a)

    def _chrome(self):
        """The color OUTSIDE the rounded shape (the panel showing through
        the corners). Given by _tint_brand_button; guessed from the parent
        when it is not."""
        c = self._o["chrome"]
        if c:
            return c
        for w in (self.master, self):
            try:
                c = str(w.cget("background"))
            except tk.TclError:
                c = ""
            if c:
                return c
        return self._o["bg"]

    def _colors(self):
        o = self._o
        chrome = self._chrome()
        if o["state"] == "disabled":
            fill = o["disabledbackground"] or self._mix(o["bg"], chrome, 0.55)
            txt = o["disabledforeground"] or self._mix(o["fg"], chrome, 0.45)
            return chrome, fill, txt, None
        fill = o["bg"]
        txt = o["fg"]
        if self._hot:
            fill = o["activebackground"] or fill
            txt = o["activeforeground"] or txt
        if self._down:
            fill = self._dim(fill, 0.86)
        return chrome, fill, txt, (o["outline"] or None)

    def _resolve_font(self, spec):
        if spec is None or isinstance(spec, tkfont.Font):
            return spec
        try:
            return tkfont.Font(root=self, font=spec)
        except Exception:
            return None

    def _gap(self):
        """Icon-to-label gap. Default scales with the text size."""
        g = self._o["gap"]
        if g is not None:
            return int(g)
        a = self._app
        try:
            return max(4, a._em() - 4)
        except Exception:
            return 5

    def _label(self):
        """What is actually DRAWN: the leading space the old tk.Button
        primaries used as their icon gap is ours to draw now."""
        t = self._o["text"] or ""
        if (self._o["image"] is not None
                and self._o["compound"] in ("left", "right")
                and t.startswith(" ")):
            t = t[1:]
        return t

    def _font(self):
        f = self._fobj
        if f is None:
            try:
                f = tkfont.nametofont("TkDefaultFont")
            except tk.TclError:
                return None
        return f

    # ---- geometry --------------------------------------------------------
    def _pads(self):
        """(height, total horizontal padding) this button should request."""
        o = self._o
        f = self._font()
        line = f.metrics("linespace") if f is not None else 14
        h = pw = 0
        if o["matchttk"] and self._app is not None:
            try:
                h, pw = self._app._ttk_btn_metrics()
            except Exception:
                h = pw = 0
        if o["pady"] is not None or h < 8:
            h = line + 2 * int(o["pady"] if o["pady"] is not None else 5)
        if o["padx"] is not None or pw < 8:
            pw = 2 * int(o["padx"] if o["padx"] is not None else 10)
        return int(h), int(pw)

    def _sync(self):
        h, pw = self._pads()
        f = self._font()
        o = self._o
        lab = self._label()
        tw = f.measure(lab) if (f is not None and lab) else 0
        iw = 0
        img = o["image"]
        if img is not None and o["compound"] in ("left", "right"):
            try:
                iw = int(img.width()) + self._gap()
            except Exception:
                iw = 0
        w = max(int(o["minwidth"] or 0), tw + iw + pw)
        try:
            if (int(tk.Canvas.cget(self, "width")) != w
                    or int(tk.Canvas.cget(self, "height")) != h):
                tk.Canvas.configure(self, width=w, height=h)
        except (tk.TclError, ValueError):
            pass
        self._draw()

    def _draw(self):
        try:
            w, h = self.winfo_width(), self.winfo_height()
            if w <= 1:
                w = int(tk.Canvas.cget(self, "width"))
            if h <= 1:
                h = int(tk.Canvas.cget(self, "height"))
            if w < 4 or h < 4:
                return
            chrome, fill, txt, edge = self._colors()
            tk.Canvas.configure(self, background=chrome)
            self.delete("all")
            self._round_rect(0, 0, w - 1, h - 1, int(self._o["radius"]),
                             fill, edge, int(self._o["outlinewidth"]))
            f = self._font()
            o = self._o
            img = o["image"]
            if img is not None and o["compound"] in ("left", "right"):
                img = self._flat_icon(img, fill)
            else:
                img = None
            cx, cy = w / 2.0, h / 2.0
            lab = self._label()
            tw = f.measure(lab) if (f is not None and lab) else 0
            if img is None:
                if lab:
                    self.create_text(cx, cy, text=lab, fill=txt,
                                     font=f, anchor="center")
            else:
                iw = int(img.width())
                gap = self._gap()
                x = cx - (iw + gap + tw) / 2.0
                self.create_image(x, cy, image=img, anchor="w")
                self.create_text(x + iw + gap, cy, text=lab, fill=txt,
                                 font=f, anchor="w")
            if self._ring and o["state"] != "disabled":
                self.create_rectangle(
                    3, 3, w - 4, h - 4, outline=(o["focuscolor"] or txt),
                    width=1, dash=(2, 2))
        except tk.TclError:
            pass

    def _round_rect(self, x0, y0, x1, y1, r, fill, edge=None, ew=2):
        """Filled rounded rectangle, drawn the BrandCard way: two crossing
        rectangles plus a pieslice in each corner (Tk has no rounded-rect
        primitive)."""
        r = max(0, min(int(r), (x1 - x0) // 2, (y1 - y0) // 2))
        if r <= 0:
            self.create_rectangle(x0, y0, x1, y1, fill=fill, outline=fill)
            return
        self.create_rectangle(x0 + r, y0, x1 - r, y1, fill=fill, outline=fill)
        self.create_rectangle(x0, y0 + r, x1, y1 - r, fill=fill, outline=fill)
        for box, start in (((x0, y0, x0 + 2 * r, y0 + 2 * r), 90),
                           ((x1 - 2 * r, y0, x1, y0 + 2 * r), 0),
                           ((x1 - 2 * r, y1 - 2 * r, x1, y1), 270),
                           ((x0, y1 - 2 * r, x0 + 2 * r, y1), 180)):
            self.create_arc(box, start=start, extent=90, style="pieslice",
                            fill=fill, outline=fill)
        if edge:
            for box, start in (((x0, y0, x0 + 2 * r, y0 + 2 * r), 90),
                               ((x1 - 2 * r, y0, x1, y0 + 2 * r), 0),
                               ((x1 - 2 * r, y1 - 2 * r, x1, y1), 270),
                               ((x0, y1 - 2 * r, x0 + 2 * r, y1), 180)):
                self.create_arc(box, start=start, extent=90, style="arc",
                                outline=edge, width=ew)
            for ln in ((x0 + r, y0, x1 - r, y0), (x0 + r, y1, x1 - r, y1),
                       (x0, y0 + r, x0, y1 - r), (x1, y0 + r, x1, y1 - r)):
                self.create_line(*ln, fill=edge, width=ew)

    def _flat_icon(self, img, over):
        """The geometric icons are antialiased RGBA. A tk.Button flattens
        them against its own background; a canvas item's alpha handling is
        not something to bet the look on, so flatten in PIL against the
        exact fill this button is about to draw."""
        a = self._app
        if a is None:
            return img
        try:
            return a._icon_over(img, over)
        except Exception:
            return img

    # ---- interaction (private bindtag: Tooltip cannot clobber these) -----
    def _ev_enter(self, _e=None):
        if self._o["state"] != "disabled":
            self._hot = True
            self._draw()

    def _ev_leave(self, _e=None):
        self._hot = self._down = False
        self._draw()

    def _ev_press(self, _e=None):
        if self._o["state"] == "disabled":
            return None
        self._down = True
        try:
            self.focus_set()
        except tk.TclError:
            pass
        self._draw()
        return "break"

    def _ev_release(self, e=None):
        was, self._down = self._down, False
        self._draw()
        if not was or self._o["state"] == "disabled":
            return None
        if e is not None:
            try:
                if not (0 <= e.x < self.winfo_width()
                        and 0 <= e.y < self.winfo_height()):
                    return None
            except tk.TclError:
                return None
        self.invoke()
        return "break"

    def _ev_focus_in(self, _e=None):
        self._ring = True
        self._draw()

    def _ev_focus_out(self, _e=None):
        self._ring = False
        self._draw()

    def _ev_key(self, _e=None):
        if self._o["state"] == "disabled":
            return None
        self.invoke()
        return "break"

    def _ev_configure(self, _e=None):
        self._draw()


# Theme picker. The five functional themes come first, then a
# non-selectable divider row, then the novelty ones: a first-run user
# looking for plain dark should not have to guess between "Kinda Dark"
# and "Davy Jones". The KEYS are unchanged, so settings and sessions
# written by any earlier build still resolve.
THEME_LABELS = {
    "light": "Standard Light",
    "dark": "Kinda Dark",
    "black": "Black Hole",
    "highcontrast": "High Contrast",
    "colorblind": "Colorblind Safe",
    "colorblinddark": "Colorblind Safe Dark",
    "white": "Flashbang White",
    "coastguard": "Semper Paratus",
    "forest": "Touch Grass",
    "rose": "Pink Pony Club",
    "ocean": "Davy Jones",
    "solarized": "New Mexico",
    "rainbow": "Rainbow",
    "synthwave": "Synthwave",
    "christmas": "Christmas",
    "tet": "Tet",
}
# how many of the above are the functional group (the divider goes after).
# High Contrast and the two Colorblind Safe themes are accessibility
# themes, so they live above the divider, not with the novelties. The two
# Dyslexic themes retired in v1.4.9 R9a: the face they carried is an
# App-font value now (ui_prefs.RETIRED_THEMES migrates a settings file).
THEME_FUNCTIONAL = 6
THEME_DIVIDER = "\u2500" * 12


class App:
    def __init__(self, root):
        # Nothing is mapped until mainloop, so every idle flush taken while
        # the tree is still being built is pure waste: the layout it pays
        # for is invalidated by the widgets and styles that come after it.
        # Guarded by _ui_breathe; cleared as the last act of __init__.
        self._booting = True
        self.root = root
        # First thing after the root: from here on, a Tk callback that dies
        # says so instead of vanishing. Installed before a single widget
        # exists, so the build itself is covered too.
        self._install_error_handler()
        self.results = []
        self.trace_vars = {}      # label -> BooleanVar (show/hide)
        self.dvars = {}           # label -> BooleanVar (is decompression)
        self.smooth_cache = {}
        self.smooth_params = dict(smoothing.DEFAULTS)
        self.notch_cache = {}     # label -> {'absorbance','sample','background'}
        self._nt_cache = {}       # label -> per-channel fringe n*t (Thickness)
        self.last_out_dir = None
        self.settings = self._load_settings()
        self._migrate_settings()
        # d2 keys: welcome_seen (the welcome card's 'Don't show this
        # again') and tour_done. Owned by guide_tour, defaulted here
        # so a settings file written before v1.4.9 still reads.
        for _k, _v in guide_tour.D2_SETTINGS_DEFAULTS.items():
            self.settings.setdefault(_k, _v)
        _tm = ui_prefs.live_theme(self.settings.get(
            "theme", "dark" if self.settings.get("dark") else "black"))
        _valid = {"light", "white", "dark", "black"} | set(self._themes())
        if _tm not in _valid:
            _tm = "light"
        self.theme_mode = tk.StringVar(value=_tm)
        # App font: the UI typeface, one value out of ui_prefs.APP_FONTS.
        # Chrome like the theme and the text size, so it lives in the
        # settings file and never in a figure preset (rule 30).
        self.app_font = tk.StringVar(
            value=self.settings.get("app_font",
                                    ui_prefs.DEFAULT_APP_FONT))
        # plot background: on = match the interface theme, off = white page.
        # ONE var drives both the quick-access "theme bg" toggle and the
        # Colors-panel "Tint plot with theme" box (they used to diverge and
        # only bite in light).
        self.plot_theme_bg = tk.BooleanVar(
            value=bool(self.settings.get("plot_theme_bg", True)))
        self.dark_mode = tk.BooleanVar(value=(_tm != "light"))
        # reduce-motion: kill switch for the small one-shot UI animations
        self.reduce_motion = tk.BooleanVar(
            value=bool(self.settings.get("reduce_motion", False)))
        # App-wide performance mode: trade live feedback for
        # responsiveness on a slow machine (today: the pane dividers drag
        # as a ghost guide line and resize once, on release). App state,
        # persisted beside the folders exactly like auto_rescan -
        # deliberately NOT a figure preset. Distinct from self.perf_mode,
        # which is the 3D renderer's own "Performance mode (faster 3D)".
        self.app_perf_mode = tk.BooleanVar(
            value=bool(self.settings.get("app_perf_mode", False)))
        self._sash_drag = None      # (sash index, x) while a drag is live
        self._sash_ghost_win = None
        self._sash_last = 0.0
        self._anim_jobs = {}
        self._auto_rescan_job = None   # the ONE auto-rescan timer (or None)
        self._tk_widgets = []      # non-ttk widgets to recolor with the theme
        self._slider_entries = []  # (var, entry, fmt) slider<->box sync
        # action log stays quiet while the UI builds (control traces fire
        # during construction); switched on at the end of __init__
        self._action_log_on = False
        self._undo_stack = []
        self._redo_stack = []
        self._restoring = False

        # ---- computed quantities (formula editor) ------------------------
        # The derived column variants live on the pure module, so its
        # evaluator and its renderer pick them up with no other change.
        self._register_formula_columns()
        self._qty_notes = []            # load complaints, logged after build
        self.quantities = self._load_quantities()
        # KEY of the quantity offered as a Y-data choice ("" = none). It
        # changes the figure, so it rides in _preset_registry; the
        # quantities THEMSELVES live in settings, never in a preset.
        self.active_qty = tk.StringVar(value="")
        self._qty_sel = tk.StringVar(value="")     # highlighted list row
        self._ydata_combos = []         # the three Y-data pickers
        self._qty_rows = []
        self._qty_recs = []             # per-row widget handles, for retinting
        self._qty_struct_sig = None     # what the rows SAY (rebuild trigger)
        self._qty_look_sig = None       # what the rows LOOK like (retint)
        self._qty_tint = None           # (theme, tint) the ttk style holds
        self._qty_cache = {}            # label -> (values, None) | (None, why)
        self._qty_cache_sig = None
        self._qty_skip_sig = None       # one log line per skip situation
        self._mathtext_cache = {}       # (tex, color, size) -> PhotoImage
        self._surf_cache = {}           # 3D surface grids, keyed on their input

        # brand typography: private-load Jost and route the named fonts
        # through it so every ttk widget follows (DESIGN_RULES.md). Must
        # run before any widget is built.
        global UI_FONT, UI_FONT_SEMI, DYS_FONT
        _register_brand_fonts()
        UI_FONT, UI_FONT_SEMI = _resolve_ui_font()
        DYS_FONT = _resolve_dyslexic_font()
        self._scaled_fonts = {}   # (delta, weight, mono, semi, ul) -> Font
        _ufs = self.settings.get("ui_font_size", "auto")
        self._ui_font_auto = str(_ufs).strip().lower() in ("auto", "none", "")
        if not self._ui_font_auto:
            try:
                self._body_size = max(3, min(15, int(_ufs)))
            except (TypeError, ValueError):
                self._ui_font_auto = True
        if self._ui_font_auto:
            self._body_size = self._auto_body_size()
        _bs = self._body_size
        # the ACTIVE face, not the brand face: a session saved in a
        # Dyslexic theme must be born in its font, not converted later
        _uf = self._ui_faces()[0]
        for _nf, _sz in (("TkDefaultFont", _bs), ("TkTextFont", _bs),
                         ("TkMenuFont", _bs), ("TkHeadingFont", _bs),
                         ("TkTooltipFont", _bs - 1),
                         ("TkCaptionFont", _bs - 1)):
            try:
                tkfont.nametofont(_nf).configure(family=_uf, size=_sz)
            except tk.TclError:
                pass

        root.title(APP_TITLE)
        root.geometry(self.settings.get("geometry", "1400x860"))
        root.minsize(1024, 640)     # below this the three panes are unusable
        try:                                # window / taskbar icon
            # _MEIPASS = the PyInstaller bundle dir when frozen; the script
            # dir otherwise. icon.png is shipped as a data file in both.
            _base = getattr(sys, "_MEIPASS",
                            os.path.dirname(os.path.abspath(__file__)))
            _ico = os.path.join(_base, "icon.png")
            self._app_icon = tk.PhotoImage(file=_ico)
            root.iconphoto(True, self._app_icon)
        except Exception:
            pass                            # missing icon never blocks launch
        root.protocol("WM_DELETE_WINDOW", self._on_close)
        self._init_theme()

        self._build_top()
        self._build_panes()
        self._center_titles()
        self._refresh_fallback_note()
        self._refresh_presets()
        self._refresh_ydata_values()
        # A remembered journal preset has to be APPLIED, not just shown: the
        # combobox trace only fires on a change. (cmap_default needs no such
        # pass - the colormap is read at draw time.) Runs before the
        # _defaults snapshot so Reset all returns HERE, not to 7x5 in.
        if self.fig_preset.get() != "custom":
            self._apply_journal_preset()
        self._defaults = {k: v.get() for k, v in self._preset_registry().items()}
        self._recolor_tk()
        self._bind_shortcuts()
        self._schedule_auto_rescan()   # no-op unless the toggle is remembered on
        self._push_undo("initial")
        self._update_undo_buttons()
        self._redraw()

        # start logging user actions only now, with a friendly first line
        self._action_log_on = True
        if not self.log.get("1.0", "end-1c").strip():
            self._logline("Ready. Pick an input folder and press Run, or "
                          "click 'Load previous run\u2026' to reopen a finished "
                          "output.")
        for _qn in getattr(self, "_qty_notes", []):
            self._logline(_qn)
        self._qty_notes = []
        for _gm in getattr(self, "_gfx_migrated", []):
            self._logline(_gm)
        self._gfx_migrated = []
        for _dm in getattr(self, "_df_migrated", []):
            self._logline(_dm)
        self._df_migrated = []
        if getattr(self, "_theme_note", None):
            self._logline(self._theme_note)
            self._theme_note = None
        self._set_run_state("Ready", "#2a8a4a")
        self._apply_brand()
        # DWM ignores caption colors set before the window is
        # composited; re-apply once mapped and shortly after
        # NB: a bind on root fires for EVERY child widget's <Map> (their
        # bindtags include the toplevel) -- re-adding a hidden pane maps
        # hundreds of widgets and used to re-apply the titlebar for each
        root.bind("<Map>",
                  lambda e: (self._apply_titlebar()
                             if e.widget is root else None), add="+")
        root.after(400, self._apply_titlebar)

        # widgets built above were BORN with tk_setPalette's frozen
        # foreground (option db) -- clear it now that they all exist
        self._pin_field_styles()

        # Explorer drag-and-drop (Windows). Exactly one log line either way;
        # a hook that will not attach must never keep the program from
        # starting, so the whole call is inside the guard.
        try:
            self._attach_drop_target()
        except Exception as _dnd_err:
            self._logline("Drag-and-drop unavailable (%s). Use Browse, or "
                          "paste a path into the Input folder box."
                          % _dnd_err)

        # multi-tab sessions: one shared widget tree, per-tab state swapped
        # in and out (see _capture_session / _load_session). Tab 0 captures
        # the freshly-built state.
        self.sessions = [self._capture_session("Session 1")]
        self.active = 0
        self._render_tabs()
        self._booting = False      # from here on _ui_breathe may flush
        # First launch: the welcome card. A no-op once the user has
        # ticked 'Don't show this again'; reopened from About.
        self._tour = None
        root.after(400, lambda: guide_tour.maybe_show_welcome(self))

    def _bind_shortcuts(self):
        b = self.root.bind
        # Run is the most repeated action at the beamline and was the one
        # with no key. Escape reaches Cancel only while a worker is alive,
        # and is bound with add="+" so every other Escape (dialogs, the
        # settings menu, a divider drag) keeps its meaning.
        b("<Control-Return>", self._hotkey_run)
        try:                       # keypad Enter, where the keysym exists
            b("<Control-KP_Enter>", self._hotkey_run)
        except tk.TclError:
            pass
        b("<Escape>", self._hotkey_cancel_run, add="+")
        b("<Control-s>", lambda e: self._save_plot())
        # Export data: the second half of the Run/export pair. The handler
        # carries its own no-results note, so the key is safe at any time.
        b("<Control-e>", lambda e: self._open_export_dialog())
        b("<Control-z>", lambda e: self._undo())
        b("<Control-y>", lambda e: self._redo())
        b("<Control-Z>", lambda e: self._redo())   # Ctrl+Shift+Z
        b("<Control-r>", lambda e: self._reset_3d_view())
        b("<Control-Shift-C>", lambda e: self._copy_clipboard())
        b("<F1>", lambda e: self._show_shortcuts_popup())
        b("<Key-1>", lambda e: self._hotkey_wf("off"))
        b("<Key-2>", lambda e: self._hotkey_wf("2D stacked"))
        b("<Key-3>", lambda e: self._hotkey_wf("3D ridge"))
        b("<Key-4>", lambda e: self._hotkey_wf("3D shape"))
        b("<bracketleft>", lambda e: self._cycle_cmap(-1))
        b("<bracketright>", lambda e: self._cycle_cmap(1))
        b("<Control-Tab>", lambda e: self._cycle_tab(1))
        b("<Control-Shift-Tab>", lambda e: self._cycle_tab(-1))
        try:                       # Tk < 8.6.10 has no ISO_* keysyms
            b("<Control-ISO_Left_Tab>", lambda e: self._cycle_tab(-1))
        except tk.TclError:
            pass
        b("<Control-t>", lambda e: (self._new_session(), "break")[1])
        b("<Control-w>", lambda e: (self._close_session(self.active),
                                    "break")[1])
        b("<Control-d>", lambda e: self._toggle_drawer())
        b("<F5>", lambda e: self._manual_rescan())
        # Enter in the input-folder box = Rescan + remember that folder
        try:
            self._in_entry.bind("<Return>",
                                lambda e: self._manual_rescan(True))
        except (AttributeError, tk.TclError):
            pass
        # 2D view: arrows pan, +/- zoom, 0 fits (all no-ops while typing)
        b("<Left>", lambda e: self._hot_pan(-1, 0))
        b("<Right>", lambda e: self._hot_pan(+1, 0))
        b("<Up>", lambda e: self._hot_pan(0, +1))
        b("<Down>", lambda e: self._hot_pan(0, -1))
        b("<plus>", lambda e: self._hot_zoom(0.9))
        b("<equal>", lambda e: self._hot_zoom(0.9))
        b("<KP_Add>", lambda e: self._hot_zoom(0.9))
        b("<minus>", lambda e: self._hot_zoom(1.0 / 0.9))
        b("<KP_Subtract>", lambda e: self._hot_zoom(1.0 / 0.9))
        b("<Key-0>", lambda e: self._hot_fit())

    def _typing_in_box(self):
        """True when keyboard focus is in a widget that consumes keystrokes
        itself (text entry, list/tree navigation, slider arrows), so global
        single-key shortcuts must not fire (the promise in SHORTCUTS_TEXT)."""
        w = self.root.focus_get()
        return w is not None and w.__class__.__name__ in (
            "Entry", "TEntry", "Combobox", "TCombobox",
            "Spinbox", "TSpinbox", "Text",
            "Scale", "TScale", "Listbox", "Treeview")

    def _hotkey_run(self, _e=None):
        """Ctrl+Enter: the Run button's action.

        A multi-line box keeps the key: this binding sits on the toplevel,
        which Tk reaches AFTER the widget's own class binding, so 'break'
        here would arrive too late to take a newline back."""
        w = self.root.focus_get()
        if w is not None and w.__class__.__name__ == "Text":
            return
        try:
            self._run()
        except tk.TclError:
            pass
        return "break"

    def _hotkey_cancel_run(self, _e=None):
        """Escape while a run is under way: cancel it.

        Returns None on purpose. 'break' here would swallow Escape for the
        bindings that share the key."""
        if self._run_busy():
            try:
                self._cancel_run()
            except tk.TclError:
                pass

    def _hotkey_wf(self, mode):
        if self._typing_in_box():
            return
        self.wf_mode.set(mode)

    def _step_cmap(self, step):
        """Walk the colormap list one step.

        The list is the one the dropdown is SHOWING, so a filter typed in
        the Filter box narrows the arrows with it and the two controls can
        never disagree about what 'next' means."""
        try:
            vals = [str(v) for v in self.cmap_cb.cget("values")]
        except (AttributeError, tk.TclError):
            vals = []
        if not vals:
            vals = list(colormaps.available())
        if not vals:
            return
        cur = self.cmap.get()
        i = ((vals.index(cur) + step) % len(vals)) if cur in vals else 0
        self.cmap.set(vals[i])
        self._log_action("Colormap: " + vals[i])

    def _cycle_cmap(self, step):
        if self._typing_in_box():
            return
        try:
            self._step_cmap(step)
        except Exception:
            pass

    # ---- dropdown step arrows: ONE mechanism for every combobox (W1b) ----
    def _step_combo(self, combo, step, subject=None):
        """Walk a readonly combobox one step through the list it is
        SHOWING - a filtered list narrows the arrows with it - skipping
        divider rows, wrapping at the ends, and firing the same
        <<ComboboxSelected>> a real pick fires, so a mapped combo's
        display->code sync and every bound listener agree."""
        try:
            vals = [str(v) for v in combo.cget("values")]
        except tk.TclError:
            return
        vals = [v for v in vals if v.strip("\u2500- ")]   # divider rows out
        if not vals:
            return
        try:
            cur = combo.get()
        except tk.TclError:
            return
        if cur in vals:
            i = (vals.index(cur) + step) % len(vals)
        else:
            i = 0 if step > 0 else len(vals) - 1
        combo.set(vals[i])
        combo.event_generate("<<ComboboxSelected>>")
        if subject:
            self._log_action("%s: %s" % (subject[:1].upper() + subject[1:],
                                         vals[i]))

    def _combo_arrows(self, combo, subject, command=None, keys=None,
                      log=True):
        """The colormap prev/next pair, generalized.

        Call AFTER the combobox is packed. On a stretchy combo the pair
        packs at the row's right edge BEFORE the combo in pack order, so
        the box stays the one thing that gives when the panel narrows
        (rule 13); on a fixed-width combo the pair sits right beside it,
        in the row's measured dead space. The text glyphs are the
        PIL-less fallback; _apply_brand stamps the drawn chevrons over
        every registered pair. Returns (prev, next)."""
        try:
            info = combo.pack_info()
        except tk.TclError:
            return None
        row = combo.master
        if command is None:
            _sub = subject if log else None
            step = lambda d: self._step_combo(combo, d, _sub)
        else:
            step = command
        nxt = ttk.Button(row, text="\u203a", width=2,
                         style="Compact.TButton", command=lambda: step(1))
        prv = ttk.Button(row, text="\u2039", width=2,
                         style="Compact.TButton", command=lambda: step(-1))
        if str(info.get("expand", 0)).lower() in ("1", "true", "yes"):
            nxt.pack(side="right", padx=(PAD_X_TIGHT, 0), before=combo)
            prv.pack(side="right", padx=(PAD_X, 0), before=combo)
        else:
            prv.pack(side="left", padx=(PAD_X, 0), after=combo)
            nxt.pack(side="left", padx=(PAD_X_TIGHT, 0), after=prv)
        _kp = (" Keyboard: %s" % keys[0]) if keys else ""
        _kn = (" Keyboard: %s" % keys[1]) if keys else ""
        Tooltip(prv, "Step back one %s in the list. The list stays shut.%s"
                     % (subject, _kp))
        Tooltip(nxt, "Step on to the next %s in the list.%s"
                     % (subject, _kn))
        if not hasattr(self, "_combo_arrow_btns"):
            self._combo_arrow_btns = []
        self._combo_arrow_btns += [(prv, "chev_l"), (nxt, "chev_r")]
        return prv, nxt

    def _help_glyph_btn(self, parent, command, tip):
        """A [?] glyph that opens deeper reading (the fringe cards'
        idiom): a flat label wearing the drawn help square, keyboard
        reachable, re-stamped per theme by _apply_brand. Caller packs."""
        lbl = self._lbl(parent, text="?", font=self._F(0, "bold"),
                        anchor="center", takefocus=1, cursor="hand2")
        img = getattr(self, "_icons", {}).get("help")
        if img is not None:
            lbl.configure(image=img, text="")
        for seq in ("<Button-1>", "<Return>", "<Key-space>"):
            lbl.bind(seq, lambda e: command())
        Tooltip(lbl, tip)
        if not hasattr(self, "_help_btns"):
            self._help_btns = []
        self._help_btns.append(lbl)
        return lbl

    def _show_shortcuts_popup(self):
        """F1's shortcut list, in the house guide shape.

        It used to be a `messagebox.showinfo`, which is an OS dialog: no
        theme, no brand face, a proportional font that broke the aligned
        key column it is entirely made of, and no way to keep it open
        beside the window you were learning. It is a help surface like
        every other now (R4 item 8) - one styled, scrollable, singleton
        card, classified by the same segmenter the Guide panel uses."""
        if self._raise_existing("_shortcuts_win") is not None:
            return
        win = tk.Toplevel(self.root)
        self._shortcuts_win = win
        win.title("Keyboard shortcuts")
        win.transient(self.root)
        _sw, _sh = self._dialog_size(84, 78)
        self._center_on_root(win, _sw, _sh)
        self._apply_titlebar(win)
        win.bind("<Escape>", lambda e: win.destroy())
        bar = ttk.Frame(win, padding=(10, 8)); bar.pack(side="bottom",
                                                        fill="x")
        ttk.Button(bar, text="Close", command=win.destroy).pack(side="right")
        card = self._card(win, grow="both")
        card.pack(fill="both", expand=True, padx=10, pady=(8, 2))
        card.set_title(self._lf_header(card, "Shortcuts", icon="book"))
        txt = self._guide_text_box(card.body, width=68)
        # Classified here rather than by _guide_fallback_segments: the body
        # is ONE fixed-width two-column table, and the shared classifier
        # judges line by line - rows whose gutter is a space or two
        # ("Dbl-click pill Reset that pane...") came out as prose and the
        # key column lost its alignment. Here every line up to the closing
        # note is verbatim, which is what it is.
        # The closing note is the last blank-line-separated block. It used
        # to be spotted by its opening bracket, which R12's rewrite took
        # away - and the note then rendered in the mono key column.
        _lines = SHORTCUTS_TEXT.splitlines()
        _note_at = max((i for i, s in enumerate(_lines) if not s.strip()),
                       default=len(_lines))
        rows, note = [], False
        for _i, ln in enumerate(_lines):
            body = ln.strip()
            if _i > _note_at:
                note = True
            if not body:
                rows.append(("gap", ""))
            elif note:
                rows.append(("b", body))
            elif body.upper() == body and any(c.isalpha() for c in body):
                rows.append(("h", body))
            else:
                rows.append(("m", ln.rstrip()))
        self._guide_fill(txt, rows)
        txt.configure(state="disabled")
        self._iconize_buttons(win)

    def _toggle_tooltips(self):
        """Helper switch: turn every hover tooltip on or off (remembered)."""
        Tooltip.enabled = bool(self.tooltips_on.get())
        self.settings["tooltips_on"] = Tooltip.enabled
        self._save_settings()
        self._log_action("Helper tips %s"
                         % ("on" if Tooltip.enabled else "off"))

    def _on_close(self):
        try:
            self._detach_drop_target()  # no Python WNDPROC outlives the HWND
        except Exception:
            pass
        self._cancel_auto_rescan()      # no timer may outlive the window
        self._sash_ghost(None)          # nor may a drag guide line
        self._save_user_notes()
        try:
            self.settings["geometry"] = self.root.winfo_geometry()
            self._save_settings()
        except Exception:
            pass
        self.root.destroy()

    def _themes(self):
        """Accent themes. light/dark/black are built in and untouched; the rest
        tint the chrome only and keep the plot neutral unless 'Tint plot' is on."""
        return {
            "white":     dict(base="light", bg="#ffffff", fg="#1c2530",
                              field="#f2f2f2", accent="#1D3EC0"),
            "coastguard": dict(base="dark", bg="#002855", fg="#eef3fb",
                               field="#0d3a6e", accent="#E4002B",
                               cgstripe=True),
            "christmas": dict(base="dark", bg="#0e3a29", fg="#f5efe0",
                              field="#124a34", accent="#c8102e"),
            "tet":       dict(base="dark", bg="#8c1414", fg="#ffe9b8",
                              field="#a01f1f", accent="#FFCF33"),
            "synthwave": dict(base="dark", bg="#1a1030", fg="#e8d5ff",
                              field="#241447", accent="#ff3caf"),
            "highcontrast": dict(base="dark", bg="#000000", fg="#ffffff",
                                 field="#000000", accent="#ffd400"),
            "colorblind": dict(base="light", bg="#ffffff", fg="#000000",
                               field="#ffffff", accent="#0072B2"),
            "forest":    dict(base="light", bg="#eaf1e8", fg="#1b2e1b",
                              field="#ffffff", accent="#2e7d32"),
            "rose":      dict(base="light", bg="#fbeef3", fg="#3a1b2a",
                              field="#ffffff", accent="#c2185b"),
            "ocean":     dict(base="dark",  bg="#0f2a3a", fg="#dbeefb",
                              field="#13344a", accent="#26c6da"),
            "solarized": dict(base="dark", bg="#17140c", fg="#e7ddc2",
                              field="#241c0f", accent="#c9a31a"),
            "rainbow":   dict(base="dark", bg="#0c0c10", fg="#ececef",
                              field="#16161d", accent="#c64fd0", rainbow=True),
            # Colorblind Safe Dark: the Okabe-Ito palette on a dark
            # ground. Every accent clears 4.5:1 against that ground, so
            # this theme holds the same contrast floor the light one
            # holds (measured, R9a).
            "colorblinddark": dict(base="dark", bg="#14171c", fg="#f2f5f8",
                                   field="#1e232b", accent="#56B4E9"),
        }

    def _brand(self):
        """The SPARTA triad for the active theme (DESIGN_RULES.md #3):
        ac1 primary actions, ac2 signal (dot/carets/markers), ac3 highlight,
        ink structural rules, hov = ac1 hover shade."""
        T = {
            "light":     ("#1D3EC0", "#E4581C", "#B98A0E", "#171310"),
            "dark":      ("#5B78F2", "#FF7A45", "#EDBB4A", "#E8E4DA"),
            "black":     ("#6C86FF", "#FF8149", "#F2BE3A", "#EFEBE0"),
            "white":     ("#1D3EC0", "#E4581C", "#B98A0E", "#171310"),
            "coastguard": ("#E4002B", "#6FA8DC", "#E8B84B", "#DCE8FA"),
            "christmas": ("#c8102e", "#3fae63", "#E8B84B", "#F0E6D0"),
            "tet":       ("#FFCF33", "#FF6B6B", "#FFE066", "#FFE0A0"),
            "synthwave": ("#ff3caf", "#3cd5ff", "#ffd24a", "#E0C8FF"),
            "highcontrast": ("#FFD400", "#00E5FF", "#FFD400", "#FFFFFF"),
            "colorblind": ("#0072B2", "#D55E00", "#E69F00", "#000000"),
            "forest":    ("#2E7D32", "#E4581C", "#C9A227", "#1B2E1B"),
            "rose":      ("#C2185B", "#8A63D2", "#DDA523", "#3A1B2A"),
            "ocean":     ("#26C6DA", "#F2984B", "#7FD1AE", "#DBEEFB"),
            "solarized": ("#c9a31a", "#7fb53c", "#3fbee0", "#c6ba93"),
            "rainbow":   ("#C64FD0", "#E4581C", "#E3A917", "#ECECEF"),
            "colorblinddark": ("#56B4E9", "#E69F00", "#F0E442", "#E8ECF1"),
        }
        ac1, ac2, ac3, ink = T.get(self.theme_mode.get(), T["light"])
        return {"ac1": ac1, "ac2": ac2, "ac3": ac3, "ink": ink,
                "hov": self._shade(ac1, 0.82)}

    @staticmethod
    def _shade(hexcol, f):
        """Darken (f<1) or lighten (f>1) a #rrggbb color."""
        try:
            r, g, b = (int(hexcol[i:i + 2], 16) for i in (1, 3, 5))
            return "#%02x%02x%02x" % tuple(max(0, min(255, int(c * f)))
                                           for c in (r, g, b))
        except Exception:
            return hexcol

    def _theme_palette(self):
        """(ui_bg, ui_fg, field_bg, plot_bg, plot_fg) for the active theme."""
        t = self.theme_mode.get()
        if t == "black":
            # true-black chrome and plot. frames/labels are pushed to pure black
            # by the style.configure overrides in _init_theme; field bg stays a
            # hair above black so entry/combo boxes stay visible.
            return ("#000000", "#e8e8e8", "#0d0d0d", "#000000", "#e8e8e8")
        if t == "dark":
            return ("#23252b", "#e6e6e6", "#2c2f37", "#23252b", "#e6e6e6")
        if t == "light":
            # Bauhaus paper (DESIGN_RULES.md): warm workshop ground; fields
            # and the plot page stay white for publication neutrality.
            return ("#f1eee6", "#201b16", "#ffffff", "white", "#1c2530")
        th = self._themes().get(t)
        if th:
            base_dark = th["base"] == "dark"
            follow = getattr(self, "plot_theme_bg", None)
            if follow is not None and follow.get():
                pb, pf = th["bg"], th["fg"]
            else:
                pb, pf = (("#23252b", "#e6e6e6") if base_dark
                          else ("white", "#1c2530"))
            return (th["bg"], th["fg"], th["field"], pb, pf)
        return ("#f3f5f8", "#1c2530", "#ffffff", "white", "#1c2530")

    def _section_palette(self):
        """Some fun themes give each settings section its own head colour -- a
        little parade down the panel instead of the plain Bauhaus look. Each
        palette is chosen to suit the theme (not copied from the prism).
        Returns a colour list to cycle through, or None."""
        return {
            "rainbow":    ["#e53935", "#fb8c00", "#fdd835", "#43a047",
                           "#1e88e5", "#8e24aa"],       # the DSotM prism
            "colorblinddark": ["#56B4E9", "#E69F00", "#009E73", "#CC79A7",
                               "#F0E442"],              # Okabe-Ito
            "solarized":  ["#d8b020", "#7fb53c", "#3fbee0"],   # BB chemistry
            "coastguard": ["#E4002B", "#E8B84B", "#6FA8DC", "#DCE8FA"],  # CG
            "forest":     ["#1B5E20", "#E65100", "#6A1B9A", "#B8860B"],  # meadow
            "rose":       ["#C2185B", "#8E24AA", "#C9A227", "#00ACC1"],  # disco
            "ocean":      ["#26C6DA", "#2BB673", "#6FA0E0", "#EF9A6B"],  # sea
            "christmas":  ["#E5484D", "#F2C14E", "#EDE3CC", "#5FC27E"],  # festive
            "tet":        ["#FFCF33", "#FF8A8A", "#8BC34A", "#FFE0A0"],  # Tet
            "synthwave":  ["#ff3caf", "#3cd5ff", "#ffd24a", "#b06bff"],  # neon
            "highcontrast": ["#FFD400", "#00E5FF", "#FF61D8", "#FFFFFF"],
            "colorblind": ["#0072B2", "#D55E00", "#009E73", "#CC79A7"],  # Okabe-Ito
        }.get(self.theme_mode.get())

    def _recolor_accents(self, accent=None, rainbow=False):
        """Bauhaus treatment: the square marker carries the signal color
        (via _apply_brand), the collapse caret goes quiet, titles stay ink.
        Rainbow keeps its per-section caret parade."""
        _u, fg, _fl, _pb, _pf = self._theme_palette()
        # one derivation, not a hand-rolled pair: _muted_fg already collapses
        # to the full fg in High Contrast (rule 48)
        muted = self._muted_fg()
        pal = self._section_palette()
        _seen = {}
        for rec in getattr(self, "_collapsibles", []):
            if pal:
                c = rec.get("cat")
                j = _seen.get(c, 0)
                _seen[c] = j + 1
                col = pal[j % len(pal)]
            else:
                col = muted
            try:
                rec["caret"].configure(foreground=col)
                if rec.get("title_lbl"):
                    rec["title_lbl"].configure(
                        foreground=(col if pal else fg))
            except Exception:
                pass
        if hasattr(self, "title_lbl"):
            try:
                self.title_lbl.configure(foreground=fg)
            except Exception:
                pass

    def _apply_brand(self):
        """Re-tint every brand element from the active theme's triad: the
        wordmark dot (ac2), the 2px section rules (ink), and the primary
        brand buttons (ac1). Called at init end and from _toggle_dark."""
        br = self._brand()
        # Tooltips are bare toplevels, so they take their colours from the
        # palette here rather than from the ttk theme. The field ground and
        # the body ink give a legible chip in every theme, High Contrast
        # and Colorblind Safe included.
        _tu, _tf, _tfld, _tpb, _tpf = self._theme_palette()
        Tooltip.BG = _tfld
        Tooltip.FG = _tf
        try:
            Tooltip.EDGE = self._blendc(_tfld, _tf, 0.35)
        except (ValueError, TypeError):
            Tooltip.EDGE = _tf
        if getattr(self, "_wm_dot", None) is not None:
            try:
                self._wm_dot.configure(foreground=self._signal_fg())
            except tk.TclError:
                pass
        # the Dyslexic themes swap the UI face, and the theme box is sized
        # from measured text, so its width is a themed asset too (rule 49)
        self._fit_theme_combo()
        _pal = self._section_palette()
        _seen = {}
        for rec in getattr(self, "_collapsibles", []):
            if _pal:
                c = rec.get("cat")
                j = _seen.get(c, 0)
                _seen[c] = j + 1
                col = _pal[j % len(_pal)]
            else:
                col = None
            r = rec.get("rule")
            if r is not None:
                try:
                    r.configure(bg=col or br["ink"])
                except tk.TclError:
                    pass
            # in rainbow, the whole section head joins the prism parade:
            # marker, caret, and a tinted title. Other themes keep the
            # Bauhaus signal marker + quiet caret (handled elsewhere).
            if _pal:
                rec["title_rest"] = col
                for key, attr, val in (("marker", "foreground", col),
                                       ("caret", "foreground", col),
                                       ("title_lbl", "foreground", col)):
                    w = rec.get(key)
                    if w is not None:
                        try:
                            w.configure(**{attr: val})
                        except tk.TclError:
                            pass
            else:
                rec["title_rest"] = None
        alive = []
        for b in getattr(self, "_brand_btns", []):
            try:
                self._tint_brand_button(b, br)
                alive.append(b)
            except tk.TclError:
                pass                       # button from a closed dialog
        self._brand_btns = alive

        # geometric icon set: regenerate in this theme's ink/accent and
        # re-attach (references live in self._icons; tk needs them held)
        self._make_icons()
        ic = getattr(self, "_icons", {})

        def seticon(btn, name, compound="left"):
            img = ic.get(name)
            if btn is None or img is None:
                return
            try:
                btn.configure(image=img, compound=compound)
            except tk.TclError:
                pass
        seticon(getattr(self, "run_btn", None), "run_w")
        seticon(getattr(self, "_data_btn", None), "table_w")
        seticon(getattr(self, "load_prev_btn", None), "prev")
        seticon(getattr(self, "profile_btn", None), "gear")
        seticon(getattr(self, "_guide_gear_btn", None), "gear",
                compound="image")
        seticon(getattr(self, "_qa_gear_btn", None), "gear",
                compound="image")
        seticon(getattr(self, "_settings_gear_btn", None), "gear",
                compound="image")
        for _fb in list(getattr(self, "_qa_fx_btns", [])):
            try:
                if _fb.winfo_exists():
                    seticon(_fb, getattr(_fb, "_qa_icon", ""))
            except tk.TclError:
                pass
        for key in ("reset", "pan", "zoom", "save"):
            seticon(getattr(self, "_tb_btns", {}).get(key), key)
        seticon(getattr(self, "_browse_in_btn", None), "folder")
        seticon(getattr(self, "_browse_out_btn", None), "folder")
        seticon(getattr(self, "_openout_btn", None), "folder_open")
        seticon(getattr(self, "_copylog_btn", None), "copy")
        seticon(getattr(self, "_expset_btn", None), "share")
        self._sync_collapse_btn()      # label + chevron follow the state
        seticon(getattr(self, "_resetall_btn", None), "reset")
        for _b, _g in list(getattr(self, "_combo_arrow_btns", [])):
            seticon(_b, _g, compound="image")
        _hicon = ic.get("help")
        if _hicon is not None:
            for _hb in list(getattr(self, "_help_btns", [])):
                try:
                    _hb.configure(image=_hicon)
                except tk.TclError:
                    pass
        self._retint_ref()             # guide-box tags follow the theme
        _iw = getattr(self, "_interp_info_win", None)
        try:
            if _iw is not None and _iw.winfo_exists():
                self._fill_interp_info()   # typeset math is images (rule 49)
        except tk.TclError:
            pass
        try:
            _cw = self.canvas.get_tk_widget()
            if getattr(self, "fig_preview", None) is not None \
                    and self.fig_preview.get():
                _cw.configure(highlightthickness=2,
                              highlightbackground=br["ac1"],
                              highlightcolor=br["ac1"])
            else:
                _cw.configure(highlightthickness=0)
        except Exception:
            pass
        self._apply_titlebar()
        self._repaint_svttk_accent()
        if getattr(self, "_hdr_mark_lbl", None) is not None and ic.get("mark"):
            try:
                self._hdr_mark_lbl.configure(image=ic["mark"])
            except tk.TclError:
                pass
        # section geo markers (ac2 squares); quick-access title takes ac3
        for rec in getattr(self, "_collapsibles", []):
            car = ic.get("caret_closed" if rec.get("collapsed")
                         else "caret_open")
            if car is not None:
                try:
                    rec["caret"].configure(image=car, width=16)
                except tk.TclError:
                    pass
            m = rec.get("marker")
            if m is not None:
                img = ic.get("sec::" + rec["key"]) or ic.get("sec_dot")
                try:
                    if img is not None:
                        m.configure(image=img)
                    else:
                        m.configure(foreground=br["ac2"])
                except tk.TclError:
                    pass
        if getattr(self, "_drawer_title", None) is not None:
            try:
                self._drawer_title.configure(foreground=self._head_fg())
            except tk.TclError:
                pass
        # the Formulas list draws its formulas as images in the text color,
        # so it is rebuilt (not just re-tinted) whenever the theme moves
        try:
            self._refresh_quantity_rows()
        except Exception as _qr_err:
            # a broken formula list used to disappear here without a word
            try:
                self._logline("! formula list refresh failed: %r" % _qr_err)
            except Exception:
                pass
        for m in getattr(self, "_lf_markers", []):
            try:
                _hn = getattr(m, "_hdr_icon", None)
                _hi = ic.get("hdr::" + _hn) if _hn else None
                if _hi is not None:
                    m.configure(image=_hi, text="")
                else:
                    m.configure(foreground=br["ac2"])
            except tk.TclError:
                pass
        self._iconize_buttons()
        self._sync_tab_icons()
        self._sync_panel_btns()
        seticon(getattr(self, "undo_btn", None), "undo", compound="image")
        seticon(getattr(self, "redo_btn", None), "redo", compound="image")
        try:
            self.log.tag_config("logerr",
                                foreground=self._semantic_fg(SEM_BAD))
            self.log.tag_config("logwarn",
                                foreground=self._semantic_fg(SEM_WARN))
        except (tk.TclError, AttributeError):
            pass
        try:
            _u3, _f3, fld3, _pb3, _pf3 = self._theme_palette()
            stripe = ((self._shade(fld3, 1.35) if self.dark_mode.get()
                       else self._shade(fld3, 0.955))
                      if fld3.startswith("#") else "#f4f2ec")
            self._drawer_tv.tag_configure("even", background=fld3)
            self._drawer_tv.tag_configure("odd", background=stripe)
        except (tk.TclError, AttributeError):
            pass
        uibg2, _fg2, _fl2, _pb2, _pf2 = self._theme_palette()
        if uibg2.startswith("#"):
            r2 = int(uibg2[1:3], 16); g2 = int(uibg2[3:5], 16)
            b2 = int(uibg2[5:7], 16)
            if self.dark_mode.get():
                tr = "#%02x%02x%02x" % (min(255, r2 + 42),
                                        min(255, g2 + 42),
                                        min(255, b2 + 42))
            else:
                tr = self._shade(uibg2, 0.88)
        else:
            tr = "#d9d5c9"
        keep2 = []
        page = uibg2 if uibg2.startswith("#") else "#f1eee6"
        for sc in getattr(self, "_theme_scales", []):
            try:
                sc.retint(bg=page, trough=tr, fill=br["ac1"],
                          knob=br["ac1"], ring=page, hov=br["hov"])
                keep2.append(sc)
            except tk.TclError:
                pass
        self._theme_scales = keep2
        undo = ic.get("undo12")
        keep3 = []
        for rb in getattr(self, "_slider_resets", []):
            try:
                if undo is not None:
                    rb.configure(image=undo)
                keep3.append(rb)
            except tk.TclError:
                pass
        self._slider_resets = keep3
        keep4 = []
        for lab, name in getattr(self, "_slider_iconlabels", []):
            img = ic.get("sl::" + name)
            try:
                if img is not None:
                    lab.configure(image=img, compound="left")
                    _t4 = lab.cget("text")
                    if _t4 and not _t4.startswith(" "):
                        lab.configure(text=" " + _t4)
                keep4.append((lab, name))
            except tk.TclError:
                pass
        self._slider_iconlabels = keep4
        if getattr(self, "_qa_title", None) is not None:
            self._qa_caret()             # icons regenerate every theme
        for _k in getattr(self, "_ccards", {}):
            self._card_caret(_k)
            try:
                self._qa_title.configure(foreground=self._head_fg())
            except tk.TclError:
                pass

    def _make_icons(self):
        """The SPARTA geometric icon set (DESIGN_RULES.md #5): drawn with
        PIL at 2x and cached as PhotoImages, tinted from the active theme.
        White glyphs live on ac1 brand buttons; ink glyphs on plain chrome;
        ac2 is the single allowed accent fill."""
        try:
            from PIL import Image, ImageDraw, ImageTk
        except Exception:
            self._icons = {}
            self._icon_pil, self._icon_flat = {}, {}
            return
        br = self._brand()
        _u, fg, _fl, _pb, _pf = self._theme_palette()
        ic = {}
        _pil = {}

        def new(sz=16):
            im = Image.new("RGBA", (sz * 2, sz * 2), (0, 0, 0, 0))
            return im, ImageDraw.Draw(im), sz

        def keep(name, im, sz):
            _r = im.resize((sz, sz), Image.LANCZOS)
            ic[name] = ImageTk.PhotoImage(_r)
            _pil[ic[name]] = _r          # RoundButton flattens these itself

        W = 3                                # ~1.5px stroke after downscale
        # run + data table, drawn in BOTH inks (rule 36): the "_w" twin
        # rides the ac1 brand buttons, the plain one rides ordinary chrome.
        # Only the white pair used to exist, so every plain button the
        # label map handed a "table" to - "Thickness table...", "Open in
        # Excel" - wore a white glyph on a light background, which is to
        # say no glyph at all. The Quick Access function pins need the ink
        # pair too.
        for _sfx, _gc in (("_w", "#ffffff"), ("", fg)):
            im, d, sz = new()
            d.polygon([(11, 7), (26, 16), (11, 25)], fill=_gc)
            keep("run" + _sfx, im, sz)
            im, d, sz = new()
            d.rectangle([6, 8, 26, 24], outline=_gc, width=W)
            d.line([6, 14, 26, 14], fill=_gc, width=W)
            d.line([14, 8, 14, 24], fill=_gc, width=W)
            keep("table" + _sfx, im, sz)
        # reload (Load previous run): open arc + arrowhead, ink
        im, d, sz = new()
        d.arc([7, 7, 25, 25], start=300, end=210, fill=fg, width=W)
        d.polygon([(4, 12), (13, 10), (8, 18)], fill=fg)
        keep("prev", im, sz)
        # reset view: register target, ink ring + ac2 center
        im, d, sz = new()
        d.ellipse([8, 8, 24, 24], outline=fg, width=W)
        d.line([16, 3, 16, 9], fill=fg, width=W)
        d.line([16, 23, 16, 29], fill=fg, width=W)
        d.line([3, 16, 9, 16], fill=fg, width=W)
        d.line([23, 16, 29, 16], fill=fg, width=W)
        d.ellipse([13, 13, 19, 19], fill=br["ac2"])
        keep("reset", im, sz)
        # pan: four-way arrows, ink
        im, d, sz = new()
        d.line([16, 5, 16, 27], fill=fg, width=W)
        d.line([5, 16, 27, 16], fill=fg, width=W)
        for tri in ([(16, 2), (12, 8), (20, 8)], [(16, 30), (12, 24), (20, 24)],
                    [(2, 16), (8, 12), (8, 20)], [(30, 16), (24, 12), (24, 20)]):
            d.polygon(tri, fill=fg)
        keep("pan", im, sz)
        # zoom: magnifier, ink
        im, d, sz = new()
        d.ellipse([6, 6, 20, 20], outline=fg, width=W)
        d.line([19, 19, 27, 27], fill=fg, width=W + 1)
        keep("zoom", im, sz)
        # save: tray with down arrow, ink
        im, d, sz = new()
        d.line([16, 5, 16, 19], fill=fg, width=W)
        d.polygon([(16, 23), (11, 16), (21, 16)], fill=fg)
        d.line([6, 26, 26, 26], fill=fg, width=W)
        keep("save", im, sz)
        # folder / folder-open, ink
        im, d, sz = new()
        d.polygon([(4, 9), (13, 9), (15, 12), (28, 12), (28, 25), (4, 25)],
                  outline=fg, width=W)
        keep("folder", im, sz)
        im, d, sz = new()
        d.polygon([(4, 9), (13, 9), (15, 12), (26, 12), (26, 14), (30, 14),
                   (25, 25), (4, 25)], outline=fg, width=W)
        keep("folder_open", im, sz)
        # copy: two offset squares, ink
        im, d, sz = new()
        d.rectangle([10, 4, 26, 20], outline=fg, width=W)
        d.rectangle([5, 11, 21, 27], outline=fg, width=W)
        keep("copy", im, sz)
        # share/export-settings: tray with UP arrow, ink
        im, d, sz = new()
        d.line([16, 25, 16, 11], fill=fg, width=W)
        d.polygon([(16, 5), (11, 12), (21, 12)], fill=fg)
        d.line([6, 27, 26, 27], fill=fg, width=W)
        keep("share", im, sz)
        # collapse / expand chevrons, ink
        im, d, sz = new()
        d.line([8, 14, 16, 7], fill=fg, width=W)
        d.line([16, 7, 24, 14], fill=fg, width=W)
        d.line([8, 24, 16, 17], fill=fg, width=W)
        d.line([16, 17, 24, 24], fill=fg, width=W)
        keep("chev_up", im, sz)
        im, d, sz = new()
        d.line([8, 8, 16, 15], fill=fg, width=W)
        d.line([16, 15, 24, 8], fill=fg, width=W)
        d.line([8, 18, 16, 25], fill=fg, width=W)
        d.line([16, 25, 24, 18], fill=fg, width=W)
        keep("chev_dn", im, sz)
        # step-left / step-right chevrons (the colormap arrows)
        im, d, sz = new()
        d.line([19, 7, 12, 16], fill=fg, width=W)
        d.line([12, 16, 19, 25], fill=fg, width=W)
        keep("chev_l", im, sz)
        im, d, sz = new()
        d.line([13, 7, 20, 16], fill=fg, width=W)
        d.line([20, 16, 13, 25], fill=fg, width=W)
        keep("chev_r", im, sz)
        # [?] help: a Bauhaus square holding a drawn question mark, ac2
        # (the fringe cards' glyph, stroke for stroke, so the sets match)
        im, d, sz = new()
        d.rectangle([3, 3, 29, 29], outline=br["ac2"], width=W)
        d.arc([10, 7, 22, 17], start=180, end=90, fill=br["ac2"], width=W)
        d.line([16, 17, 16, 20], fill=br["ac2"], width=W)
        d.ellipse([14, 23, 18, 26], fill=br["ac2"])
        keep("help", im, sz)
        # gear: ring + spokes in ac2 (the ingestion entry point)
        im, d, sz = new()
        d.ellipse([9, 9, 23, 23], outline=br["ac2"], width=W)
        for a, b in (((16, 4), (16, 9)), ((16, 23), (16, 28)),
                     ((4, 16), (9, 16)), ((23, 16), (28, 16)),
                     ((7, 7), (11, 11)), ((21, 21), (25, 25)),
                     ((7, 25), (11, 21)), ((21, 11), (25, 7))):
            d.line([a, b], fill=br["ac2"], width=W)
        keep("gear", im, sz)
        # anvil mark: the brand logo (two ink anvils pressing the sample).
        # The anvils take the STRUCTURAL ink, not the raw text color -- the
        # mark is a rule, not a word, and ink is the tone the 2 px section
        # rules already use in this theme. The sample takes _signal_fg, so
        # it cannot wash out on the bright themes.
        _mink = br["ink"]
        _msig = self._signal_fg()
        for name, px in (("mark", max(20, self._body_size + 10)),
                         ("mark_lg", 44), ("mark_xl", 96)):
            im, d, _ = new(px)
            s = px * 2
            d.polygon([(s*0.15, s*0.08), (s*0.85, s*0.08),
                       (s*0.68, s*0.36), (s*0.32, s*0.36)], fill=_mink)
            d.polygon([(s*0.32, s*0.64), (s*0.68, s*0.64),
                       (s*0.85, s*0.92), (s*0.15, s*0.92)], fill=_mink)
            r = s * 0.09
            d.ellipse([s*0.5 - r, s*0.5 - r, s*0.5 + r, s*0.5 + r],
                      fill=_msig)
            keep(name, im, px)
        # section mini-icons (12px, ac2): one distinct geometric glyph per
        # right-panel section, replacing the plain square markers (plan B3)
        A = br["ac2"]

        def sec(name, fn):
            im, d, _ = new(12)
            fn(d)
            keep("sec::" + name, im, 12)
        sec("Plot mode", lambda d: (d.ellipse([3, 3, 21, 21], outline=A,
            width=W), d.ellipse([9, 9, 15, 15], fill=A)))
        sec("Stacked & 3D", lambda d: (
            d.line([3, 7, 21, 7], fill=A, width=W),
            d.line([3, 13, 21, 13], fill=A, width=W),
            d.line([3, 19, 21, 19], fill=A, width=W)))
        sec("2D plot options", lambda d: d.line(
            [3, 19, 9, 9, 14, 14, 21, 4], fill=A, width=W))
        sec("3D plot options", lambda d: (
            d.rectangle([3, 8, 15, 20], outline=A, width=W),
            d.rectangle([9, 3, 21, 15], outline=A, width=W)))
        sec("Axis", lambda d: (d.line([5, 3, 5, 19], fill=A, width=W),
                               d.line([5, 19, 21, 19], fill=A, width=W)))
        sec("Limits & scale", lambda d: (
            d.line([8, 3, 3, 3], fill=A, width=W),
            d.line([3, 3, 3, 21], fill=A, width=W),
            d.line([3, 21, 8, 21], fill=A, width=W),
            d.line([16, 3, 21, 3], fill=A, width=W),
            d.line([21, 3, 21, 21], fill=A, width=W),
            d.line([21, 21, 16, 21], fill=A, width=W)))
        sec("Ticks", lambda d: (d.line([3, 17, 21, 17], fill=A, width=W),
                                d.line([7, 17, 7, 10], fill=A, width=W),
                                d.line([13, 17, 13, 10], fill=A, width=W),
                                d.line([19, 17, 19, 10], fill=A, width=W)))
        sec("Frame & grid", lambda d: (
            d.rectangle([3, 3, 21, 21], outline=A, width=W),
            d.line([3, 12, 21, 12], fill=A, width=2),
            d.line([12, 3, 12, 21], fill=A, width=2)))
        sec("Colors & colormap", lambda d: (
            d.rectangle([3, 8, 9, 16], fill=A),
            d.rectangle([10, 8, 15, 16], outline=A, width=2),
            d.rectangle([16, 8, 21, 16], fill=A)))
        sec("Fonts", lambda d: (d.line([5, 21, 12, 3], fill=A, width=W),
                                d.line([12, 3, 19, 21], fill=A, width=W),
                                d.line([8, 14, 16, 14], fill=A, width=W)))
        sec("Title & axis labels", lambda d: (
            d.line([4, 4, 20, 4], fill=A, width=W),
            d.line([12, 4, 12, 21], fill=A, width=W)))
        sec("Legend", lambda d: (d.rectangle([3, 5, 9, 11], fill=A),
                                 d.line([12, 8, 21, 8], fill=A, width=W),
                                 d.rectangle([3, 14, 9, 20], outline=A,
                                             width=2),
                                 d.line([12, 17, 21, 17], fill=A, width=W)))
        sec("Colorbar", lambda d: (
            d.rectangle([8, 3, 16, 9], fill=A),
            d.rectangle([8, 9, 16, 15], outline=A, width=2),
            d.rectangle([8, 15, 16, 21], fill=A)))
        sec("Reference lines", lambda d: (
            d.line([12, 3, 12, 7], fill=A, width=W),
            d.line([12, 10, 12, 14], fill=A, width=W),
            d.line([12, 17, 12, 21], fill=A, width=W)))
        sec("Smoothing", lambda d: d.arc([3, 6, 21, 20], 180, 360,
                                         fill=A, width=W))
        sec("Traces", lambda d: (
            d.line([3, 7, 8, 12], fill=A, width=W),
            d.line([8, 12, 14, 4], fill=A, width=W),
            d.line([3, 19, 21, 19], fill=A, width=W)))
        sec("Formulas", lambda d: (d.line([4, 12, 20, 12], fill=A, width=W),
                                   d.ellipse([9, 3, 15, 9], fill=A),
                                   d.ellipse([9, 15, 15, 21], fill=A)))
        sec("Presets & projects", lambda d: d.polygon(
            [(12, 3), (15, 9), (21, 12), (15, 15), (12, 21), (9, 15),
             (3, 12), (9, 9)], fill=A))
        sec("Export", lambda d: (d.line([12, 3, 12, 13], fill=A, width=W),
                                 d.polygon([(12, 17), (8, 11), (16, 11)],
                                           fill=A),
                                 d.line([4, 20, 20, 20], fill=A, width=W)))
        sec("Figure", lambda d: (d.rectangle([3, 5, 21, 19], outline=A,
                                             width=W),
                                 d.ellipse([6, 8, 11, 13], fill=A)))
        im, d, _ = new(12)
        d.rectangle([7, 7, 17, 17], fill=A)
        keep("sec_dot", im, 12)
        # mini glyphs for slider rows + the small per-slider reset
        def mini(name, fn):
            im2, d2, _ = new(13)
            fn(d2)
            keep(name, im2, 13)
        mini("undo12", lambda d2: (
            d2.arc([5, 5, 21, 21], start=300, end=210, fill=fg, width=3),
            d2.polygon([(2, 10), (11, 8), (6, 16)], fill=fg)))
        mini("sl::opacity", lambda d2: (
            d2.ellipse([4, 4, 22, 22], outline=fg, width=2),
            d2.pieslice([4, 4, 22, 22], 270, 90, fill=fg)))
        mini("sl::angle", lambda d2: (
            d2.line([5, 21, 21, 21], fill=fg, width=2),
            d2.line([5, 21, 17, 6], fill=fg, width=2),
            d2.arc([5, 10, 19, 26], 290, 360, fill=fg, width=2)))
        mini("sl::rotate", lambda d2: (
            d2.arc([5, 5, 21, 21], start=0, end=280, fill=fg, width=3),
            d2.polygon([(24, 10), (16, 8), (21, 16)], fill=fg)))
        mini("sl::zoomm", lambda d2: (
            d2.ellipse([4, 4, 17, 17], outline=fg, width=2),
            d2.line([16, 16, 23, 23], fill=fg, width=3)))
        mini("sl::arr_h", lambda d2: (
            d2.line([5, 13, 21, 13], fill=fg, width=2),
            d2.polygon([(2, 13), (7, 9), (7, 17)], fill=fg),
            d2.polygon([(24, 13), (19, 9), (19, 17)], fill=fg)))
        mini("sl::arr_v", lambda d2: (
            d2.line([13, 5, 13, 21], fill=fg, width=2),
            d2.polygon([(13, 2), (9, 7), (17, 7)], fill=fg),
            d2.polygon([(13, 24), (9, 19), (17, 19)], fill=fg)))
        mini("sl::arr_d", lambda d2: (
            d2.line([6, 20, 20, 6], fill=fg, width=2),
            d2.polygon([(22, 3), (15, 6), (20, 11)], fill=fg),
            d2.polygon([(4, 23), (11, 20), (6, 15)], fill=fg)))
        mini("sl::widthI", lambda d2: (
            d2.line([4, 9, 22, 9], fill=fg, width=1),
            d2.line([4, 17, 22, 17], fill=fg, width=4)))
        mini("sl::detail", lambda d2: (
            d2.ellipse([4, 11, 8, 15], fill=fg),
            d2.ellipse([11, 10, 16, 15], fill=fg),
            d2.ellipse([19, 9, 25, 15], fill=fg)))
        # check + cross for in-panel action buttons (plan: iconology)
        im, d, sz = new()
        d.line([6, 17, 13, 24], fill=fg, width=W + 1)
        d.line([13, 24, 26, 8], fill=fg, width=W + 1)
        keep("check", im, sz)
        im, d, sz = new()
        d.line([8, 8, 24, 24], fill=fg, width=W + 1)
        d.line([8, 24, 24, 8], fill=fg, width=W + 1)
        keep("cross", im, sz)
        # collapse carets as images: the text glyphs came from two different
        # fallback fonts and rendered at two sizes. Mustard (ac3) per Nhan.
        im, d, _ = new(13)
        d.polygon([(4, 8), (22, 8), (13, 20)], fill=br["ac3"])
        keep("caret_open", im, 13)
        im, d, _ = new(13)
        d.polygon([(8, 4), (20, 13), (8, 22)], fill=br["ac3"])
        keep("caret_closed", im, 13)
        # padlock: the read-only marker beside a built-in quantity
        im, d, _ = new(12)
        d.arc([8, 4, 16, 14], start=180, end=360, fill=fg, width=3)
        d.rectangle([5, 11, 19, 21], fill=fg)
        keep("lock", im, 12)
        # ---- v1.4.8 icon pass -------------------------------------------
        # panel-collapse glyphs: a pane rectangle with the folding side
        # filled while that panel is open, hollow once it is hidden
        def panel(name, right, filled):
            im2, d2, s2 = new()
            d2.rectangle([4, 7, 28, 25], outline=fg, width=W)
            box = [19, 7, 28, 25] if right else [4, 7, 13, 25]
            if filled:
                d2.rectangle(box, fill=fg)
            else:
                x = box[0] if right else box[2]
                d2.line([x, 7, x, 25], fill=fg, width=W)
            keep(name, im2, s2)
        panel("panel_l", False, True)
        panel("panel_l_off", False, False)
        panel("panel_r", True, True)
        panel("panel_r_off", True, False)
        # undo / redo at button size (undo12 is the slider-row miniature):
        # a bent arrow, NOT a ring -- two rings side by side read as the
        # same button, and the panel already spends rings on prev/refresh
        im, d, sz = new()
        d.polygon([(3, 12), (14, 5), (14, 19)], fill=fg)
        d.line([12, 12, 20, 12], fill=fg, width=W)
        d.arc([12, 12, 28, 28], start=270, end=60, fill=fg, width=W)
        keep("undo", im, sz)
        im, d, sz = new()
        d.polygon([(29, 12), (18, 5), (18, 19)], fill=fg)
        d.line([12, 12, 20, 12], fill=fg, width=W)
        d.arc([4, 12, 20, 28], start=120, end=270, fill=fg, width=W)
        keep("redo", im, sz)
        # refresh (Rescan): a ring with a barb at its open end
        im, d, sz = new()
        d.arc([7, 7, 25, 25], start=45, end=330, fill=fg, width=W)
        d.polygon([(19, 4), (29, 8), (21, 14)], fill=fg)
        keep("refresh", im, sz)
        # sparkle (Guess format): the one "the tool works it out" action.
        # White twin for the ac1 brand buttons, ink twin for plain chrome.
        def spark(name, col):
            im2, d2, s2 = new()
            d2.polygon([(12, 8), (15, 16), (23, 19), (15, 22), (12, 30),
                        (9, 22), (1, 19), (9, 16)], fill=col)
            d2.polygon([(25, 4), (27, 9), (31, 11), (27, 13), (25, 18),
                        (23, 13), (19, 11), (23, 9)], fill=col)
            keep(name, im2, s2)
        spark("wand", fg)
        spark("wand_w", "#ffffff")
        # white check for a primary brand button (the ink one is "check")
        im, d, sz = new()
        d.line([6, 17, 13, 24], fill="#ffffff", width=W + 1)
        d.line([13, 24, 26, 8], fill="#ffffff", width=W + 1)
        keep("check_w", im, sz)
        # plus / pencil / eye: new, edit, look-without-touching
        im, d, sz = new()
        d.line([16, 6, 16, 26], fill=fg, width=W + 1)
        d.line([6, 16, 26, 16], fill=fg, width=W + 1)
        keep("plus", im, sz)
        im, d, sz = new()
        d.polygon([(6, 28), (10, 21), (21, 5), (27, 9), (16, 25)],
                  outline=fg, width=W)
        keep("pencil", im, sz)
        im, d, sz = new()
        d.ellipse([3, 7, 29, 25], outline=fg, width=W)
        d.ellipse([12, 11, 20, 21], fill=fg)
        keep("eye", im, sz)
        # card-title glyphs (12 px, ac2): the SAME slot the plain square
        # marker uses, handed out only where the picture adds meaning
        def hdr(name, fn):
            im2, d2, _z = new(12)
            fn(d2)
            keep("hdr::" + name, im2, 12)
        hdr("folder", lambda d2: d2.polygon(
            [(2, 5), (9, 5), (11, 8), (22, 8), (22, 19), (2, 19)],
            outline=A, width=W))
        hdr("folder_open", lambda d2: d2.polygon(
            [(2, 5), (9, 5), (11, 8), (20, 8), (20, 10), (23, 10),
             (19, 19), (2, 19)], outline=A, width=W))
        hdr("log", lambda d2: (d2.line([3, 6, 21, 6], fill=A, width=W),
                               d2.line([3, 12, 21, 12], fill=A, width=W),
                               d2.line([3, 18, 14, 18], fill=A, width=W)))
        hdr("book", lambda d2: (d2.rectangle([3, 3, 21, 21], outline=A,
                                             width=W),
                                d2.line([12, 3, 12, 21], fill=A, width=W)))
        hdr("pencil", lambda d2: d2.polygon(
            [(3, 21), (6, 15), (16, 3), (21, 7), (11, 19)],
            outline=A, width=W))
        hdr("eye", lambda d2: (d2.ellipse([2, 5, 22, 19], outline=A,
                                          width=W),
                               d2.ellipse([9, 8, 15, 16], fill=A)))
        # right-panel notebook tabs (14 px, ac2) and their 12 px twins:
        # _fit_tab_padding steps down to "tabsm::" in a narrow pane to buy
        # air between the tabs before it ever touches the type size
        def tabi(name, fn):
            im2, d2, _z = new(14)
            fn(d2)
            keep("tab::" + name, im2, 14)
            keep("tabsm::" + name, im2, 12)
        tabi("Plot", lambda d2: d2.line([3, 22, 10, 12, 16, 17, 25, 5],
                                        fill=A, width=W))
        tabi("Axes", lambda d2: (d2.line([6, 4, 6, 22], fill=A, width=W),
                                 d2.line([6, 22, 24, 22], fill=A, width=W),
                                 d2.polygon([(6, 1), (2, 8), (10, 8)],
                                            fill=A),
                                 d2.polygon([(27, 22), (20, 18), (20, 26)],
                                            fill=A)))
        tabi("Style", lambda d2: (d2.polygon([(20, 3), (25, 8), (12, 21),
                                              (7, 16)], fill=A),
                                  d2.polygon([(7, 16), (12, 21), (5, 26),
                                              (2, 24)], outline=A, width=W)))
        tabi("Data", lambda d2: (d2.rectangle([3, 5, 25, 23], outline=A,
                                              width=W),
                                 d2.line([3, 11, 25, 11], fill=A, width=W),
                                 d2.line([11, 5, 11, 23], fill=A, width=W)))
        tabi("Export", lambda d2: (d2.line([14, 22, 14, 7], fill=A, width=W),
                                   d2.polygon([(14, 2), (9, 10), (19, 10)],
                                              fill=A),
                                   d2.line([4, 25, 24, 25], fill=A, width=W)))
        # fringe: one and a half periods of an interference wave, the
        # workbench's whole subject. Sampled every pixel at 2x so the curve
        # survives the downscale, and SMOOTH on purpose - Plot's glyph is
        # the angular trace, and two zigzags side by side would not read.
        _wave = [(_x, 14.0 - 7.0 * float(np.sin((_x - 2) * np.pi / 8.0)))
                 for _x in range(2, 27)]
        tabi("Fringe", lambda d2: d2.line(_wave, fill=A, width=W))
        self._icons = ic
        self._icon_pil, self._icon_flat = _pil, {}

    def _repaint_svttk_accent(self):
        """Evict sv_ttk's baked-in Fluent blue (plan B2): remap the accent-
        hue pixels of every theme sprite to the triad's ac1, so checkboxes,
        radios, switches, sliders and focus rings follow the brand in every
        theme. Originals are cached per (base, image) so a re-theme always
        starts from stock; our own PIL icons (pyimage*) are never touched."""
        if not _HAVE_SVTTK:
            return
        try:
            import base64
            import colorsys
            import io as _io
            from PIL import Image
        except Exception:
            return
        br = self._brand()
        ac = br["ac1"]
        r1, g1, b1 = (int(ac[i:i + 2], 16) for i in (1, 3, 5))
        h1, s1, _v1 = colorsys.rgb_to_hsv(r1 / 255, g1 / 255, b1 / 255)
        base = "dark" if self.dark_mode.get() else "light"
        cache = getattr(self, "_sv_orig", None)
        if cache is None:
            cache = self._sv_orig = {}
        done = getattr(self, "_sv_done", None)
        if done is None:
            done = self._sv_done = {}
        try:
            names = [str(n) for n in self.root.tk.call("image", "names")]
        except tk.TclError:
            return
        for n in names:
            if n.startswith("pyimage"):
                continue
            if done.get(n) == (base, ac):
                continue
            ck = (base, n)
            try:
                if ck not in cache:
                    cache[ck] = str(self.root.tk.call(
                        n, "data", "-format", "png"))
                im = Image.open(_io.BytesIO(
                    base64.b64decode(cache[ck]))).convert("RGBA")
            except Exception:
                continue
            cols = im.getcolors(200000)
            if not cols:
                continue
            lut = {}
            for _cnt, px in cols:
                r, g, b, a2 = px
                if a2 == 0:
                    continue
                h, s, v = colorsys.rgb_to_hsv(r / 255, g / 255, b / 255)
                if 190 <= h * 360 <= 235 and s >= 0.25 and v >= 0.25:
                    nr, ng, nb = colorsys.hsv_to_rgb(
                        h1, min(1.0, s1 * (0.35 + 0.75 * s)), v)
                    lut[px] = (int(nr * 255), int(ng * 255),
                               int(nb * 255), a2)
            if lut:
                im.putdata([lut.get(q, q) for q in im.getdata()])
                buf = _io.BytesIO()
                im.save(buf, "png")
                b64 = base64.b64encode(buf.getvalue()).decode("ascii")
                try:
                    self.root.tk.call(n, "configure", "-data", b64)
                except tk.TclError:
                    continue
            done[n] = (base, ac)

    def _combo_home(self, ev_or_widget):
        """Scroll a combobox's text back to its first character.

        Bound on the TCombobox class bindtag for the events that leave the
        entry view moved, and callable directly with a widget wherever a
        value is written after build. Deferred to the idle loop: at the
        moment of the event the box may not have its final width yet, and
        `xview_moveto` on a stale width is a no-op."""
        w = getattr(ev_or_widget, "widget", ev_or_widget)
        try:
            w.after_idle(lambda: w.xview_moveto(0.0))
        except (tk.TclError, AttributeError):
            pass

    def _sync_combo_popdowns(self, fld, fg):
        """ttk builds each Combobox's popdown list once and never re-reads the
        option database, so a dropdown opened under the first theme keeps its
        old colours (the "theme menu stuck on the first theme" bug -- often
        dark text on a dark list). Push the active palette straight onto every
        already-built popdown listbox."""
        seen = []

        def walk(w):
            try:
                kids = w.winfo_children()
            except tk.TclError:
                return
            for c in kids:
                try:
                    if c.winfo_class() == "TCombobox":
                        seen.append(str(c))
                except tk.TclError:
                    pass
                walk(c)
        walk(self.root)
        for name in seen:
            pop = name + ".popdown"
            try:
                if not int(self.root.tk.call("winfo", "exists", pop)):
                    continue
                lb = pop + ".f.l"
                self.root.tk.call(lb, "configure", "-background", fld,
                                  "-foreground", fg, "-selectbackground", fg,
                                  "-selectforeground", fld)
            except tk.TclError:
                pass

    def _lf_header(self, parent, text, icon=None):
        """Brand header for a left-panel LabelFrame: ac2 marker + bold
        title, matching the right panel's section language (plan B4).

        `icon` names an hdr:: glyph that replaces the plain square. It is
        handed out only where the picture says something the word does not
        (the folder cards, Progress, the Guide / Input / Preview cards);
        the icon set does not exist yet while the main window is being
        built, so the square is drawn first and _apply_brand restamps it."""
        f = ttk.Frame(parent)
        img = (getattr(self, "_icons", {}).get("hdr::" + icon)
               if icon else None)
        if img is not None:
            m = self._lbl(f, image=img)
        else:
            m = self._lbl(f, text="\u25a0", font=self._F(-2),
                          foreground=self._brand()["ac2"])
        m._hdr_icon = icon
        m.pack(side="left", padx=(0, 4))
        self._lf_markers = getattr(self, "_lf_markers", [])
        self._lf_markers.append(m)
        self._lbl(f, text=text, font=self._F(1, "bold")).pack(side="left")
        return f

    def _iconize_buttons(self, root=None):
        """Give in-panel buttons a matching mini icon by their label text
        (Nhan: iconology for the right-panel settings). Re-attached on
        every theme switch because the icon set is regenerated. `root`
        limits the walk to one window -- a dialog calls it on itself once
        it is built, since it is born long after the last theme switch."""
        ic = getattr(self, "_icons", {})
        m = {"Apply": "check", "Apply ticks": "check",
             "Apply limits": "check",
             "Reset": "reset", "Reset all": "reset", "Reset axes": "reset",
             "Reset stretch": "reset", "Defaults": "reset",
             "Save plot…": "save", "Save as…": "save",
             "Save project…": "save",
             "Copy figure": "copy", "Copy log": "copy",
             "Copy all (TSV)": "copy",
             "Load": "folder_open", "Open project…": "folder_open",
             "Open in Excel": "table",
             "Export data…": "share", "Export settings": "share",
             "Batch export (one per shown trace)…": "share",
             "Smoothing settings…": "gear",
             "Decompression list…": "folder",
             "Delete": "cross", "Clear": "cross",
             # v1.4.8 icon pass: one glyph per obvious verb, nothing more
             "Rescan": "refresh",
             "New…": "plus",
             "Edit…": "pencil", "View": "eye",
             "Fix selected…": "pencil",
             "Remove fix": "cross", "Clear all fixes": "cross",
             "Exclude selected": "cross",
             "Save formula CSVs…": "save",
             "Save C/D-tagged CSVs…": "save",
             "Export D list (CSV) by selection": "share",
             "Absorbance readout at…": "zoom",
             "Thickness table…": "table"}

        # half the map was written with the ellipsis character while the
        # buttons spell theirs with three dots, so those entries had never
        # matched anything: normalise before the lookup.
        def _k(t):
            return str(t).replace("...", "…")

        def walk(w):
            for c in w.winfo_children():
                if c.winfo_class() == "TButton":
                    try:
                        img = ic.get(m.get(_k(c.cget("text")), ""))
                        if img is not None:
                            c.configure(image=img, compound="left")
                    except tk.TclError:
                        pass
                walk(c)
        walk(root if root is not None else self.root)

    _TAB_ELEM = "SpartaNotebook.tab"

    def _install_tab_element(self):
        """Take the right-panel tabs off sv_ttk's baked-in horizontal air.

        sv_ttk creates ``Notebook.tab`` with ``-padding {16 14 16 6}``: 32 px
        of air per tab, a fixed pixel figure that scales with neither the App
        text size nor the Windows DPI. Six tabs then ask for ~550 px inside a
        ~500 px panel and every label loses its tail ("Plo", "Expor",
        "Fring"). The element is rebuilt here from the SAME sprites with the
        horizontal padding taken out, which moves the air to the style's
        ``-padding`` where `_fit_tab_padding` can size it to the room that
        actually exists. The vertical padding is kept exactly as sv_ttk had
        it, so the strip's height never moves.

        The same pass drops sv_ttk's ``Notebook.border`` element from the
        TNotebook layout (R2 item 4): that sprite drew a thin gray ring
        around the whole settings panel that read as default-ttk chrome
        next to the flat tab strip and the sections' own ink rules. The
        panel edge is flat now, and the border sprite's 5 px of inner
        air is re-provided as TNotebook -padding so nothing moves.

        Per theme, once: ttk keeps element tables and layouts per theme, and
        a second ``element create`` under one name is an error."""
        if not _HAVE_SVTTK:
            return False                      # clam fallback: style-driven
        if getattr(self, "_tab_elem_themes", None) is None:
            self._tab_elem_themes = set()
        try:
            theme = str(ttk.Style().theme_use())
        except tk.TclError:
            return False
        ns = {"sun-valley-dark": "ttk::theme::sv_dark",
              "sun-valley-light": "ttk::theme::sv_light"}.get(theme)
        if ns is None:
            return False
        if theme in self._tab_elem_themes:
            return True
        sprite = "$" + ns + "::I(tab-%s)"
        create = ("ttk::style element create " + self._TAB_ELEM +
                  " image [list " + sprite % "rest" +
                  " selected " + sprite % "selected" +
                  " active " + sprite % "hover" + "]"
                  " -border 13 -padding {0 14 0 6} -height 32")
        layout = ("ttk::style layout TNotebook.Tab {" + self._TAB_ELEM +
                  " -children {Notebook.padding -side top -sticky nswe"
                  " -children {Notebook.focus -side top -sticky nswe"
                  " -children {Notebook.label -side top -sticky {}}}}}")
        flat = ("ttk::style layout TNotebook {TNotebook.Tab -expand 1};"
                " ttk::style configure TNotebook -padding {4 2 4 4}")
        try:
            self.root.tk.eval("ttk::style theme settings " + theme +
                              " {" + create + "; " + layout + "; " + flat + "}")
        except tk.TclError:
            return False
        self._tab_elem_themes.add(theme)
        return True

    def _fit_tab_padding(self):
        """Size the tabs' horizontal air to the room there actually is.

        All six right-panel labels must read in full at every App text size
        and every DPI, so the air is measured, never hardcoded: whatever is
        left once every label and its glyph has its own width, split evenly
        over the tabs. Called at the end of `_sync_tab_icons`, so a theme
        switch (which regenerates the glyphs) and a text-size change (which
        goes through `_apply_brand`) both re-fit.

        Comfort has a floor now too (R2 item 3, the bunched-strip
        screenshot): with less than `comfort` px of air per tab side, two
        neighbouring icon+label pairs read as one run of text. Air is
        bought in this order - the 12 px glyph twins first ("prefer
        slightly smaller tab glyphs over cramping"), the type size only
        after, one point at a time down to `max(6, top - 3)`. The first
        candidate whose per-side air clears the comfort floor wins; when
        none does, the airiest one wins, floored at 1 px, so the no-clip
        guarantee (the fitted strip never asks for more room than there
        is) holds exactly as before. All of it is derived, never
        switched: the moment there is room again the tabs are back to
        the full glyphs at `_body_size + 1`."""
        nb = getattr(self, "rnotebook", None)
        self._tabfit_job = None
        if nb is None:
            return
        try:
            tabs = list(nb.tabs())
        except tk.TclError:
            return
        if not tabs:
            return
        try:
            st = ttk.Style()
            ic = getattr(self, "_icons", {})
            labels = [str(nb.tab(t, "text")) for t in tabs]

            def glyphs_w(prefix):
                w = 0
                for lab in labels:
                    img = ic.get(prefix + lab.strip())
                    if img is not None:
                        w += int(self.root.tk.call("image", "width",
                                                   str(img)))
                return w

            room = nb.winfo_width()
            if room <= 1:                     # not mapped yet: use the pane
                room = self._pane_widths()[3] - self._em() * 2
            # Chrome is measured, not guessed: the strip starts 4 px in,
            # ends 4 px short (TNotebook -padding), and EVERY tab carries
            # 6 px of fixed chrome (focus + internal padding) beyond
            # glyph + label + 2*pad -- probed with ttk's own identify at
            # two pads, exactly 6 at both. Model it, or ttk squeezes the
            # strip and the last label pays the difference in clipped
            # letters.
            room -= 6 * len(tabs) + 8
            n2 = 2 * len(tabs)
            top = int(getattr(self, "_body_size", 9)) + 1
            comfort = max(3, self._em() // 3)
            _uf = self._ui_faces()[0]
            fnt = tkfont.Font(family=_uf, size=top, weight="bold")
            cands = [("tab::", top)] + [
                ("tabsm::", s) for s in range(top, max(6, top - 3) - 1, -1)]
            best = None
            for prefix, size in cands:
                fnt.configure(size=size)
                need = (glyphs_w(prefix)
                        + sum(fnt.measure(lab) for lab in labels))
                pad = int((room - need) // n2)
                if best is None or pad > best[2]:
                    best = (prefix, size, pad)
                if pad >= comfort:
                    break
            prefix, size, pad = best
            pad = int(max(1, min(self._em() + 6, pad)))
            want = (int(size), pad, prefix)
            # Touching a ttk style relayouts EVERY widget that uses it, and
            # this one is asked to re-fit on every <Configure>. Idempotent
            # or it is a thrash: only write when the answer changed.
            if want != getattr(self, "_tabfit_applied", None):
                st.configure("TNotebook.Tab",
                             font=(_uf, want[0], "bold"),
                             padding=(pad, 0))
                for t in tabs:
                    img = ic.get(prefix + str(nb.tab(t, "text")).strip())
                    if img is not None:
                        nb.tab(t, image=img)
                self._tabfit_applied = want
            self._tabfit_w = nb.winfo_width()
        except (tk.TclError, ValueError, TypeError):
            pass

    def _on_rnb_configure(self, e=None):
        """Re-fit the tab strip whenever the notebook's width changes.

        THE DISAPPEARING TAB. `_fit_tab_padding` hands the tabs every pixel
        of slack there is, so the fitted strip is exactly as wide as the
        notebook was WHEN IT RAN -- and it only ran from `_sync_tab_icons`,
        i.e. on a theme or text-size pass. Every other way the width moves
        (a sash drag, a window resize, hiding a side panel, a relayout that
        lands after `_apply_brand` measured) left the fit stale and the
        strip too wide, and ttk::notebook answers an over-wide strip by
        SQUEEZING the tabs: at a 390 px panel the right-most labels are
        given 68 px for the 70 px they need and render clipped, which is
        the tab that "disappeared" after a Collapse all / Expand all pass.
        Debounced, because a drag fires <Configure> dozens of times."""
        nb = getattr(self, "rnotebook", None)
        if nb is None:
            return
        try:
            w = nb.winfo_width()
        except tk.TclError:
            return
        if w <= 1 or w == getattr(self, "_tabfit_w", None):
            return
        if getattr(self, "_booting", False):
            return                      # the build's own storm; _apply_brand
        self._tabfit_w = w              # fits once at the end of it
        job = getattr(self, "_tabfit_job", None)
        if job:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
        try:
            self._tabfit_job = self.root.after(120, self._fit_tab_padding)
        except tk.TclError:
            self._tabfit_job = None

    def _sync_tab_icons(self):
        """Small geometric glyph beside each right-panel tab label. The set
        is regenerated per theme, so the tabs are restamped from here."""
        nb = getattr(self, "rnotebook", None)
        if nb is None:
            return
        ic = getattr(self, "_icons", {})
        try:
            tabs = list(nb.tabs())
        except tk.TclError:
            return
        for t in tabs:
            try:
                base = str(nb.tab(t, "text")).strip()
                img = ic.get("tab::" + base)
                if img is not None:
                    # one space of air between glyph and label (house rule:
                    # every icon+text pairing gets a single space of air)
                    nb.tab(t, image=img, compound="left", text=" " + base)
            except tk.TclError:
                pass
        # the icon set was just regenerated, so the fit must re-stamp even
        # if its numbers come out the same as last time
        self._tabfit_applied = None
        self._fit_tab_padding()

    def _sync_panel_btns(self):
        """Icon + tooltip for the two panel-collapse buttons. The glyph is
        a pane rectangle with the folding side filled while that panel is
        open; the tooltip carries the words the buttons used to spell out
        (those labels cost the top bar room it did not have at 1920)."""
        ic = getattr(self, "_icons", {})
        for btn, tip, base, shown, on_txt, off_txt in (
                (getattr(self, "left_btn", None),
                 getattr(self, "_left_tip", None), "panel_l",
                 bool(getattr(self, "left_shown", True)),
                 "Hide the left panel: folders, progress and the log. The "
                 "plot widens.",
                 "Show the left panel: folders, progress and the log."),
                (getattr(self, "right_btn", None),
                 getattr(self, "_right_tip", None), "panel_r",
                 bool(getattr(self, "right_shown", True)),
                 "Hide the right panel of controls. The plot widens.",
                 "Show the right panel of controls.")):
            if btn is None:
                continue
            img = ic.get(base if shown else base + "_off")
            try:
                if img is not None:
                    btn.configure(image=img, compound="image", text="")
            except tk.TclError:
                pass
            if tip is not None:
                tip.text = on_txt if shown else off_txt

    def _apply_titlebar(self, win=None):
        """Paint the Windows caption bar with the theme (Win11 caption/text
        color attributes; immersive-dark fallback). Never raises."""
        try:
            import ctypes
            w = win or self.root
            # The flush is only here to guarantee the window exists before
            # GetParent, and that is settled for good once we have seen a
            # real HWND for it. Re-flushing on every theme switch paid for a
            # full SYNCHRONOUS relayout mid-switch that the trailing idle
            # cycle then did all over again -- 1.9-3.0 s, by far the biggest
            # slice of a theme change.
            if not getattr(w, "_sparta_tb_seen", False):
                w.update_idletasks()
            try:
                w.configure(background=self._theme_palette()[0])
            except tk.TclError:
                pass
            hwnd = ctypes.windll.user32.GetParent(w.winfo_id())
            if not hwnd:
                return
            w._sparta_tb_seen = True
            uibg, fg, *_ = self._theme_palette()

            def cref(hexcol):
                r, g, b = (int(hexcol[i:i + 2], 16) for i in (1, 3, 5))
                return (b << 16) | (g << 8) | r

            def dwm(attr, val):
                v = ctypes.c_int(val)
                ctypes.windll.dwmapi.DwmSetWindowAttribute(
                    hwnd, attr, ctypes.byref(v), 4)
            dwm(20, 1 if self.dark_mode.get() else 0)
            if uibg.startswith("#") and fg.startswith("#"):
                dwm(35, cref(uibg))          # caption color (Win11)
                dwm(36, cref(fg))            # caption text
        except Exception:
            pass

    def _raise_existing(self, attr):
        """The one way an app dialog answers a second open request (the
        fringe workbench's pattern, W1b): clicking again NEVER spawns a
        twin - the existing window is un-minimised, raised and focused,
        and the caller returns it. A dead window clears the attribute
        and returns None: build fresh."""
        win = getattr(self, attr, None)
        if win is None:
            return None
        try:
            if win.winfo_exists():
                win.deiconify()
                win.lift()
                win.focus_force()
                return win
        except tk.TclError:
            pass
        setattr(self, attr, None)
        return None

    def _center_on_root(self, win, w, h):
        """Size a dialog AND place it centered over the main window, fully
        on screen. winfo_screenwidth/height describe the PRIMARY display, so
        the clamp box is that screen UNION the main window's own rectangle -
        a dialog opened from a window on a second monitor must not be yanked
        back to the primary one."""
        w, h = int(w), int(h)
        try:
            self.root.update_idletasks()
            rx, ry = self.root.winfo_rootx(), self.root.winfo_rooty()
            rw, rh = self.root.winfo_width(), self.root.winfo_height()
            sw = self.root.winfo_screenwidth()
            sh = self.root.winfo_screenheight()
            x = rx + (rw - w) // 2
            y = ry + (rh - h) // 2
            lo_x, hi_x = min(0, rx), max(sw - w, rx + rw - w)
            lo_y, hi_y = min(0, ry), max(sh - h, ry + rh - h)
            x = max(lo_x, min(x, max(lo_x, hi_x)))
            y = max(lo_y, min(y, max(lo_y, hi_y)))
        except tk.TclError:
            win.geometry("%dx%d" % (w, h))
            return
        win.geometry("%dx%d+%d+%d" % (w, h, x, y))

    def _blendc(self, c1, c2, f):
        """Blend color c1 toward c2 by fraction f (hex out)."""
        from matplotlib.colors import to_rgb
        try:
            a, b2 = to_rgb(c1), to_rgb(c2)
        except ValueError:
            return c1
        return "#%02x%02x%02x" % tuple(
            int(round(255 * (x + (y - x) * f))) for x, y in zip(a, b2))

    def _tint_brand_button(self, b, br):
        """Apply the active triad to one tiered button (see _brand_button)."""
        uibg, fg, _fl, _pb, _pf = self._theme_palette()
        tier = getattr(b, "_tier", "primary")
        if tier == "nuke":
            # deliberately loud and fixed; only the panel showing through
            # its rounded corners follows the theme
            b.configure(chrome=uibg)
            return
        if tier == "primary":
            _bt = self._auto_text_color(br["ac1"])
            b.configure(bg=br["ac1"], fg=_bt, activebackground=br["hov"],
                        activeforeground=_bt, disabledforeground="#cfcfcf",
                        highlightthickness=0)
            if isinstance(b, RoundButton):
                b.configure(chrome=uibg, focuscolor=_bt,
                            disabledbackground=self._blendc(br["ac1"], uibg,
                                                            0.55),
                            disabledforeground=self._blendc(_bt, uibg, 0.45))
            b._rest_bg, b._hot_bg = br["ac1"], br["hov"]
            b._rest_fg = _bt
        elif tier == "secondary":
            # tonal chip: a light ac1-tinted fill (a Windows tk.Button
            # cannot draw a colored outline reliably, so the tint IS the
            # button shape), deepening on hover / press
            tonal = self._blendc(uibg, br["ac1"], 0.10)
            b.configure(bg=tonal, fg=br["ac1"],
                        activebackground=self._blendc(uibg, br["ac1"], 0.30),
                        activeforeground=br["ac1"],
                        disabledforeground=self._blendc(fg, uibg, 0.6),
                        highlightthickness=2, highlightbackground=uibg,
                        highlightcolor=br["ac3"])
            b._rest_bg = tonal
            b._hot_bg = self._blendc(uibg, br["ac1"], 0.20)
            b._rest_fg = br["ac1"]
        else:                            # tertiary: quiet text button
            muted = self._blendc(fg, uibg, 0.35)
            b.configure(bg=uibg, fg=muted, activebackground=uibg,
                        activeforeground=br["ac1"],
                        disabledforeground=self._blendc(fg, uibg, 0.6),
                        highlightthickness=1, highlightbackground=uibg,
                        highlightcolor=br["ac3"])
            b._rest_bg, b._hot_bg = uibg, uibg
            b._rest_fg = muted

    def _hover_brand_button(self, b, hot):
        try:
            if str(b["state"]) == "disabled":
                return
            if getattr(b, "_tier", "primary") == "tertiary":
                b.configure(fg=(self._brand()["ac1"] if hot
                                else getattr(b, "_rest_fg", None)
                                or self._theme_palette()[1]))
                return
            b.configure(bg=(getattr(b, "_hot_bg", None) if hot else
                            getattr(b, "_rest_bg", None)) or b["bg"])
        except (tk.TclError, AttributeError):
            pass

    def _brand_button(self, parent, text, command, big=False,
                      tier="primary", **bkw):
        """A branded action button we fully own (sv_ttk's accent visuals are
        image-drawn and cannot be recolored). Tiers per the button plan:
        primary = filled ac1 + bold (the ONE main action of a region);
        secondary = outlined, ac1 text on chrome; tertiary = quiet text.
        Every tier has hover, pressed, keyboard-focus ring (ac3) and a
        distinct disabled look; hierarchy is carried by shape + weight,
        never color alone."""
        if tier == "primary":
            # drawn, not stock: ttk height + ttk side padding + real
            # rounded corners, carrying the theme triad sv_ttk cannot
            b = RoundButton(parent, app=self, text=text, command=command,
                            cursor="hand2", font=self._F(1, "bold"),
                            radius=4, **bkw)
        else:
            b = tk.Button(parent, text=text, command=command, relief="flat",
                          bd=0, cursor="hand2",
                          font=self._F(1, "normal"),
                          padx=10, pady=4, **bkw)
        b._tier = tier
        self._tint_brand_button(b, self._brand())
        if not hasattr(self, "_brand_btns"):
            self._brand_btns = []
        self._brand_btns.append(b)
        if not isinstance(b, RoundButton):
            # RoundButton owns its hover on a bindtag (a Tooltip's plain
            # <Enter> bind would replace a widget-level one)
            b.bind("<Enter>", lambda e: self._hover_brand_button(b, True))
            b.bind("<Leave>", lambda e: self._hover_brand_button(b, False))
        return b

    def _ttk_btn_metrics(self):
        """(height, total horizontal padding) of a stock ttk.Button at the
        current text size, MEASURED from real ones - sv_ttk assembles its
        button from images, so the numbers cannot be derived. Two probes of
        different text length cancel the padding out without needing to
        know which font the style ended up with. Cached per body size; a
        fresh ttk.Button reports its requested size at once, so this costs
        no idle flush."""
        bs = getattr(self, "_body_size", 9)
        hit = getattr(self, "_ttkbtn_cache", None)
        if hit is not None and hit[0] == bs:
            return hit[1]
        h = pw = 0
        try:
            p1 = ttk.Button(self.root, text="M")
            p2 = ttk.Button(self.root, text="MM")
            w1, w2 = int(p1.winfo_reqwidth()), int(p2.winfo_reqwidth())
            h = int(p1.winfo_reqheight())
            p1.destroy()
            p2.destroy()
            pw = 2 * w1 - w2            # w1 - (w2 - w1): the padding alone
        except tk.TclError:
            pass
        if h < 8:
            h = self._F(0).metrics("linespace") + 12
        if pw < 8:
            pw = 4 * self._em()
        out = (h, pw)
        self._ttkbtn_cache = (bs, out)
        return out

    def _icon_over(self, photo, bg):
        """One of the brand icons, flattened onto a solid background so a
        canvas button never has to composite alpha itself. Cached per
        (icon, background); the whole cache dies with each _make_icons."""
        src = getattr(self, "_icon_pil", {}).get(photo)
        if src is None:
            return photo
        cache = getattr(self, "_icon_flat", None)
        if cache is None:
            cache = self._icon_flat = {}
        key = (photo, bg)
        if key in cache:
            return cache[key]
        try:
            from PIL import Image, ImageTk
            r, g, b = (int(v) // 256 for v in self.root.winfo_rgb(bg))
            base = Image.new("RGBA", src.size, (r, g, b, 255))
            base.alpha_composite(src)
            out = ImageTk.PhotoImage(base.convert("RGB"))
        except Exception:
            return photo
        cache[key] = out
        return out

    def _hairline(self):
        """(ground, border) for the flat cards: border = a 32% blend of
        the text color into the panel ground (full fg in High Contrast)."""
        uibg, fg, _fl, _pb, _pf = self._theme_palette()
        if self.theme_mode.get() == "highcontrast":
            return uibg, fg
        try:
            r1, g1, b1 = self.root.winfo_rgb(uibg)
            r2, g2, b2 = self.root.winfo_rgb(fg)
            t = 0.32
            border = "#%02x%02x%02x" % (
                int((r1 * (1 - t) + r2 * t) / 256),
                int((g1 * (1 - t) + g2 * t) / 256),
                int((b1 * (1 - t) + b2 * t) / 256))
        except tk.TclError:
            border = "#b9b0a0"
        return uibg, border

    def _card(self, parent, grow="x", width=None):
        """A BrandCard registered for theme retints, tinted immediately
        (dialog cards would otherwise show default colors)."""
        kw = {"width": width} if width else {}
        c = BrandCard(parent, grow=grow, **kw)
        if not hasattr(self, "_brand_cards"):
            self._brand_cards = []
        self._brand_cards = [x for x in self._brand_cards
                             if x.winfo_exists()]
        self._brand_cards.append(c)
        try:
            c.retint(*self._hairline())
        except tk.TclError:
            pass
        return c

    def _recolor_tk(self):
        """Recolor plain tk widgets (Text, Canvas) that ignore the ttk theme."""
        uibg, fg, fld, _pb, _pf = self._theme_palette()
        t = self.theme_mode.get()
        bg = ("#000000" if t == "black" else
              "#1c1d22" if t == "dark" else
              "white" if t == "light" else fld)
        scrolls = set(getattr(self, "_tab_canvases", []))
        flats = {getattr(self, "log", None), getattr(self, "ref", None)}
        # Dyslexic themes: wider line spacing on every prose Text box
        # (the one spacing knob Tk gives us cheaply - guidance asks for
        # roomier lines; letter tracking is not a Tk facility). 0 puts
        # every other theme back to stock in the same walk.
        _dsp = max(2, self._em() // 3) if self._dys_on() else 0
        for w in getattr(self, "_tk_widgets", []):
            if w in scrolls:
                continue                # settings pages match the chrome below
            try:
                if isinstance(w, tk.Text):
                    w.configure(spacing1=_dsp, spacing2=_dsp,
                                spacing3=_dsp)
            except tk.TclError:
                pass
            if w in flats:              # flat boxes: ground color, not field
                try:
                    w.configure(background=uibg, foreground=fg,
                                insertbackground=fg)
                except tk.TclError:
                    pass
                continue
            try:
                w.configure(background=bg, foreground=fg, insertbackground=fg)
            except tk.TclError:
                try:
                    w.configure(background=bg)      # Canvas has no foreground
                except tk.TclError:
                    pass
        for c in scrolls:
            try:
                c.configure(background=uibg)
            except tk.TclError:
                pass
        # the loop above wipes the status chip's colors; re-tint it
        st = getattr(self, "_last_run_state", None)
        if st:
            self._set_run_state(*st)
        _hl = self._hairline()
        for c in getattr(self, "_brand_cards", []):
            try:
                c.retint(*_hl)
            except tk.TclError:
                pass
        _pw = getattr(self, "pw", None)
        if _pw is not None:
            try:
                _pw.configure(bg=uibg)
            except tk.TclError:
                pass
        self._place_sash_handles()   # pills follow the theme
        self._sync_tabs()   # tab strip follows the theme

    # ---- theme: modern look + light/dark ---------------------------------
    def _init_theme(self):
        try:
            # sv_ttk re-runs Tcl's tk_setPalette from its <<ThemeChanged>>
            # binding; that command walks EVERY widget stamping widget-
            # level colors that override our styles at the next idle
            # (fields went invisible whenever its base palette disagreed
            # with the active theme). The app recolors plain tk widgets
            # itself, so make it a no-op before sv_ttk can ever call it.
            self.root.tk.eval("proc ::tk_setPalette {args} {}")
        except tk.TclError:
            pass
        t = self.theme_mode.get()
        th = self._themes().get(t, {})
        base = th.get("base", "light" if t == "light" else "dark")
        self.dark_mode.set(base != "light")
        if _HAVE_SVTTK:
            try:
                sv_ttk.set_theme("dark" if base != "light" else "light")
            except Exception:
                self._clam_palette()
        else:
            self._clam_palette()
        # the six-tab strip only fits once sv_ttk's fixed 32 px of tab air
        # is ours to size; per theme, and before any tab padding is set
        self._install_tab_element()
        # Always re-assert the chrome backgrounds for the active palette. This
        # is what makes switching BACK to light/dark/black fully revert: ttk
        # style.configure overrides are global and sticky, so an accent theme's
        # tint would otherwise linger.
        uibg, fg, _fld, _pb, _pf = self._theme_palette()
        self._pin_field_styles()
        try:
            self.root.configure(bg=uibg)
        except tk.TclError:
            pass
        # a second assert once the switch has settled: if anything above
        # was clobbered by late sv_ttk work, this heals it (idempotent)
        try:
            self.root.after(250, self._pin_field_styles)
        except tk.TclError:
            pass
        self._apply_style_fonts()
        # accent (or reset to plain) the carets, group titles and wordmark
        # Re-sync classic tk.Label content labels (they honor bg, unlike
        # sv_ttk ttk.Label). Preserve any caller-set custom fg/bg.
        # ...and DROP the dead ones while we are walking the list. Every
        # pass that rebuilds labels rather than retinting them -- chiefly
        # _refresh_quantity_rows, which must rebuild because the formulas
        # are images in the text colour -- destroys its old labels and
        # registers new ones, so this list grew by 10 on every theme
        # switch AND every text-size change (measured 372 -> 472 over ten
        # operations) and every switch after that re-walked the corpses.
        _live = []
        for _rec in getattr(self, "_content_labels", []):
            _lab, _cfg, _cbg = _rec
            try:
                if not _lab.winfo_exists():
                    continue
                _lab.configure(bg=(_cbg if _cbg is not None else uibg),
                               fg=self._role_fg(_cfg, fg))
                _live.append(_rec)
            except tk.TclError:
                continue          # gone between the check and the write
        self._content_labels = _live
        self._recolor_accents(th.get("accent"), th.get("rainbow", False))
        matplotlib.rcParams["pdf.fonttype"] = 42
        matplotlib.rcParams["ps.fonttype"] = 42

    def _pin_field_styles(self):
        """Assert every themed style the app relies on for READABILITY:
        chrome backgrounds, notebook flatness, and the entry/combobox/
        spinbox field colors for every widget state. Idempotent, each
        step guarded separately -- one failure must never silently skip
        the rest and leave gray-on-dark text (the half-themed bug) --
        and failures are logged instead of swallowed."""
        uibg, fg, _fld, _pb, _pf = self._theme_palette()

        def _log_fail(step, e):
            try:
                if hasattr(self, "log"):
                    self._logline("! theme style step '%s' failed: %r"
                                  % (step, e))
            except Exception:
                pass
        try:
            st = ttk.Style()
        except Exception as e:
            _log_fail("style", e)
            return
        try:
            for w in ("TFrame", "TLabel", "TLabelframe", "TLabelframe.Label",
                      "TCheckbutton", "TRadiobutton", "Card.TFrame"):
                st.configure(w, background=uibg, foreground=fg)
        except Exception as e:
            _log_fail("chrome", e)
        try:
            # The one permanently disabled row in the program that must
            # still read: 'Absorbance data (always)' in EXPORT > DATA
            # FILES states a fact rather than offering a choice. It takes
            # the MUTED role (rule 65) instead of ttk's stock disabled
            # grey, which disappears on the dark accent themes, and it is
            # re-pinned here so it follows every theme switch. High
            # Contrast collapses muted to the full fg by itself.
            st.configure("Muted.TCheckbutton", background=uibg,
                         foreground=fg)
            st.map("Muted.TCheckbutton",
                   foreground=[("disabled", self._muted_fg())])
        except Exception as e:
            _log_fail("muted check", e)
        try:
            # the settings notebook: drop sv_ttk's boxed border so the
            # tabbed panel reads as flat like the hairline cards around it
            st.configure("TNotebook", background=uibg, borderwidth=0,
                         bordercolor=uibg, lightcolor=uibg, darkcolor=uibg)
            st.configure("TNotebook.Client", borderwidth=0)
        except Exception as e:
            _log_fail("notebook", e)
        # disabled text: readable muted (sv_ttk's stock gray disappears
        # on dark accent themes), still distinct from the normal fg
        try:
            dfg = self._blendc(fg, uibg, 0.35)
        except Exception:
            dfg = fg
        try:
            # entry / combobox / spinbox: sv_ttk leaves the field
            # FOREGROUND unset, so dark themes drew unreadable text on
            # the field. Pin field bg AND fg for every widget state.
            for w in ("TEntry", "TCombobox", "TSpinbox"):
                st.configure(w, fieldbackground=_fld, foreground=fg,
                             background=_fld, insertcolor=fg,
                             selectforeground=uibg, selectbackground=fg)
                st.map(w,
                       fieldbackground=[("readonly", _fld),
                                        ("disabled", _fld), ("focus", _fld)],
                       foreground=[("disabled", dfg), ("readonly", fg),
                                   ("focus", fg)],
                       selectforeground=[("readonly", fg)],
                       selectbackground=[("readonly", _fld)])
        except Exception as e:
            _log_fail("fields", e)
        try:
            # sv_ttk's tk_setPalette stuffs the option db, so every field
            # is BORN with a widget-level foreground frozen at the boot
            # theme -- and a widget-level option beats the style forever
            # (invisible text once the page brightness flips). Clear it
            # everywhere; live ghost hints get the theme-aware muted tone.
            gset = getattr(self, "_ghost_fields", set())
            gfg = self._ghost_fg()
            stack = [self.root]
            while stack:
                w = stack.pop()
                stack.extend(w.winfo_children())
                if w.winfo_class() in ("TEntry", "TCombobox", "TSpinbox"):
                    try:
                        w.configure(foreground=(gfg if w in gset else ""))
                    except tk.TclError:
                        pass
                    if w.winfo_class() == "TCombobox":
                        # the self-heal walk already has every combobox in
                        # hand: put any scrolled value back on char 0 here
                        # rather than pay for a second walk of the tree
                        try:
                            w.xview_moveto(0.0)
                        except tk.TclError:
                            pass
        except Exception as e:
            _log_fail("unfreeze", e)
        try:
            # and future widgets: out-specific tk_setPalette's *foreground
            # so new fields are born deferring to the style
            for cls in ("TEntry", "TCombobox", "TSpinbox"):
                self.root.option_add("*%s.foreground" % cls, "")
        except Exception as e:
            _log_fail("optdefault", e)
        try:
            # combobox dropdown list (a tk Listbox via the option db)
            self.root.option_add("*TCombobox*Listbox.background", _fld)
            self.root.option_add("*TCombobox*Listbox.foreground", fg)
            self.root.option_add("*TCombobox*Listbox.selectBackground", fg)
            self.root.option_add("*TCombobox*Listbox.selectForeground", _fld)
        except Exception as e:
            _log_fail("optiondb", e)
        try:
            self._sync_combo_popdowns(_fld, fg)
        except Exception as e:
            _log_fail("popdowns", e)

    @staticmethod
    def _contrast(c1, c2):
        """WCAG contrast ratio between two #rrggbb colors (1.0 - 21.0)."""
        def lin(c):
            out = []
            for i in (1, 3, 5):
                u = int(c[i:i + 2], 16) / 255.0
                out.append(u / 12.92 if u <= 0.03928
                           else ((u + 0.055) / 1.055) ** 2.4)
            return 0.2126 * out[0] + 0.7152 * out[1] + 0.0722 * out[2]
        try:
            a, b = lin(c1), lin(c2)
        except (ValueError, IndexError, TypeError):
            return 21.0
        hi, lo = max(a, b), min(a, b)
        return (hi + 0.05) / (lo + 0.05)

    _ROLE_FG = {"muted": "_muted_fg", "value": "_value_fg",
                "state": "_state_fg", "head": "_head_fg"}

    def _role_fg(self, cfg, fallback):
        """Resolve a semantic role token to this theme's ink.

        Anything that is not a role token passes through untouched, so a
        caller-set literal still wins and `None` still means 'the theme's
        text color'."""
        role = getattr(cfg, "role", None)
        if role == "semantic":
            return self._semantic_fg(cfg.base)
        m = self._ROLE_FG.get(role)
        if m:
            try:
                return getattr(self, m)()
            except Exception:
                return fallback
        return cfg if cfg is not None else fallback

    def _value_fg(self):
        """VALUE: numbers, units and expressions the user reads off a
        panel. The signal accent pulled toward the text color, which is the
        higher-contrast direction in every theme -- the same ink the Guide
        cards' mono tag already uses, now named for what it means."""
        return self._code_fg()

    def _state_fg(self):
        """STATE: the one live word or line a region reports about itself
        (Ready / Running, the last export's result, 'on plot'). The primary
        accent pulled 30% toward the text color, so it reads as the region
        speaking rather than as another button."""
        try:
            _u, fg, _fld, _pb, _pf = self._theme_palette()
            return self._blendc(self._brand()["ac1"], fg, 0.3)
        except Exception:
            return self._brand()["ac1"]

    def _lift_fg(self, base, bg=None, floor=4.5):
        """Walk a colour toward the theme's TEXT colour until it is legible
        on the ground it will be drawn on.

        The one move behind three roles. Accents and meaning hues are both
        picked for their HUE, not their luminance, so either can wash out
        on a theme whose chrome happens to sit near them (the blown-out
        logo was ac2 at 3.17:1 on the light ground). Toward the text colour
        is the higher-contrast direction in every theme, and the walk stops
        at the first step that clears `floor`, so a colour that already
        reads keeps its exact value and nothing is switched on
        `dark_mode`."""
        try:
            uibg, fg, _fld, _pb, _pf = self._theme_palette()
            ground = bg or uibg
            for i in range(9):
                c = self._blendc(base, fg, i * 0.08)
                if self._contrast(c, ground) >= floor:
                    return c
            return self._blendc(base, fg, 0.64)
        except Exception:
            return base

    def _semantic_fg(self, base):
        """The fixed meaning hues (SEM_OK / SEM_WARN / SEM_BAD / SEM_FIX),
        made legible on the active ground. The HUE is fixed on purpose --
        red means failed in every theme -- but its luminance is not."""
        return self._lift_fg(base)

    def _head_fg(self):
        """HEAD: the sub-heading inside a section, and the Quick Access /
        drawer titles. The highlight accent ac3, which rule 45 already
        assigns to exactly these, lifted until it reads."""
        return self._lift_fg(self._brand()["ac3"])

    def _signal_fg(self, bg=None):
        """ac2, guaranteed to read on the ground it is drawn on: the
        wordmark dot and the anvil mark's sample."""
        return self._lift_fg(self._brand()["ac2"], bg)

    def _ghost_fg(self):
        """Muted hint color readable on the themed FIELD background."""
        try:
            _u, fg, fld, _pb, _pf = self._theme_palette()
            return self._blendc(fg, fld, 0.5)
        except Exception:
            return "#888888"

    def _muted_fg(self):
        """Muted tone for hint / status labels standing on the PANEL ground:
        the text color pulled 45% into the chrome. Ghost text living INSIDE a
        field takes _ghost_fg instead, which blends into the field color.
        High Contrast gets no dimmed text at all (rule 48): muted collapses
        to the full fg there, exactly as it does in the session tab strip."""
        try:
            uibg, fg, _fld, _pb, _pf = self._theme_palette()
            if self.theme_mode.get() == "highcontrast":
                return fg
            return self._blendc(fg, uibg, 0.35)
        except Exception:
            return self._ghost_fg()

    def _code_fg(self):
        """Ink for the mono `m` tag in the Guide cards: the theme's signal
        accent (ac2) pulled 35% toward the text color. Toward the text color
        is always the higher-contrast direction, so one formula stays
        readable on the card ground in light, dark and High Contrast alike."""
        ac2 = self._brand()["ac2"]
        try:
            _u, fg, _fld, _pb, _pf = self._theme_palette()
            return self._blendc(ac2, fg, 0.35)
        except Exception:
            return ac2

    def _ghost_mark(self, w, on):
        """Track entries currently showing ghost/hint text so theme
        switches can re-tint them instead of wiping them readable."""
        gs = getattr(self, "_ghost_fields", None)
        if gs is None:
            gs = self._ghost_fields = set()
        (gs.add if on else gs.discard)(w)

    def _auto_body_size(self):
        """Default interface text size from the screen: 12 on a roomy
        desktop, down to 9 where Windows display scaling (e.g. 150% on a
        laptop) shrinks the logical width. 1280 logical px -> 9,
        1920 -> 12."""
        try:
            scale = max(0.5, self.root.winfo_fpixels("1i") / 96.0)
            eff = self.root.winfo_screenwidth() / scale
        except (tk.TclError, ValueError):
            return 9
        return int(max(9, min(12, round(9 + 3.0 * (eff - 1280.0) / 640.0))))

    def _F(self, delta=0, weight="normal", mono=False, semi=False):
        """Shared font at body size + delta. Widgets built with these are
        reconfigured in place by _apply_style_fonts, so everything follows
        the App-text-size control (the old literal sizes did not)."""
        if weight == "underline":
            weight, ul = "normal", True
        else:
            ul = False
        key = (delta, weight, mono, semi, ul)
        f = self._scaled_fonts.get(key)
        if f is None:
            f = tkfont.Font()
            self._scaled_fonts[key] = f
            self._conf_scaled(key, f)
        return f

    # The retired Dyslexic theme keys. v1.4.9 R9a moved their face into
    # the App-font picker, so no theme switches the typeface any more.
    DYS_THEMES = tuple(ui_prefs.RETIRED_THEMES)

    def _dys_on(self):
        """True while the App font is the dyslexia-friendly face."""
        return self._app_font() == "OpenDyslexic"

    def _app_font(self):
        """The App-font value in force. Reads the settings file while
        the var is still being born, so the first _ui_faces call in
        __init__ already gets the saved face."""
        try:
            v = self.app_font.get()
        except (AttributeError, tk.TclError):
            v = self.settings.get("app_font", ui_prefs.DEFAULT_APP_FONT)
        return v or ui_prefs.DEFAULT_APP_FONT

    def _ui_faces(self):
        """(body, semibold) UI families for the ACTIVE App font.

        Everything font-shaped asks _ui_faces, so a switch reverts in
        the same pass that switched in. The brand Jost pair is the
        default (rule 44). A face that carries its weights in one
        family stands in for both slots. Deliberately untouched:
        Consolas verbatim text, the drawn wordmark and NUKE (brand
        marks, rules 43/19), and the figure (a publication surface,
        not UI chrome)."""
        return _resolve_app_font(self._app_font())

    def _conf_scaled(self, key, f):
        delta, weight, mono, semi, ul = key
        bs = getattr(self, "_body_size", 9)
        _ui, _us = self._ui_faces()
        fam = "Consolas" if mono else (_us if semi else _ui)
        f.configure(family=fam, size=max(7, bs + delta), weight=weight,
                    underline=ul)

    def _em(self):
        """Width of one '0' in the body font: the px unit panel widths
        scale by (tracks both text size and the Windows DPI scale)."""
        try:
            return max(5, self._F(0).measure("0"))
        except tk.TclError:
            return 7

    def _pane_widths(self):
        # 330/410 px were tuned at body size 9 on a 96-dpi screen (em = 7)
        em = self._em()
        return (em * 28, em * 42, em * 36, em * 53)  # lmin, lw, rmin, rw

    NUKE_AIR = 24          # the guaranteed gap to the right cluster (px)

    def _size_nuke(self):
        """Keep NUKE a notch shorter than the top bar (visible gap to the
        brand strip) and never let it cover the Undo/Redo cluster on
        narrow windows: it stays centered while there is room, then slides
        left of Undo, always leaving NUKE_AIR of clear air.

        R4: this runs from a <Configure> handler and PLACES a widget, which
        posts another <Configure>. The loop settles today only because x
        stops moving. Re-writing a placement the button already has is what
        keeps the loop alive for a frame longer than it needs, so a pass
        that computes no change stops before place_configure. The last
        placement is remembered here rather than read back from
        place_info(), which returns strings and would need parsing."""
        b = getattr(self, "nuke_btn", None)
        if b is None:
            return
        try:
            h = max(24, b.winfo_reqheight() - 8)
            top = b.master
            tw = top.winfo_width()
            ub = getattr(self, "undo_btn", None)
            if tw > 1 and ub is not None and ub.master.winfo_ismapped():
                nw = b.winfo_reqwidth()
                lim = ub.master.winfo_x() - nw // 2 - self.NUKE_AIR
                tf = getattr(self, "_titles_f", None)
                lo = (tf.winfo_x() + tf.winfo_width() if tf is not None
                      else 0) + nw // 2 + 12
                x = min(tw // 2, max(lo, lim))
                # bordermode='outside' puts place's x in the SAME frame as
                # winfo_x, which is what lim and lo are measured in. The
                # default ('inside') starts at the top bar's inner edge, so
                # NUKE sat one PAD_X right of where it was aimed and gave
                # that much of NUKE_AIR back to the Undo cluster.
                want = ("centered", int(x), int(h))
                if want == getattr(self, "_nuke_place", None):
                    return
                self._nuke_place = want
                b.place_configure(relx=0, x=x, rely=0.5, anchor="center",
                                  height=h, bordermode="outside")
            else:
                want = ("height-only", int(h))
                if want == getattr(self, "_nuke_place", None):
                    return
                self._nuke_place = want
                b.place_configure(height=h, bordermode="outside")
        except tk.TclError:
            self._nuke_place = None      # placement unknown after a failure

    def _apply_style_fonts(self, force=False):
        """sv_ttk pins fonts two ways at set_theme: named SunValley* fonts
        (used by entries/combos/spinboxes AND our content labels) and per-
        style fonts. Re-point BOTH at the brand face so nothing keeps Segoe.

        The font half is SKIPPED when nothing about the type has changed.
        MEASURED: one write to a named font or a ttk style font invalidates
        the whole widget tree and costs ~0.7-1.0 s to re-lay out, and this
        method makes ~40 of them, so it cost ~3 s per call. It is called
        from _init_theme, i.e. on every theme switch -- where the sizes and
        families are identical to what is already set. Probing this
        sv_ttk build shows set_theme() resets NONE of the 8 named fonts
        and NONE of the 9 style fonts we care about (0 of 17 changed), so
        rewriting them on a theme switch was pure cost. The signature is
        (body size, ui family, semibold family); `force` and the self-heal
        probe below cover anything that resets the fonts behind our back
        -- a different sv_ttk build, or the clam fallback.

        The families come from _ui_faces, so the signature ALSO goes
        stale when a Dyslexic theme swaps the face - that switch is the
        one theme change that must pay the full font pass, both ways."""
        bs = getattr(self, "_body_size", 11)
        ui, semi = self._ui_faces()
        st_probe = ttk.Style()
        _sig = (bs, ui, semi)
        _stale = bool(force) or getattr(self, "_style_font_sig", None) != _sig
        if not _stale:
            # rule-7 discipline: verify the invariant instead of trusting
            # it, so one unexpected reset cannot leave the app in Segoe
            try:
                _now = str(st_probe.lookup("TButton", "font"))
                if _now != getattr(self, "_style_font_probe", None):
                    _stale = True
            except tk.TclError:
                _stale = True
        if not _stale:
            self._apply_style_colors(st_probe)
            return
        # the named-font family sv_ttk registers (the real culprit): remap
        # every SunValley* face to the active UI face, scaled around the
        # body size
        sv = {
            "SunValleyBodyFont": (ui, bs, "normal"),
            "SunValleyBodyLargeFont": (ui, bs + 3, "normal"),
            "SunValleyBodyStrongFont": (semi, bs, "bold"),
            "SunValleyCaptionFont": (ui, max(8, bs - 1), "normal"),
            "SunValleySubtitleFont": (semi, bs + 4, "bold"),
            "SunValleyTitleFont": (semi, bs + 10, "bold"),
            "SunValleyTitleLargeFont": (semi, bs + 19, "bold"),
            "SunValleyDisplayFont": (semi, bs + 40, "bold"),
        }
        for name, (fam, sz, wt) in sv.items():
            try:
                tkfont.nametofont(name).configure(family=fam, size=sz,
                                                  weight=wt)
            except tk.TclError:
                pass
        # the core named fonts follow the active face too (set at init,
        # re-pointed here so a Dyslexic switch reaches tooltips, menus
        # and every widget built on the Tk defaults)
        for _nf, _nsz in (("TkDefaultFont", bs), ("TkTextFont", bs),
                          ("TkMenuFont", bs), ("TkHeadingFont", bs),
                          ("TkTooltipFont", bs - 1),
                          ("TkCaptionFont", bs - 1)):
            try:
                tkfont.nametofont(_nf).configure(family=ui, size=_nsz)
            except tk.TclError:
                pass
        st = ttk.Style()
        body = (ui, bs)
        for s in ("TButton", "Accent.TButton", "TCheckbutton", "TRadiobutton",
                  "TLabel", "TEntry", "TCombobox", "TSpinbox", "TMenubutton",
                  "Switch.TCheckbutton", "Toolbutton", "Treeview"):
            try:
                st.configure(s, font=body)
            except tk.TclError:
                pass
        # uniform, roomier internal padding on every button (sv_ttk's stock
        # 8/2/8/3 reads cramped, especially vertically)
        for s in ("TButton", "Accent.TButton", "NameFmt.TButton"):
            try:
                st.configure(s, padding=(10, 5))
            except tk.TclError:
                pass
        try:
            # settings tabs: bold, a size up (the selected tab's mustard
            # ac3 foreground is theme-dependent and lives in
            # _apply_style_colors, which runs on every call)
            st.configure("TNotebook.Tab", font=(ui, bs + 1, "bold"))
        except tk.TclError:
            pass
        try:
            st.configure("Compact.TButton",
                         font=(ui, max(8, bs - 1)), padding=(6, 2))
            st.configure("Treeview.Heading", font=(semi, bs, "bold"))
            st.configure("TLabelframe.Label", font=(semi, bs, "bold"))
            st.configure("NameFmt.TButton", font=(ui, bs))
        except tk.TclError:
            pass
        # everything built through _F follows the body size live
        for _k, _f in getattr(self, "_scaled_fonts", {}).items():
            self._conf_scaled(_k, _f)
        try:
            _lh = self._F(0).metrics("linespace")
            st.configure("Treeview", rowheight=max(20, _lh + 8))
        except tk.TclError:
            pass
        try:  # combobox dropdown lists (new popdowns pick this up)
            self.root.option_add("*TCombobox*Listbox.font", self._F(0))
        except tk.TclError:
            pass
        self._style_font_sig = _sig
        try:
            self._style_font_probe = str(st.lookup("TButton", "font"))
        except tk.TclError:
            self._style_font_probe = None
        self._apply_style_colors(st)
        try:
            self.root.after_idle(self._size_nuke)
        except tk.TclError:
            pass

    def _apply_style_colors(self, st=None):
        """The THEME-dependent half of _apply_style_fonts: the selected
        notebook tab takes ac3. Split out because it must run on every
        theme switch even when the font half is skipped as unchanged."""
        st = st or ttk.Style()
        try:
            st.map("TNotebook.Tab",
                   foreground=[("selected", self._brand()["ac3"])])
        except tk.TclError:
            pass

    def _clam_palette(self):
        """Fallback hand-tuned theme if sv_ttk is unavailable."""
        style = ttk.Style()
        try:
            style.theme_use("clam")
        except tk.TclError:
            return
        bg, fg, fld, _pb, _pf = self._theme_palette()
        self.root.configure(bg=bg)
        style.configure(".", background=bg, foreground=fg, fieldbackground=fld,
                        bordercolor=("#555c66" if self.dark_mode.get()
                                     else "#c2c9d2"))
        for w in ("TFrame", "TLabel", "TCheckbutton", "TRadiobutton",
                  "TLabelframe"):
            style.configure(w, background=bg, foreground=fg)
        style.configure("TLabelframe", borderwidth=1, relief="solid")
        style.configure("TButton", padding=6, relief="flat")
        style.configure("TEntry", fieldbackground=fld, foreground=fg)
        style.configure("TCombobox", fieldbackground=fld, foreground=fg)

    def _center_titles(self):
        """Center every group-box title (labelanchor='n')."""
        def walk(w):
            for c in w.winfo_children():
                if isinstance(c, ttk.Labelframe):
                    try:
                        c.configure(labelanchor="n")
                    except Exception:
                        pass
                walk(c)
        walk(self.root)

    def _draw_rainbow_banner(self):
        """Debounced entry point for the top-bar scene (rapid <Configure>
        events during a window resize would otherwise re-render the PIL
        image dozens of times)."""
        root = getattr(self, "root", None)
        if root is None:
            return
        job = getattr(self, "_banner_job", None)
        if job:
            try:
                root.after_cancel(job)
            except Exception:
                pass
        try:
            self._banner_job = root.after(45, self._paint_banner_now)
        except Exception:
            pass

    def _paint_banner_now(self):
        cv = getattr(self, "rainbow_banner", None)
        if cv is None:
            return
        try:
            w = cv.winfo_width() or self.root.winfo_width() or 1200
            t = self.theme_mode.get()
            scenes = {"coastguard": (self._bimg_coastguard, 20),
                      "tet": (self._bimg_tet, 26),
                      "christmas": (self._bimg_christmas, 26),
                      "synthwave": (self._bimg_synthwave, 20),
                      "solarized": (self._bimg_newmexico, 22)}
            if t in scenes:
                painter, h = scenes[t]
                self._render_banner_image(cv, w, h, painter)
                return
            cv.delete("all")
            if self._themes().get(t, {}).get("rainbow"):
                self._banner_rainbow(cv, w)     # Rainbow + Dyslexic Dark
                return
            ac = self._brand()["ac1"]
            cv.configure(height=6, bg=ac)
            cv.create_rectangle(0, 0, w, 6, fill=ac, outline=ac)
        except Exception:
            pass

    def _render_banner_image(self, cv, w, h, painter):
        """Render a supersampled PIL banner (crisp, anti-aliased) and show it
        on the canvas. painter(draw, W, H) works in the supersampled space."""
        from PIL import Image, ImageDraw, ImageTk
        ss = 3
        W, Hs = max(2, w) * ss, h * ss
        img = Image.new("RGB", (W, Hs), (255, 255, 255))
        painter(ImageDraw.Draw(img, "RGBA"), W, Hs)
        img = img.resize((max(2, w), h), Image.LANCZOS)
        self._banner_photo = ImageTk.PhotoImage(img)     # hold the ref
        cv.configure(height=h)
        cv.delete("all")
        cv.create_image(0, 0, anchor="nw", image=self._banner_photo)

    def _banner_rainbow(self, cv, w):
        import colorsys
        cv.configure(height=8, bg="#000000")
        for x in range(0, max(w, 2), 2):
            frac = x / max(w - 1, 1)
            r, g, b = colorsys.hsv_to_rgb(frac * 0.83, 0.95, 1.0)
            cv.create_line(x, 0, x, 8, width=2,
                           fill="#%02x%02x%02x" % (int(r * 255),
                                                   int(g * 255),
                                                   int(b * 255)))

    def _banner_font(self, px, bold=True):
        """A PIL truetype font with full Vietnamese coverage for banner text
        (the bundled Jost lacks U+1EEB / U+1EDB, so the Tet greeting would
        tofu). Tries Segoe UI Semibold / Arial, degrades gracefully."""
        import os
        from PIL import ImageFont
        fdir = os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts")
        names = (["seguisb.ttf", "arialbd.ttf", "segoeui.ttf", "arial.ttf"]
                 if bold else ["segoeui.ttf", "arial.ttf"])
        for fn in names:
            try:
                return ImageFont.truetype(os.path.join(fdir, fn), px)
            except Exception:
                continue
        try:
            return ImageFont.load_default()
        except Exception:
            return None

    def _banner_text(self, d, xy, text, font, fill, anchor="mm",
                     stroke=0, stroke_fill=None):
        """Draw banner text, never letting a font/anchor hiccup blank the
        whole scene."""
        if font is None:
            return
        try:
            d.text(xy, text, font=font, fill=fill, anchor=anchor,
                   stroke_width=stroke, stroke_fill=stroke_fill)
        except Exception:
            pass

    def _bimg_coastguard(self, d, W, H):
        # a white hull band with navy trim and the Coast Guard racing stripe
        # (thin blue / thin white / wide red, canted) toward the right,
        # like a cutter's bow.
        navy, red = (0, 32, 91), (228, 0, 43)
        d.rectangle([0, 0, W, H], fill=(255, 255, 255))
        lw = max(2, int(H * 0.05))
        d.line([(0, int(H * 0.06)), (W, int(H * 0.06))], fill=navy, width=lw)
        d.line([(0, int(H * 0.94)), (W, int(H * 0.94))], fill=navy, width=lw)
        # racing stripe (right)
        dx = int(H * 0.49)
        x0 = int(W * 0.72)
        wb, gapw, wr = int(H * 0.28), int(H * 0.22), int(H * 1.6)
        d.polygon([(x0, H), (x0 + dx, 0), (x0 + dx + wb, 0), (x0 + wb, H)],
                  fill=navy)
        rx = x0 + wb + gapw
        d.polygon([(rx, H), (rx + dx, 0), (rx + dx + wr, 0), (rx + wr, H)],
                  fill=red)

    def _bimg_tet(self, d, W, H):
        # lucky-red Tet banner: a blossom branch with peach (pink) + apricot
        # (yellow) flowers -- Vietnam's two Tet blooms -- clustered on the
        # sides, framing a gold "Chuc Mung Nam Moi!" greeting (Vietnamese;
        # code points keep this source ASCII).
        import math
        for yy in range(H):
            f = yy / float(H - 1)
            d.line([(0, yy), (W, yy)], fill=(int(160 - 36 * f),
                   int(22 - 9 * f), int(22 - 9 * f)))
        brown, green = (86, 52, 30), (70, 150, 78)
        cy = int(H * 0.5)

        def bough_y(x):
            return cy + int(H * 0.06 * math.sin(x / (H * 0.9)))
        step = max(3, int(H * 0.1))
        d.line([(x, bough_y(x)) for x in range(0, W + step, step)],
               fill=brown, width=max(2, int(H * 0.05)), joint="curve")

        def blossom(bx, petal, center, edge):
            by = bough_y(bx)
            R, pr = int(H * 0.17), int(H * 0.12)
            for k in range(5):
                a = -math.pi / 2 + k * 2 * math.pi / 5
                px, py = bx + R * math.cos(a), by + R * math.sin(a)
                d.ellipse([px - pr, py - pr, px + pr, py + pr],
                          fill=petal, outline=edge)
            cr = int(H * 0.06)
            d.ellipse([bx - cr, by - cr, bx + cr, by + cr], fill=center)

        pink = ((255, 150, 190), (255, 224, 120), (233, 110, 160))
        yell = ((255, 205, 60), (228, 90, 30), (214, 165, 30))
        greet = "".join(chr(c) for c in (
            67, 104, 250, 99, 32, 77, 7915, 110, 103, 32,
            78, 259, 109, 32, 77, 7899, 105, 33))
        gfont = self._banner_font(int(H * 0.5), True)
        try:
            gw = d.textlength(greet, font=gfont) if gfont else int(W * 0.3)
        except Exception:
            gw = int(W * 0.3)
        cx = W // 2
        half = int(gw / 2) + int(H * 0.7)          # clear gap for the greeting
        step = int(H * 0.66)
        margin = int(H * 0.2)

        def spray(bx, k):                          # one blossom + a small leaf
            col = pink if k % 2 == 0 else yell
            lx = int(bx + H * 0.33)
            ly = bough_y(lx)
            d.ellipse([lx - int(H * 0.11), ly - int(H * 0.045),
                       lx + int(H * 0.11), ly + int(H * 0.045)], fill=green)
            blossom(bx, *col)
        k, bx = 0, cx + half + step // 2           # right side, outward
        while bx < W - margin:
            spray(bx, k); bx += step; k += 1
        k, bx = 0, cx - half - step // 2           # left side, mirrors right
        while bx > margin:
            spray(bx, k); bx -= step; k += 1
        self._banner_text(d, (cx, int(H * 0.52)), greet, gfont,
                          (255, 216, 92), stroke=max(2, int(H * 0.045)),
                          stroke_fill=(120, 8, 8))

    def _bimg_christmas(self, d, W, H):
        # candy-cane ribbon with a cream plaque reading "Merry Christmas!",
        # flanked by holly sprigs, snow dots scattered on the stripes.
        d.rectangle([0, 0, W, H], fill=(245, 246, 248))
        dx = int(H * 0.8)
        red, green = (200, 16, 46), (31, 138, 76)
        barw, period = int(H * 0.5), int(H * 1.05)
        i, x = 0, -dx - 2 * period
        while x < W + period:
            d.polygon([(x, H), (x + dx, 0), (x + dx + barw, 0), (x + barw, H)],
                      fill=[red, green][i % 2])
            x += period
            i += 1
        for (fx, fy) in ((0.07, 0.3), (0.15, 0.72), (0.9, 0.34),
                         (0.83, 0.72), (0.7, 0.2)):
            r = int(H * 0.045)
            sx, sy = int(W * fx), int(H * fy)
            d.ellipse([sx - r, sy - r, sx + r, sy + r], fill=(255, 255, 255))
        fnt = self._banner_font(int(H * 0.42), True)
        txt = "Merry Christmas!"
        try:
            tw = d.textlength(txt, font=fnt) if fnt else int(W * 0.3)
        except Exception:
            tw = int(W * 0.3)
        pad = int(H * 0.55)
        cx = W // 2
        px0, px1 = cx - int(tw // 2) - pad, cx + int(tw // 2) + pad
        d.rounded_rectangle([px0, int(H * 0.14), px1, int(H * 0.86)],
                            radius=int(H * 0.16), fill=(250, 246, 235),
                            outline=(198, 158, 66), width=max(1, int(H * 0.03)))

        def holly(hx):
            hy = H // 2
            for sgn in (-1, 1):
                d.ellipse([hx - int(H * 0.11), hy + sgn * int(H * 0.0) -
                           int(H * 0.05), hx + int(H * 0.11),
                           hy + int(H * 0.05)], fill=green)
            for bx in (-1, 0, 1):
                d.ellipse([hx + bx * int(H * 0.05) - int(H * 0.028),
                           hy + int(H * 0.05), hx + bx * int(H * 0.05) +
                           int(H * 0.028), hy + int(H * 0.05) +
                           int(H * 0.056)], fill=(200, 16, 46))
        holly(px0)
        holly(px1)
        self._banner_text(d, (cx, H // 2), txt, fnt, (200, 16, 46))

    def _bimg_newmexico(self, d, W, H):
        # Breaking Bad: a dark New Mexico desert night -- stars, a hazmat
        # green/gold horizon, a layered mesa skyline, scattered periodic-tile
        # texture, and the "Br" (35) / "Ba" (56) tiles that spell the title.
        for yy in range(H):
            f = yy / float(H - 1)
            d.line([(0, yy), (W, yy)], fill=(int(24 + 28 * f),
                   int(18 + 18 * f), int(11 + 10 * f)))
        # stars
        for (fx, fy, r) in ((0.5, 0.15, 1), (0.58, 0.3, 1), (0.66, 0.12, 2),
                            (0.72, 0.34, 1), (0.8, 0.2, 1), (0.87, 0.12, 2),
                            (0.92, 0.3, 1), (0.55, 0.42, 1), (0.78, 0.46, 1),
                            (0.95, 0.18, 1), (0.63, 0.23, 1), (0.85, 0.42, 1)):
            sx, sy = int(W * fx), int(H * fy)
            d.ellipse([sx - r, sy - r, sx + r, sy + r], fill=(206, 220, 186))
        hz = int(H * 0.7)
        # green hazmat haze fading up into the sky
        band = int(H * 0.16)
        for yy in range(hz - band, hz):
            a = 1 - (hz - yy) / float(band)
            d.line([(0, yy), (W, yy)], fill=(int(22 + 46 * a), int(44 + 78 * a),
                   int(20 + 34 * a), int(150 * a)))
        d.rectangle([0, hz, W, hz + max(1, int(H * 0.03))], fill=(198, 180, 66))
        # layered mesa skyline (far, then near)
        d.polygon([(0, H), (int(W * 0.55), int(H * 0.82)),
                   (int(W * 0.62), int(H * 0.74)), (int(W * 0.78), int(H * 0.74)),
                   (int(W * 0.85), int(H * 0.82)), (W, int(H * 0.8)), (W, H)],
                  fill=(30, 30, 20))
        d.polygon([(0, H), (0, int(H * 0.86)), (int(W * 0.12), int(H * 0.86)),
                   (int(W * 0.17), int(H * 0.72)), (int(W * 0.34), int(H * 0.72)),
                   (int(W * 0.4), int(H * 0.86)), (int(W * 0.66), int(H * 0.86)),
                   (int(W * 0.72), int(H * 0.8)), (W, int(H * 0.8)), (W, H)],
                  fill=(24, 24, 14))
        # scattered faint periodic tiles (texture on the right)
        ftiny = self._banner_font(int(H * 0.16), True)
        for (ex, ey, sym) in ((0.7, 0.3, "Cl"), (0.8, 0.5, "P"),
                              (0.88, 0.26, "Se"), (0.94, 0.48, "Na"),
                              (0.75, 0.15, "H"), (0.6, 0.52, "O")):
            tx, ty2, ts = int(W * ex), int(H * ey), int(H * 0.2)
            d.rectangle([tx - ts // 2, ty2 - ts // 2, tx + ts // 2,
                         ty2 + ts // 2], outline=(66, 96, 52), width=1)
            self._banner_text(d, (tx, ty2), sym, ftiny, (98, 132, 74))
        # the two title tiles -- the show's logo
        fnum = self._banner_font(int(H * 0.15), True)
        fsym = self._banner_font(int(H * 0.4), True)
        fname = self._banner_font(int(H * 0.12), True)
        tw, th = int(H * 0.76), int(H * 0.86)
        ty, gap, x0 = (H - th) // 2, int(H * 0.14), int(H * 0.4)
        pale = (232, 242, 214)

        def tile(x, num, sym, name):
            d.rounded_rectangle([x, ty, x + tw, ty + th], radius=int(th * 0.1),
                                fill=(95, 142, 60), outline=(58, 94, 36),
                                width=max(1, int(H * 0.02)))
            d.rounded_rectangle([x + int(tw * 0.08), ty + int(th * 0.06),
                                 x + int(tw * 0.92), ty + int(th * 0.22)],
                                radius=int(th * 0.06), fill=(112, 160, 74))
            self._banner_text(d, (x + int(tw * 0.17), ty + int(th * 0.14)),
                              num, fnum, pale, anchor="lm")
            self._banner_text(d, (x + tw // 2, ty + int(th * 0.53)), sym,
                              fsym, pale)
            self._banner_text(d, (x + tw // 2, ty + th - int(th * 0.12)),
                              name, fname, (206, 224, 184), anchor="ms")
        tile(x0, "35", "Br", "Bromine")
        tile(x0 + tw + gap, "56", "Ba", "Barium")

    def _bimg_synthwave(self, d, W, H):
        # retro sunset gradient with a banded rising sun
        top, bot = (242, 46, 158), (255, 148, 30)
        for yy in range(H):
            f = yy / float(H - 1)
            d.line([(0, yy), (W, yy)],
                   fill=tuple(int(top[k] * (1 - f) + bot[k] * f)
                              for k in range(3)))
        scx, scy, sr = W // 2, int(H * 1.02), int(H * 0.82)
        d.ellipse([scx - sr, scy - sr, scx + sr, scy + sr], fill=(255, 224, 96))
        for cf in (0.52, 0.66, 0.79, 0.9):
            yy = int(scy - sr + 2 * sr * cf)
            band = tuple(int(top[k] * (1 - cf) + bot[k] * cf) for k in range(3))
            d.rectangle([scx - sr, yy, scx + sr, yy + max(1, int(H * 0.05))],
                        fill=band)

    def _collapsible_card(self, card, key):
        """Make a left-panel card collapsible: clicking its title header
        toggles (drawn caret at the END of the title); state persists in
        settings[key]. Returns the frame the builder should pack the
        card content into."""
        wrap = ttk.Frame(card.body)
        wrap.pack(fill="both", expand=True)
        header = card._title
        # caret FIRST, the Quick Access position: on a card whose title
        # already opens with a glyph marker, a trailing caret read as a
        # third unrelated symbol
        _was = list(header.winfo_children())
        caret = self._lbl(header, text="")
        if _was:
            caret.pack(side="left", padx=(0, 4), before=_was[0])
        else:
            caret.pack(side="left", padx=(0, 4))
        d = getattr(self, "_ccards", None)
        if d is None:
            d = self._ccards = {}
        d[key] = {"card": card, "wrap": wrap, "caret": caret}
        for w in [header] + list(header.winfo_children()):
            w.configure(cursor="hand2")
            w.bind("<Button-1>", lambda e, k=key: self._card_toggle(k))
        if self.settings.get(key):
            self.root.after_idle(lambda k=key: self._card_toggle(k, True))
        else:
            self.root.after_idle(lambda k=key: self._card_caret(k))
        return wrap

    def _card_toggle(self, key, collapse=None):
        rec = getattr(self, "_ccards", {}).get(key)
        if not rec:
            return
        wrap, card = rec["wrap"], rec["card"]
        shown = bool(wrap.winfo_manager())
        want = shown if collapse is None else collapse
        if want and shown:
            wrap.pack_forget()
        elif not want and not shown:
            wrap.pack(fill="both", expand=True)
        collapsed = not bool(wrap.winfo_manager())
        try:
            card.body.configure(height=1 if collapsed else 0)
            if card.grow != "x":
                # an expanding card must also stop absorbing pane space
                if collapsed:
                    card.pack_configure(expand=False, fill="x")
                    card.configure(height=card._top_inset() + card.pad)
                else:
                    card.pack_configure(expand=True, fill="both")
                    card.configure(height=1)
            card._refresh()
        except tk.TclError:
            pass
        self.settings[key] = collapsed
        self._card_caret(key)
        self._save_settings()

    def _card_caret(self, key):
        rec = getattr(self, "_ccards", {}).get(key)
        if not rec:
            return
        ic = getattr(self, "_icons", {})
        img = ic.get("caret_closed" if self.settings.get(key)
                     else "caret_open")
        try:
            if img is not None:
                rec["caret"].configure(image=img)
        except tk.TclError:
            pass

    def _toggle_qa(self, collapse=None):
        """Collapse / expand the Quick Access card; the title stays on the
        border as the click target. Persists in settings."""
        w = getattr(self, "_qa_wrap", None)
        if w is None:
            return
        shown = bool(w.winfo_manager())
        want_collapse = shown if collapse is None else collapse
        if want_collapse and shown:
            w.pack_forget()
        elif not want_collapse and not shown:
            w.pack(fill="x")
        collapsed = not bool(w.winfo_manager())
        card = getattr(self, "_qa_card", None)
        if card is not None:
            try:
                # an EMPTY frame keeps its last requested size, so pin the
                # body to 1px when collapsed / natural when expanded and
                # re-fit the card -- the notebook below gets the room back
                card.body.configure(height=1 if collapsed else 0)
                card._refresh()
            except tk.TclError:
                pass
        self.settings["qa_collapsed"] = collapsed
        self._qa_caret()
        self._save_settings()

    def _qa_caret(self):
        """Show the QA collapse state with the drawn caret icons."""
        t = getattr(self, "_qa_title", None)
        if t is None:
            return
        ic = getattr(self, "_icons", {})
        img = ic.get("caret_closed" if self.settings.get("qa_collapsed")
                     else "caret_open")
        try:
            if img is not None:
                t.configure(image=img, compound="left", padx=4)
        except tk.TclError:
            pass

    def _toggle_dark(self):
        # A session or a project written before v1.4.9 R9a can still
        # name a retired Dyslexic theme. Map it here, the one choke
        # point every theme write passes through, and the write
        # re-enters with a live key and the dyslexia-friendly font.
        _live = ui_prefs.live_theme(self.theme_mode.get())
        if _live != self.theme_mode.get():
            self.settings["app_font"] = ui_prefs.RETIRED_THEMES[
                self.theme_mode.get()][1]
            try:
                self.app_font.set(self.settings["app_font"])
            except (AttributeError, tk.TclError):
                pass
            self.theme_mode.set(_live)
            return
        self._theming = True
        try:
            self._toggle_dark_inner()
        except Exception as e:
            # a mid-switch failure used to die silently in the var trace
            # and leave the app half-themed (unreadable fields)
            try:
                self._logline("! theme switch failed midway: %r" % e)
            except Exception:
                pass
        finally:
            self._theming = False
            try:
                self._pin_field_styles()   # ALWAYS the final act
            except Exception:
                pass

    def _toggle_dark_inner(self):
        self._init_theme()
        self._center_titles()
        self._recolor_tk()
        self._draw_rainbow_banner()
        self._apply_brand()
        self.settings["theme"] = self.theme_mode.get()
        self.settings["dark"] = self.dark_mode.get()
        self._save_settings()
        self._log_action("Theme: " + self.theme_mode.get())
        self._redraw()

    def _auto_text_color(self, bg):
        """Black or white, whichever is readable on the given background."""
        from matplotlib.colors import to_rgb
        try:
            r, g, b = to_rgb(bg)
        except Exception:
            return "#f0f0f0"
        lum = 0.2126 * r + 0.7152 * g + 0.0722 * b
        return "#101010" if lum > 0.55 else "#f0f0f0"

    def _axis_text_colors(self, fg):
        """(axis/spine color, tick+label text color) honoring user overrides.
        'auto' contrasts with the actual plot background (luminance-based)."""
        from matplotlib.colors import to_rgb
        try:
            auto = self._auto_text_color(self._mpl_colors()[0])
        except Exception:
            auto = fg
        def res(var):
            v = var.get() if var is not None else "auto"
            if v == "auto":
                return auto
            try:
                to_rgb(v); return v
            except Exception:
                return auto
        return (res(getattr(self, "axis_color", None)),
                res(getattr(self, "text_color", None)))

    def _page_dark(self):
        """True when the EFFECTIVE plot page is dark (theme bg on + a dark
        theme). Pane/grid auto-shades must key on the page, not the theme:
        a dark accent theme with 'theme bg' off has a WHITE page."""
        try:
            from matplotlib.colors import to_rgb
            r, g, b = to_rgb(self._mpl_colors()[0])
            return (0.2126 * r + 0.7152 * g + 0.0722 * b) < 0.5
        except Exception:
            return bool(self.dark_mode.get())

    def _mpl_colors(self):
        u, f, _fl, _pb, _pf = self._theme_palette()
        if (getattr(self, "plot_theme_bg", None) is not None
                and self.plot_theme_bg.get()):
            return (u, f)               # match the interface theme, any theme
        return ("white", "#1c2530")     # classic white page + dark text

    # ---- action log + undo/redo ------------------------------------------
    def _log_action(self, msg):
        if not getattr(self, "_action_log_on", False):
            return
        if hasattr(self, "log"):
            self._logline("  . " + msg)

    def _snapshot(self):
        try:
            snap = {k: v.get() for k, v in self._preset_registry().items()}
            snap["_smooth"] = dict(self.smooth_params)
            snap["_traces"] = {k: v.get() for k, v in self.trace_vars.items()}
            snap["_dvars"] = {k: v.get() for k, v in self.dvars.items()}
            return snap
        except Exception:
            return None

    def _push_undo(self, label=""):
        if self._restoring:
            return
        snap = self._snapshot()
        if snap is None:
            return
        if self._undo_stack and self._undo_stack[-1][1] == snap:
            return
        if self._undo_stack and label != "initial":
            self._log_changes(self._undo_stack[-1][1], snap)
        self._undo_stack.append((label, snap))
        if len(self._undo_stack) > 80:
            self._undo_stack.pop(0)
        self._redo_stack.clear()
        self._update_undo_buttons()

    _LOG_NAMES = {
        "wf_mode": "Stacked & 3D", "mode": "plot mode",
        "cmap": "colormap",
        "cmap_rev": "reverse cmap", "xunit": "x unit", "ydata": "overlay Y",
        "theme_mode": "theme", "aspect_mode": "aspect", "wf3d_alpha": "fill opacity",
        "wf3d_elev": "elev", "wf3d_azim": "azim", "wf3d_zoom": "zoom",
        "lw": "line width", "autoscale": "auto-limits", "tick_dir": "tick dir",
        "legend_on": "legend", "colorbar_on": "colorbar", "grid_on": "grid",
        "show_smooth": "show smoothed", "show_notch": "defringe",
        "active_qty": "active quantity",
    }

    def _log_changes(self, a, b):
        changed = []
        for k, v in b.items():
            if k in ("_traces", "_dvars", "_smooth"):
                continue
            if a.get(k) != v:
                nm = self._LOG_NAMES.get(k, k)
                changed.append("%s -> %s" % (nm, v))
        if a.get("_traces") != b.get("_traces"):
            n = sum(1 for x in b.get("_traces", {}).values() if x)
            changed.append("traces shown=%d" % n)
        if a.get("_smooth") != b.get("_smooth"):
            changed.append("smoothing params")
        for c in changed[:5]:
            self._log_action(c)

    def _restore(self, snap):
        self._restoring = True
        try:
            reg = self._preset_registry()
            for k, v in reg.items():
                if k in snap:
                    try:
                        v.set(snap[k])
                    except Exception:
                        pass
            if "_smooth" in snap:
                self.smooth_params.update(snap["_smooth"]); self.smooth_cache.clear()
            for k, val in snap.get("_traces", {}).items():
                if k in self.trace_vars:
                    self.trace_vars[k].set(val)
            for k, val in snap.get("_dvars", {}).items():
                if k in self.dvars:
                    self.dvars[k].set(val)
        finally:
            self._restoring = False
        self._sync_decomp_row()
        self._redraw()

    def _undo(self):
        if len(self._undo_stack) < 2:
            return
        cur = self._undo_stack.pop()
        self._redo_stack.append(cur)
        self._restore(self._undo_stack[-1][1])
        self._logline("  < undo: " + (cur[0] or "change"))
        self._update_undo_buttons()

    def _redo(self):
        if not self._redo_stack:
            return
        label, snap = self._redo_stack.pop()
        self._undo_stack.append((label, snap))
        self._restore(snap)
        self._logline("  > redo: " + (label or "change"))
        self._update_undo_buttons()

    def _update_undo_buttons(self):
        try:
            self.undo_btn.config(state=("normal" if len(self._undo_stack) > 1
                                        else "disabled"))
            self.redo_btn.config(state=("normal" if self._redo_stack
                                        else "disabled"))
        except Exception:
            pass

    # ---- multi-tab sessions ----------------------------------------------
    # A "tab" is NOT a duplicate widget tree; it is a stored session state
    # swapped into the single shared UI. The snapshot machinery (used by
    # presets and undo) already serializes every registered control; a
    # session adds the data (results), the per-tab folders, caches, and
    # undo/redo stacks. Theme stays global (it is not in the registry).
    def _capture_session(self, name):
        """Snapshot the live app state into a session dict (holds live refs
        to the mutable objects, which is correct: each session owns distinct
        list/dict objects created at _new_session time)."""
        return {
            "name": name,
            "results": self.results,
            "in_dir": self.in_var.get(),
            "out_dir": self.out_var.get(),
            "last_out_dir": self.last_out_dir,
            "snapshot": self._snapshot(),
            "undo": self._undo_stack,
            "redo": self._redo_stack,
            "smooth_cache": self.smooth_cache,
            "notch_cache": self.notch_cache,
            "nt_cache": self._nt_cache,
            "smooth_params": dict(self.smooth_params),
            "run_state": getattr(self, "_last_run_state",
                                 ("Ready", "#2a8a4a")),
            "skipped_count": getattr(self, "_skipped_count", 0),
        }

    def _store_active(self):
        """Write the live state back into the active session (keeps name)."""
        if not getattr(self, "sessions", None):
            return
        nm = self.sessions[self.active]["name"]
        self.sessions[self.active] = self._capture_session(nm)

    def _apply_session_snapshot(self, snap):
        """Apply a control snapshot WITHOUT clearing per-tab caches (unlike
        _restore, which undo/redo use). Assumes trace_vars already rebuilt."""
        if not snap:
            return
        reg = self._preset_registry()
        for k, v in reg.items():
            if k in snap:
                try:
                    v.set(snap[k])
                except Exception:
                    pass
        if "_smooth" in snap:
            self.smooth_params = dict(snap["_smooth"])
        for k, val in snap.get("_traces", {}).items():
            if k in self.trace_vars:
                self.trace_vars[k].set(val)
        for k, val in snap.get("_dvars", {}).items():
            if k in self.dvars:
                self.dvars[k].set(val)
        self._sync_decomp_row()

    def _tab_load(self, i):
        """Swap session i into the live UI (theme stays global)."""
        s = self.sessions[i]
        self._restoring = True
        try:
            self.results = s["results"]
            self.smooth_cache = s.get("smooth_cache", {})
            self.notch_cache = s.get("notch_cache", {})
            self._nt_cache = s.get("nt_cache", {})
            self._surf_cache = {}      # per-session traces: start empty
            self.smooth_params = dict(s.get("smooth_params",
                                            smoothing.DEFAULTS))
            self.last_out_dir = s.get("last_out_dir")
            self._skipped_count = s.get("skipped_count", 0)
            self._undo_stack = s.get("undo", [])
            self._redo_stack = s.get("redo", [])
            self.in_var.set(s.get("in_dir", ""))
            self.out_var.set(s.get("out_dir", ""))
            self._hide_raw_banner()
            self._build_trace_checks()
            self._apply_session_snapshot(s.get("snapshot"))
            disp = self._refresh_inspect_values()
            if disp and self.inspect_p.get() not in disp:
                self.inspect_p.set(disp[0])
        finally:
            self._restoring = False
        self.active = i
        self._update_undo_buttons()
        st = s.get("run_state")
        if st:
            self._set_run_state(*st)
        self._redraw()
        self._update_status()
        self._sync_tabs()
        self._refresh_drawer()   # follow the active tab if the drawer is open

    def _switch_session(self, i):
        if not (0 <= i < len(self.sessions)) or i == self.active:
            return
        if self._run_busy():
            return
        self._store_active()
        self._tab_load(i)

    def _new_session(self, name=None, activate=True):
        """Append a blank session with default controls; return its index."""
        if self._run_busy():
            return self.active
        self._store_active()
        name = name or self._unique_session_name()
        self._restoring = True
        try:
            self.results = []
            self.smooth_cache = {}
            self.notch_cache = {}
            self._nt_cache = {}
            self._surf_cache = {}
            self.smooth_params = dict(smoothing.DEFAULTS)
            self.last_out_dir = None
            self._skipped_count = 0
            self._undo_stack = []
            self._redo_stack = []
            self.in_var.set("")
            self.out_var.set("")
            self._hide_raw_banner()
            reg = self._preset_registry()
            for k, val in self._defaults.items():
                if k in reg:
                    try:
                        reg[k].set(val)
                    except Exception:
                        pass
            self._build_trace_checks()
            self._refresh_inspect_values()
        finally:
            self._restoring = False
        self._push_undo("initial")
        self._set_run_state("Ready", "#2a8a4a")
        self.sessions.append(self._capture_session(name))
        idx = len(self.sessions) - 1
        if activate:
            self.active = idx
            self._redraw()
            self._update_status()
            self._update_undo_buttons()
        self._sync_tabs()
        return idx

    def _close_session(self, i):
        if self._run_busy() or not (0 <= i < len(self.sessions)):
            return
        if len(self.sessions) == 1:
            # closing the only tab resets it to a fresh blank session
            self.sessions = []
            self.active = 0
            self._new_session(name="Session 1", activate=True)
            return
        if i != self.active:
            del self.sessions[i]
            if i < self.active:
                self.active -= 1
            self._sync_tabs()
            return
        # closing the active tab: load a neighbor (prefer the left one)
        target = i - 1 if i > 0 else 0
        del self.sessions[i]
        target = max(0, min(target, len(self.sessions) - 1))
        self._tab_load(target)

    def _rename_session(self, i, name):
        name = (name or "").strip()
        if name and 0 <= i < len(self.sessions):
            self.sessions[i]["name"] = name[:40]
            self._sync_tabs()

    def _unique_session_name(self):
        used = {s["name"] for s in getattr(self, "sessions", [])}
        n = len(used) + 1
        while ("Session %d" % n) in used:
            n += 1
        return "Session %d" % n

    def _show_progbar(self, show):
        pb = getattr(self, "run_prog", None)
        card = getattr(self, "_progress_card", None)
        if pb is None or card is None:
            return
        try:
            if show:
                pb.pack(fill="x", pady=(0, 4), before=card)
            else:
                pb.pack_forget()
        except tk.TclError:
            pass

    def _run_busy(self):
        t = getattr(self, "_run_thread", None)
        return bool(t and t.is_alive())

    def _sync_tabs(self):
        """Redraw the tab strip if it has been built."""
        if getattr(self, "_tabbar", None) is not None:
            self._render_tabs()

    def _render_tabs(self):
        """Rebuild the browser-style tab strip from sessions/active. Built
        from plain tk widgets recolored from the theme palette each call
        (sv_ttk Card/LabelFrame would show mismatched image-fill patches)."""
        bar = getattr(self, "_tabbar", None)
        if bar is None or not getattr(self, "sessions", None):
            return
        for w in bar.winfo_children():
            w.destroy()
        uibg, fg, _fld, _pb, _pf = self._theme_palette()
        accent = self._raw_banner_accent()
        muted = "#9aa0a6" if self.dark_mode.get() else "#6b7280"
        if self.theme_mode.get() == "highcontrast":
            muted = fg
        bar.configure(bg=uibg)
        self._session_tabs = {}
        many = len(self.sessions) > 6      # compress padding when crowded
        namepad = 4 if many else 8
        for i, s in enumerate(self.sessions):
            on = (i == self.active)
            nm = s["name"]
            if len(nm) > 18:               # ellipsize long tab names
                nm = nm[:16] + "\u2026"
            tab = tk.Frame(bar, bg=uibg, cursor="hand2")
            tab.pack(side="left", padx=(0, 2))
            self._session_tabs[i] = tab
            row = tk.Frame(tab, bg=uibg); row.pack(side="top", fill="x")
            lbl = tk.Label(row, text=nm, bg=uibg,
                           fg=(fg if on else muted),
                           font=self._F(1, "bold" if on else "normal"),
                           padx=namepad, pady=3)
            lbl.pack(side="left")
            # close x: always laid out (no width jitter) but painted
            # invisible on inactive tabs until hovered
            xb = tk.Label(row, text="\u00d7", bg=uibg,
                          fg=(fg if on else uibg),
                          font=self._F(1), padx=3, cursor="hand2")
            xb.pack(side="left", padx=(0, 4))
            if not on:
                def _hov(_e, x=xb, c=muted):
                    x.config(fg=c)
                def _out(_e, x=xb, c=uibg):
                    x.config(fg=c)
                for w in (tab, row, lbl, xb):
                    w.bind("<Enter>", _hov)
                    w.bind("<Leave>", _out)
            under = tk.Frame(tab, height=2, bg=(accent if on else uibg))
            under.pack(side="top", fill="x")
            for w in (tab, row, lbl):
                w.bind("<Button-1>", lambda e, k=i: self._switch_session(k))
                w.bind("<Double-Button-1>",
                       lambda e, k=i: self._begin_rename(k))
                w.bind("<Button-2>", lambda e, k=i: self._close_session(k))
            xb.bind("<Button-1>", lambda e, k=i: self._close_session(k))
            if len(self.sessions) > 1:
                Tooltip(lbl, s["name"] + "  (double-click to rename, "
                        "middle-click to close)")
        plus = tk.Label(bar, text="+", bg=uibg, fg=fg,
                        font=self._F(4), padx=8, cursor="hand2")
        plus.pack(side="left", padx=(2, 0))
        plus.bind("<Button-1>", lambda e: self._new_session())
        Tooltip(plus, "New tab: a blank session for another run (Ctrl+T).")
        _fr = getattr(self, "_fringe", None)
        if _fr is not None:
            _fr.sync_view_switch()   # same row, same palette pass
        self._update_title()

    def _update_title(self):
        """Window title leads with the active tab's name (D1)."""
        try:
            nm = self.sessions[self.active]["name"]
        except (AttributeError, IndexError, KeyError):
            nm = ""
        generic = not nm or nm.startswith("Session ")
        self.root.title(APP_TITLE if generic else nm + "  -  " + APP_TITLE)

    def _begin_rename(self, i):
        """Inline-rename a tab: an Entry placed over the tab label."""
        if not (0 <= i < len(self.sessions)):
            return
        if i != self.active:
            self._switch_session(i)
            i = self.active
        tabf = self._session_tabs.get(i)
        bar = self._tabbar
        if tabf is None:
            return
        bar.update_idletasks()
        e = tk.Entry(bar, font=self._F(1))
        e.insert(0, self.sessions[i]["name"])
        e.select_range(0, "end")
        e.place(x=tabf.winfo_x(), y=1,
                width=max(90, tabf.winfo_width()),
                height=max(20, tabf.winfo_height() - 2))
        e.focus_set()
        done = {"v": False}

        def commit(_=None):
            if done["v"]:
                return
            done["v"] = True
            self._rename_session(i, e.get())
            e.destroy()

        def cancel(_=None):
            done["v"] = True
            e.destroy()
        e.bind("<Return>", commit)
        e.bind("<FocusOut>", commit)
        e.bind("<Escape>", cancel)

    def _cycle_tab(self, d):
        n = len(getattr(self, "sessions", []))
        if n > 1:
            self._switch_session((self.active + d) % n)
        return "break"

    # ---- settings (remember folders) -------------------------------------
    def _migrate_settings(self):
        """Rename the settings keys that renamed controls left behind, so a
        folded section stays folded and a saved default still resolves."""
        col = self.settings.get("collapsed")
        if isinstance(col, dict) and "Reference guides" in col:
            col.setdefault("Reference lines", col["Reference guides"])
            col.pop("Reference guides", None)
        if isinstance(col, dict) and "3D shape" in col:
            # v1.4.9 R2: the Export section "3D shape" is "3D Printing"
            # now (the waterfall MODE keeps the old name), so a
            # folded section stays folded across the rename.
            col.setdefault("3D Printing", col["3D shape"])
            col.pop("3D shape", None)
        if isinstance(col, dict) and "Waterfall (2D / 3D plotting)" in col:
            # v1.4.9 R9a: the Plot section is 'Stacked & 3D' now, so a
            # folded section stays folded across the rename. The
            # wf_mode setting key is untouched: this is display only.
            col.setdefault("Stacked & 3D",
                           col["Waterfall (2D / 3D plotting)"])
            col.pop("Waterfall (2D / 3D plotting)", None)
        _so = self.settings.get("section_order")
        if isinstance(_so, dict):
            for _cat, _seq in list(_so.items()):
                if isinstance(_seq, list):
                    _seq = ["Stacked & 3D"
                            if _k == "Waterfall (2D / 3D plotting)"
                            else _k for _k in _seq]
                    # v1.5.0: a saved order written before Data files
                    # existed does not name it, and _reorder_sections packs
                    # what a saved order does not know AFTER everything it
                    # does -- which put the section below 3D Printing on
                    # every build that had ever dragged a section. Give it
                    # its factory slot, right after Export.
                    if "Export" in _seq and "Data files" not in _seq:
                        _seq.insert(_seq.index("Export") + 1, "Data files")
                    _so[_cat] = _seq
        # v1.4.9 R9a: the two Dyslexic themes retire. The face they
        # carried is an App-font value, so a settings file that names
        # one keeps the face and takes the nearest live palette.
        _oldth = self.settings.get("theme")
        _mig = ui_prefs.RETIRED_THEMES.get(_oldth)
        if _mig:
            self.settings["theme"] = _mig[0]
            self.settings["app_font"] = _mig[1]
        self._theme_note = ui_prefs.retired_note(_oldth)
        fp = self.settings.get("fig_preset_default")
        if fp in JOURNAL_ALIASES:
            self.settings["fig_preset_default"] = JOURNAL_ALIASES[fp]
        # d3 keys (v1.4.9 W1c) -- user furniture, exactly like the
        # collapsed states: which controls the Quick Access strip shows,
        # and each tab's dragged section order. Settings on purpose,
        # never presets (rule 30: presets carry figure state; applying a
        # journal preset must not rearrange anyone's panel).
        if not isinstance(self.settings.get("qa_visible"), list):
            self.settings["qa_visible"] = list(self.QA_DEFAULT)
        if not isinstance(self.settings.get("qa_funcs"), list):
            self.settings["qa_funcs"] = list(self.QA_FUNCS_DEFAULT)
        if not isinstance(self.settings.get("section_order"), dict):
            self.settings["section_order"] = {}
        # b keys -- fringe workbench defaults (v1.4.9). Additive and
        # versioned under the fr_ prefix, so a settings file written
        # by any earlier build still resolves.
        for _bk, _bv in fringe_panel.SETTINGS_DEFAULTS.items():
            self.settings.setdefault(_bk, _bv)
        # c keys -- the series level (v1.4.9): the per-dataset
        # decompression lists, the multiscale-variance error-bar
        # switch, and the Results-vs-pressure view's own state.
        # Additive under the same fr_ prefix, and defaulted here so
        # a settings file written before the series level existed
        # still reads.
        for _ck, _cv in fringe_panel.C_SETTINGS_DEFAULTS.items():
            self.settings.setdefault(
                _ck, (dict(_cv) if isinstance(_cv, dict)
                      else list(_cv) if isinstance(_cv, list)
                      else _cv))
        # v1.4.9 R13: the Graphics dial absorbs 'Surface detail'. The
        # old key converts once, and the log says what it became.
        self._gfx_migrated = []
        if ("wf3d_graphics" not in self.settings
                and "wf3d_surf_detail" in self.settings):
            _od = str(self.settings.pop("wf3d_surf_detail"))
            _nd = self.GFX_FROM_DETAIL.get(_od, "medium")
            self.settings["wf3d_graphics"] = _nd
            self._gfx_migrated.append(
                "Surface detail '%s' -> Graphics '%s'" % (_od, _nd))
        # v1.4.9 R14: the top notch 'rich' is called 'best'. _gfx_pick
        # reads an unknown notch as medium, so a stored value and every
        # saved preset convert here, once, and the log says so.
        _gr = str(self.settings.get("wf3d_graphics", ""))
        if _gr in self.GFX_RENAMED:
            self.settings["wf3d_graphics"] = self.GFX_RENAMED[_gr]
            self._gfx_migrated.append(
                "Graphics '%s' -> '%s'" % (_gr, self.GFX_RENAMED[_gr]))
        _pres = self.settings.get("presets")
        if isinstance(_pres, dict):
            for _pn, _pd in _pres.items():
                if not isinstance(_pd, dict):
                    continue
                _pv = str(_pd.get("wf3d_graphics", ""))
                if _pv in self.GFX_RENAMED:
                    _pd["wf3d_graphics"] = self.GFX_RENAMED[_pv]
                    self._gfx_migrated.append(
                        "Preset '%s' Graphics '%s' -> '%s'"
                        % (_pn, _pv, self.GFX_RENAMED[_pv]))
        self._migrate_defringe()
        self._migrate_apply_centers()

    def _migrate_apply_centers(self):
        """Drop the retired 'Write to defringe' snapshot.

        That button published ONE spectrum's notch centres and cutoffs into
        settings['fr_apply_centers'], and every pressure was then cleaned at
        the 20 GPa peaks. The fringe workbench holds per-trace state now and
        answers for every pressure - its own notches where it has them, its
        global controls elsewhere - so the snapshot has nothing left to say.
        An older settings file carries the key; it is dropped on load and
        nothing reads it.
        """
        self.settings.pop("fr_apply_centers", None)

    def _migrate_defringe(self):
        """Fold the retired Defringe section's values into the workbench.

        v1.4.9 R10: the standalone Defringe card is gone and the fringe
        workbench owns every defringe parameter, so a settings file
        written by an earlier build hands its four values over ONCE and
        is never read for them again. The rules:

          notch_nt_min / notch_nt_max / notch_pmax  ->  the workbench's
            own gates, verbatim (same meaning, same units).
          notch_width  ->  seeds the workbench's DEFAULT half-width once.
            It was a FRACTION of the fringe frequency and the workbench
            works in absolute +-micron, and the two only agree at one
            n*t (halfwidth_um = frac * nt_um), so the conversion is done
            at the geometric centre of the search band it was used with
            and capped at 10 um. The factory 15% is a default rather
            than a preference and is ignored; a width somebody actually
            moved is not. The exact conversion, at a trace's own
            detected centre, is what the notch list offers per centre
            afterwards.
          suppress_fringe_report  ->  fr_suppress_report, which is the
            same switch in its new home (the Detection card on the
            Fringe panel).
          show_notch  ->  unchanged. It is still the df switch.

        An old PRESET carrying any of these keys absorbs the same way,
        for free: _apply_preset_data only sets keys that are still in
        _preset_registry, so a removed control's value is read past.
        """
        s = self.settings
        self._df_migrated = []
        if s.get("fr_defringe_migrated"):
            return

        def _num(key):
            try:
                return float(s[key])
            except (KeyError, TypeError, ValueError):
                return None

        for old, new in (("notch_nt_min", "fr_nt_min_um"),
                         ("notch_nt_max", "fr_nt_max_um"),
                         ("notch_pmax", "fr_pvalue_max")):
            v = _num(old)
            if v is not None and v > 0:
                s[new] = v
                self._df_migrated.append("Defringe %s %g -> %s" % (old, v, new))
        w = _num("notch_width")
        if (w is not None and w > 0 and abs(w - 15.0) > 1e-9
                and not s.get("fr_width_migrated")):
            mid = math.sqrt(max(float(s.get("fr_nt_min_um", 8.0)), 1e-6)
                            * max(float(s.get("fr_nt_max_um", 300.0)), 1e-6))
            hw = min(max(round(w / 100.0 * mid, 3), 0.5), 10.0)
            s["fr_halfwidth_um"] = hw
            self._df_migrated.append(
                "Defringe notch_width %g%% -> fr_halfwidth_um %g um "
                "(converted at n*t %.1f um)" % (w, hw, mid))
        s["fr_width_migrated"] = True
        if "suppress_fringe_report" in s:
            s["fr_suppress_report"] = bool(s.get("suppress_fringe_report"))
            self._df_migrated.append(
                "Defringe suppress_fringe_report -> fr_suppress_report")
        col = s.get("collapsed")
        if isinstance(col, dict):
            col.pop("Defringe", None)
        s.pop("df_adv_collapsed", None)
        s["fr_defringe_migrated"] = True

    def _load_settings(self):
        try:
            with open(SETTINGS_PATH) as f:
                return json.load(f)
        except Exception:
            return {}

    def _save_settings(self):
        try:
            self.settings.update(in_dir=self.in_var.get(),
                                 out_dir=self.out_var.get())
            # atomic write: a crash mid-write can no longer corrupt settings
            tmp = SETTINGS_PATH + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(self.settings, f, indent=2)
            os.replace(tmp, SETTINGS_PATH)
        except Exception as e:
            # never silent: surface to the log (guarded for early-init calls)
            try:
                self._logline("Could not save settings: %s" % e)
            except Exception:
                pass

    # ---- top bar (title + collapse buttons) ------------------------------
    def _build_top(self):
        top = ttk.Frame(self.root, padding=(10, 6))
        top.pack(side="top", fill="x")
        # Dark-Side-of-the-Moon prism strip; only painted for the rainbow theme
        self.rainbow_banner = tk.Canvas(self.root, height=1, highlightthickness=0,
                                        bd=0)
        self.rainbow_banner.pack(side="top", fill="x")
        self.rainbow_banner.bind("<Configure>",
                                 lambda e: self._draw_rainbow_banner())
        titles = ttk.Frame(top)
        titles.pack(side="left")
        self._titles_f = titles
        # the anvil mark (drawn per theme; image attached in _apply_brand)
        self._hdr_mark_lbl = self._lbl(titles)
        self._hdr_mark_lbl.pack(side="left", anchor="s", padx=(0, PAD_X),
                                pady=(0, 2))
        self.title_lbl = self._lbl(titles, text=BRAND["wordmark"],
                                   font=self._F(6, semi=True))
        self.title_lbl.pack(side="left", anchor="s")
        self._wm_dot = self._lbl(titles, text=BRAND["dot"],
                                 font=self._F(6, "bold", semi=True))
        self._wm_dot.pack(side="left", anchor="s")
        vchip = self._lbl(titles, text="   %s" % APP_VERSION,
                          font=self._F(1), foreground=MUTED)
        vchip.pack(side="left", anchor="s", pady=(0, 2))
        vchip.configure(cursor="hand2")
        vchip.bind("<Button-1>", lambda e: self._about())
        Tooltip(vchip, "About this build (click).")
        # icon buttons: the pane glyph says which side folds, the tooltip
        # carries the words the labels used to spell out. The bare arrow is
        # only what shows if PIL is missing and there is no icon set.
        # The pair lives together at the FAR RIGHT of the bar, in the
        # order the panels sit on screen: the left-panel control first,
        # the right-panel control outermost, so each glyph still points at
        # what it folds. Splitting them (left button parked beside the
        # wordmark) left a lone unlabelled glyph crowding the logo; Nhan
        # asked for it back on the right. Mapping and icons unchanged.
        self.right_btn = ttk.Button(top, text=">",
                                    command=self._toggle_right)
        self.right_btn.pack(side="right")
        self._right_tip = Tooltip(self.right_btn, "Hide the right panel.")
        self.left_btn = ttk.Button(top, text="<",
                                   command=self._toggle_left)
        self.left_btn.pack(side="right", padx=(0, PAD_X))
        self._left_tip = Tooltip(self.left_btn, "Hide the left panel.")
        self._sync_panel_btns()
        # Settings: one gear for the chrome a user sets once and leaves
        # alone (app font, text size, helper tips, performance mode, the
        # tutorial and About). The bar keeps what a session touches:
        # NUKE, undo / redo, Theme, and the two panel switches. Same
        # button look as the Quick Access gear, so one glyph means
        # "customize this" everywhere in the program.
        sgb = ttk.Button(top, width=2, style="Compact.TButton",
                         command=self._toggle_settings_menu)
        _sgi = getattr(self, "_icons", {}).get("gear")
        if _sgi is not None:
            sgb.configure(image=_sgi, compound="image")
        else:
            sgb.configure(text="⚙")   # pre-icon fallback at build
        sgb.pack(side="right", padx=(0, PAD_X))
        self._settings_gear_btn = sgb
        Tooltip(sgb, "Settings: app font, text size, helper tips, "
                     "performance mode, the tutorial and About.")
        # theme dropdown (Light / Dark / Black)
        thf = ttk.Frame(top); thf.pack(side="right", padx=(PAD_X, PAD_X))
        self._lbl(thf, text="Theme").pack(side="left", padx=(0, PAD_X))
        thcb = self._mapped_combo(
            thf, self.theme_mode, THEME_LABELS,
            divider=(THEME_DIVIDER, THEME_FUNCTIONAL))
        thcb.pack(side="left")
        self._theme_combo = thcb
        self._fit_theme_combo()
        # measured 400+ px of clear top bar at the default width; the
        # divider row is skipped by _step_combo, and _toggle_dark already
        # writes the log line, so log=False keeps it single
        self._combo_arrows(thcb, "theme", log=False)
        Tooltip(thcb, "Interface theme. The five above the line are "
                      "the working themes: light, dark, black, and the "
                      "two accessibility themes. Everything below the "
                      "line changes colors only.")
        self.theme_mode.trace_add("write", lambda *a: self._toggle_dark())
        # The Settings panel's variables are born here, with the rest of
        # the chrome, because code outside the panel reads them long
        # before the panel is first opened. Their WIDGETS are built in
        # _build_settings_menu.
        self._ui_size_var = tk.IntVar(value=self._body_size)
        self._ui_auto_var = tk.BooleanVar(value=self._ui_font_auto)
        self._ui_size_pick = tk.StringVar(
            value=("auto" if self._ui_font_auto else str(self._body_size)))
        self.tooltips_on = tk.BooleanVar(
            value=bool(self.settings.get("tooltips_on", True)))
        Tooltip.enabled = self.tooltips_on.get()
        # undo / redo, separated from the theme controls
        urf = ttk.Frame(top); urf.pack(side="right", padx=(PAD_X, PAD_X))
        self.undo_btn = ttk.Button(urf, text="\u21b6",
                                    command=self._undo)
        self.undo_btn.pack(side="left", padx=(0, PAD_X_TIGHT))
        self.redo_btn = ttk.Button(urf, text="\u21b7",
                                    command=self._redo)
        self.redo_btn.pack(side="left")
        Tooltip(self.undo_btn, "Undo the last change (Ctrl+Z).")
        Tooltip(self.redo_btn, "Redo (Ctrl+Y).")
        # NUKE: hard session reset, centered prominently on the top bar
        # drawn like the other primaries (same 4 px corners) but keeping
        # its deliberate fixed 13 pt siren-red look; the 2 px darker edge
        # replaces the old relief="raised" bd=2
        self.nuke_btn = RoundButton(
            top, app=self, text="\u2622  NUKE", command=self._nuke,
            bg="#c0392b", fg="white", activebackground="#e74c3c",
            activeforeground="white", outline="#7d2019", outlinewidth=2,
            font=(UI_FONT, 13, "bold"), padx=12,
            pady=max(4, self._em() - 2), radius=4, matchttk=False,
            cursor="hand2")
        self.nuke_btn._tier = "nuke"
        if not hasattr(self, "_brand_btns"):
            self._brand_btns = []
        self._brand_btns.append(self.nuke_btn)
        self.nuke_btn.place(relx=0.5, rely=0.5, anchor="center")
        self.root.after(50, self._size_nuke)
        top.bind("<Configure>", lambda e: self._size_nuke())
        urf.bind("<Configure>", lambda e: self._size_nuke())
        Tooltip(self.nuke_btn,
                "Reset everything to a fresh start: clears loaded data, the plot, "
                "the folders, the log, and all controls back to defaults. Your "
                "saved presets and default colormap are kept. Asks first.")

    # ---- resizable 3-pane layout -----------------------------------------
    def _build_panes(self):
        self.pw = tk.PanedWindow(self.root, orient="horizontal", sashwidth=6,
                                 sashrelief="flat",
                                 bg=self._theme_palette()[0])
        self.pw.pack(side="top", fill="both", expand=True)

        self.left = ttk.Frame(self.pw, padding=(8, 6))
        self.center = ttk.Frame(self.pw)
        self.right_outer = ttk.Frame(self.pw, padding=(8, 6))
        self._build_left(self.left)
        self._build_center(self.center)
        self._build_right(self.right_outer)
        self._reorder_sections()
        self._init_fringe()
        self.root.after(80, self._restore_tab)

        self.pw.add(self.left, minsize=self._pane_widths()[0], width=self._pane_widths()[1], stretch="never")
        self.pw.add(self.center, minsize=400, stretch="always")
        self.pw.add(self.right_outer, minsize=self._pane_widths()[2], width=self._pane_widths()[3], stretch="never")
        self.left_shown = True
        self.right_shown = True
        self._build_sash_handles()

    # ---- drag-handle pills on the pane sashes ----------------------------
    def _build_sash_handles(self):
        """A subtle vertical pill centered on each pane sash (the sashes are
        themed invisible, so this is the only 'you can drag me' cue). The
        pill IS the handle: dragging it moves the sash. Two are enough
        (left|center and center|right)."""
        self._sash_handles = []
        for i in (0, 1):
            cv = tk.Canvas(self.root, width=13, highlightthickness=0, bd=0,
                           cursor="sb_h_double_arrow", takefocus=0)
            cv.bind("<Enter>", lambda e, c=cv: self._draw_sash_pill(c, True))
            cv.bind("<Leave>", lambda e, c=cv: self._draw_sash_pill(c, False))
            cv.bind("<ButtonPress-1>",
                    lambda e, c=cv: self._start_sash_drag(c))
            cv.bind("<B1-Motion>",
                    lambda e, idx=i: self._drag_sash(idx, e))
            cv.bind("<ButtonRelease-1>", self._end_sash_drag)
            cv.bind("<Escape>", self._cancel_sash_drag)
            cv.bind("<Double-Button-1>",
                    lambda e, idx=i: self._reset_sash(idx))
            self._sash_handles.append(cv)
        self.pw.bind("<Configure>",
                     lambda e: self.root.after_idle(self._place_sash_handles),
                     add="+")
        self.pw.bind("<ButtonRelease-1>",
                     lambda e: self.root.after_idle(self._place_sash_handles),
                     add="+")
        # backstop for the ghost: the pill has takefocus=0, so Escape only
        # reaches it while it holds the focus we hand it at drag start
        if not getattr(self, "_sash_esc_bound", False):
            self._sash_esc_bound = True
            self.root.bind("<Escape>", self._cancel_sash_drag, add="+")
        self.root.after_idle(self._place_sash_handles)

    def _perf_on(self):
        try:
            return bool(self.app_perf_mode.get())
        except (AttributeError, tk.TclError):
            return False

    def _sash_limits(self, idx):
        """(lo, hi) x the sash `idx` may take inside the paned window, from
        the panes' own minsize values. The live path needs it because a
        clamped sash_place still costs a full relayout, and the ghost path
        needs it because nothing else would stop the line."""
        try:
            panes = list(self.pw.panes())
            n = len(panes)
            if idx >= n - 1:
                return None
            mins = []
            for p in panes:
                try:
                    mins.append(int(self.pw.paneconfigure(p, "minsize")[4]))
                except (tk.TclError, ValueError, IndexError):
                    mins.append(0)
            try:
                # str(): Tk 8.6.9 hands back a Tcl_Obj here
                sw = int(str(self.pw.cget("sashwidth")))
            except (tk.TclError, ValueError):
                sw = 6
            lo = sum(mins[:idx + 1]) + sw * idx
            hi = (self.pw.winfo_width() - sum(mins[idx + 1:])
                  - sw * (n - 1 - idx))
            return (lo, max(lo, hi))
        except tk.TclError:
            return None

    def _clamp_sash(self, idx, x):
        lim = self._sash_limits(idx)
        if lim is None:
            return max(1, int(x))
        return int(max(lim[0], min(int(x), lim[1])))

    def _sash_ghost(self, x):
        """The performance-mode drag guide: a 2 px accent line spanning the
        paned window, placed in ROOT coordinates so it lands correctly with
        the window anywhere on any screen. x=None tears it down. It is a
        borderless overrideredirect strip, so it has no caption for
        _apply_titlebar to paint."""
        w = getattr(self, "_sash_ghost_win", None)
        if x is None:
            self._sash_ghost_win = None
            if w is not None:
                try:
                    w.destroy()
                except tk.TclError:
                    pass
            return
        try:
            gx = self.pw.winfo_rootx() + int(x)
            gy = self.pw.winfo_rooty()
            gh = max(8, self.pw.winfo_height())
            if w is None or not w.winfo_exists():
                w = tk.Toplevel(self.root)
                w.overrideredirect(True)
                try:
                    w.attributes("-topmost", True)
                except tk.TclError:
                    pass
                self._sash_ghost_win = w
            w.configure(bg=self._brand()["ac2"])
            w.geometry("2x%d+%d+%d" % (gh, gx, gy))
        except tk.TclError:
            self._sash_ghost_win = None

    def _start_sash_drag(self, cv=None):
        """Grab the pill: clear the throttle clock so the first motion moves
        at once, and take the focus so Escape can cancel a ghost drag."""
        self._sash_drag = None
        self._sash_last = 0.0
        if cv is not None and self._perf_on():
            try:
                cv.focus_set()
            except tk.TclError:
                pass

    def _drag_sash(self, idx, event):
        """<B1-Motion> on a sash pill.

        Default: LIVE resize, throttled to SASH_LIVE_MS. One sash_place
        relays out ~1000 widgets and resizes the matplotlib canvas, so
        doing it per motion event was the lag the dividers used to have;
        5 updates a second still reads as live.
        Performance mode: zero relayout while dragging - only the ghost
        guide moves, and the sash is placed once on release."""
        try:
            x = self._clamp_sash(idx, event.x_root - self.pw.winfo_rootx())
        except tk.TclError:
            return
        self._sash_drag = (idx, x)
        if self._perf_on():
            self._sash_ghost(x)
            return
        now = time.monotonic()
        if now - getattr(self, "_sash_last", 0.0) >= SASH_LIVE_MS / 1000.0:
            self._sash_last = now
            self._apply_sash(idx, x)

    def _apply_sash(self, idx, x):
        try:
            self.pw.sash_place(idx, max(1, int(x)), 1)
        except tk.TclError:
            return False
        self._place_sash_handles()
        return True

    def _end_sash_drag(self, _e=None):
        """<ButtonRelease-1>: drop the ghost and place the sash ONCE, so it
        always lands exactly where the cursor left it (the throttle can be
        mid-interval, and the ghost path has placed nothing at all). The
        existing debounced canvas resize then does its single redraw."""
        self._sash_ghost(None)
        drag, self._sash_drag = getattr(self, "_sash_drag", None), None
        if drag is not None:
            self._apply_sash(drag[0], drag[1])
        try:
            self.root.after_idle(self._place_sash_handles)
        except tk.TclError:
            pass

    def _cancel_sash_drag(self, _e=None):
        """Escape mid-drag: the guide line goes and nothing is applied.
        A no-op (and no "break") when no drag is running, so the shared
        root-level Escape never swallows anyone else's."""
        if (getattr(self, "_sash_drag", None) is None
                and getattr(self, "_sash_ghost_win", None) is None):
            return None
        self._sash_drag = None
        self._sash_ghost(None)
        return "break"

    def _reset_sash(self, idx):
        """Double-click a sash pill: put the pane it borders back to the
        tuned default width from _pane_widths(). Sash 0 sets the LEFT pane's
        width directly; the sash before the right pane is placed off the
        trailing edge instead, so the RIGHT pane lands on its default width
        whatever the window size. When the left pane is hidden, sash 0 IS
        the center|right sash - hence the pane-list check, not idx alone."""
        try:
            panes = [str(x) for x in self.pw.panes()]
            if idx >= max(0, len(panes) - 1):
                return
            _lmin, lw, _rmin, rw = self._pane_widths()
            try:
                # str(): Tk 8.6.9 hands back a Tcl_Obj here
                sw = int(str(self.pw.cget("sashwidth")))
            except (tk.TclError, ValueError):
                sw = 6
            if idx == 0 and panes[0] == str(self.left):
                x = lw
            else:
                x = self.pw.winfo_width() - rw - sw
            self.pw.sash_place(idx, int(max(1, x)), 1)
        except tk.TclError:
            return
        self._place_sash_handles()
        self._log_action("Reset pane width")

    def _sash_pill_colors(self):
        """(pill bg = the sash chrome, rest = muted pill, hot = brand pop)."""
        uibg, fg, _fl, _pb, _pf = self._theme_palette()
        try:
            r1, g1, b1 = self.root.winfo_rgb(uibg)
            r2, g2, b2 = self.root.winfo_rgb(fg)
            t = 0.42
            rest = "#%02x%02x%02x" % (
                int((r1 * (1 - t) + r2 * t) / 256),
                int((g1 * (1 - t) + g2 * t) / 256),
                int((b1 * (1 - t) + b2 * t) / 256))
        except tk.TclError:
            rest = "#9a9a9a"
        if self.theme_mode.get() == "highcontrast":
            rest = fg
        return uibg, rest, self._brand().get("ac3", "#C9A227")

    def _draw_sash_pill(self, cv, hot=False):
        try:
            bg, rest, hotc = self._sash_pill_colors()
            w = int(cv.cget("width")) or 13
            h = int(cv.winfo_height()) or 60
            cv.configure(bg=bg)
            cv.delete("all")
            pad = 8
            cv.create_line(w // 2, pad, w // 2, max(pad + 2, h - pad),
                           width=5 if hot else 4, capstyle="round",
                           fill=hotc if hot else rest)
        except tk.TclError:
            pass

    def _place_sash_handles(self, *_a):
        handles = getattr(self, "_sash_handles", None)
        if not handles:
            return
        try:
            n_sash = max(0, len(self.pw.panes()) - 1)
            px, py = self.pw.winfo_x(), self.pw.winfo_y()
            ph = min(104, max(64, self.pw.winfo_height() // 6))
            ptop = py + (self.pw.winfo_height() - ph) // 2
        except tk.TclError:
            return
        for i, cv in enumerate(handles):
            if i < n_sash:
                try:
                    sx, _sy = self.pw.sash_coord(i)
                except tk.TclError:
                    cv.place_forget(); continue
                cv.place(in_=self.root, x=px + sx - 5, y=ptop,
                         width=13, height=ph)
                tk.Misc.lift(cv)
                cv.configure(height=ph)
                self._draw_sash_pill(cv, False)
            else:
                cv.place_forget()

    def _toggle_left(self):
        if self.left_shown:
            self.pw.forget(self.left)
        else:
            self.pw.add(self.left, before=self.center, minsize=self._pane_widths()[0], width=self._pane_widths()[1],
                        stretch="never")
        self.left_shown = not self.left_shown
        self._sync_panel_btns()
        self.root.after_idle(self._place_sash_handles)

    def _toggle_right(self):
        if self.right_shown:
            self.pw.forget(self.right_outer)
        else:
            self.pw.add(self.right_outer, minsize=self._pane_widths()[2], width=self._pane_widths()[3], stretch="never")
        self.right_shown = not self.right_shown
        self._sync_panel_btns()
        self.root.after_idle(self._place_sash_handles)


